/* بيانات قسم qasasx: تُحمَّل عند أول فتح للقسم */
window.QASASX = {"s":[{"id":"adam","cat":"a","n":"آدم وإبليس","intro":"ابتداء خلق الإنسان واستخلافه في الأرض، وعلمه الأسماء، وسجود الملائكة له وإباء إبليس، ثم الجنة والشجرة والزلة والتوبة؛ وهي أصل العداوة بين الإنسان والشيطان وأصل الابتلاء.","eps":[{"t":"الاستخلاف وتعليم الأسماء","r":[2,30,33]},{"t":"سجود الملائكة وإباء إبليس","r":[7,11,18]},{"t":"الجنة والشجرة والتوبة","r":[7,19,25]},{"t":"عهد وُصّي به آدم فنسي","r":[20,115,122]}],"ls":[{"t":"التسليم لحكمة الله وفضل العلم","r":[2,30,33],"q":{"bk":"saadi","w":"السعدي","s":2,"ay":30,"x":"وفي هذه الآيات من العِبَر والآيات إثبات الكلام لله تعالى، وأنه لم يزل متكلماً يقول ما شاء، ويتكلم بما شاء وأنه عليم حكيم، وفيه أن العبد إذا خفيت عليه حكمة الله في بعض المخلوقات، والمأمورات؛ فالواجب عليه التسليم واتهامُ عقله والإقرار لله بالحكمة؛ وفيه اعتناء الله بشأن الملائكة وإحسانه بهم بتعليمهم ما جهلوا، وتنبيههم على ما لم يعلموه.","en":"Al-Sa'di draws lessons from the verses: that when Allah's wisdom in some creatures or commands is hidden from a servant he must submit and doubt his own reason, and the merit of knowledge."}},{"t":"الكبر أصل المعصية، وفساد قياس إبليس","r":[7,12,12],"q":{"bk":"saadi","w":"السعدي","s":7,"ay":11,"x":"أنه كَذَبَ في تفضيل مادة النار على مادة الطين والتراب؛ فإنَّ مادة الطين فيها الخشوعُ والسكونُ والرزانةُ، ومنها تظهر بركات الأرض من الأشجار وأنواع النبات على اختلاف أجناسه وأنواعه، وأما النار؛ ففيها الخفة والطيش والإحراق. {13} ولهذا؛ لما جرى من إبليس ما جرى؛ انحطَّ من مرتبته العالية إلى أسفل السافلين، فقال الله له: اهبطْ {منها} أي: من الجنة، {فما يكونُ لك أن تتكبَّرَ فيها}: لأنها دار الطيبين الطاهرين، فلا تَليقُ بأخبث خَلْق الله وأشرهم، {فاخرُجۡ إنَّك من الصاغرين}؛ أي: المهانين الأذلين؛ جزاء على كبره وعجبه بالإهانة والذل.","en":"Al-Sa'di: Iblis lied in preferring the matter of fire to clay, for clay has humility, calm and gravity and from it come the blessings of the earth; because of his pride he fell to the lowest of the low."}},{"t":"عداوة الشيطان وغلبة الشهوة على العقل","r":[7,22,22],"q":{"bk":"saadi","w":"السعدي","s":7,"ay":19,"x":"{22} فاغترَّا بذلك، وغلبت الشهوة في تلك الحال على العقل، {فدلاَّهما}؛ أي: أنزلهما عن رتبتهما العالية التي هي البعدُ عن الذنوب والمعاصي إلى التلوُّث بأوضارِها، فأقدما على أكلها، {فلمَّا ذاقا الشجرةَ بَدَتۡ لهما سوآتُهما}؛ أي: ظهرت عورة كل منهما بعدما كانت مستورةً، فصار للعري الباطن من التقوى في هذه الحال أثرٌ في اللباس الظاهر حتى انخلع، فظهرت عوراتُهما، ولما ظهرتْ عوراتُهما؛ خَجِلا وجَعَلا يخصِفان على عوراتهما من أوراق شجر الجنة ليستترا بذلك، {وناداهما ربهما}: وهما بتلك الحال ـ موبِّخاً ومعاتباً ـ: {ألم أنۡهَكُما عن تلكما الشجرةِ وأقل لكما إنَّ الشيطان لكما عدوٌّ مبينٌ}: فَلِمَ اقترفتُما المنهيَّ وأطعتما عدوَّكما؟!","en":"Al-Sa'di: they were deceived, desire overcame reason in that moment, and so Satan brought them down from their high rank."}},{"t":"التوبة بالاعتراف وسؤال المغفرة","r":[7,23,23],"q":{"bk":"saadi","w":"السعدي","s":7,"ay":19,"x":"{23} فحينئذٍ مَنَّ الله عليهما بالتوبة وقَبولها، فاعترفا بالذنب، وسألا من الله مغفرتَه، فقالا:{ربَّنا ظَلمۡنا أنفُسَنا وإن لم تغفرۡ لنا وترحَمۡنا لَنَكونَنَّ من الخاسرينَ}؛ أي: قد فعلنا الذنب الذي نبَّهتنا عنه وأضررنا بأنفسنا باقتراف الذنب، وقد فعلنا سببَ الخسار إن لم تغفرْ لنا بمحو أثر الذنب وعقوبته وترحَمْنا بقَبول التوبة والمعافاة من أمثال هذه الخطايا، فغفر الله لهما ذلك، وعصى آدمُ ربَّه فغوى. ثم اجتباه ربُّه فتاب عليه وهَدَى. هذا وإبليس مستمرٌّ على طغيانِهِ، غير مقلع من عصيانه؛ فمن أشبه آدم بالاعتراف وسؤال المغفرة والندم والإقلاع إذا صدرت منه الذُّنوب؛ اجتباهُ ربُّه وهداه، ومن أشبهَ إبليس إذا صدر منه الذنبُ لا يزالُ يزدادُ من المعاصي؛ فإنه لا يزداد من الله إلا بعداً.","en":"Al-Sa'di: Allah granted them repentance; they confessed their sin and asked His forgiveness; whoever resembles Adam in confession, regret and giving up the sin is guided, while Iblis persists."}},{"t":"النسيان وضعف العزم من طبع الإنسان","r":[20,115,115],"q":{"bk":"saadi","w":"السعدي","s":20,"ay":115,"x":"{115} أي: ولقد وصَّينا آدم وأمرناه وعَهِدْنا إليه عهداً ليقوم به، فالتزَمَه وأذعن له وانقادَ وعزمَ على القيام به، ومع ذلك نَسِيَ ما أُمِرَ به، وانتقضت عزيمتُه المحكمة، فجرى عليه ما جرى، فصار عبرةً لذرِّيَّته، وصارت طبائعُهم مثل طبيعة آدم؛ نسي فنسيت ذُرِّيَّتُه، وخَطِئ فخطئوا، ولم يثبت على العزم المؤكَّد وهم كذلك، وبادر بالتوبة من خطيئته، وأقرَّ بها، واعترفَ فغُفِرَتْ له، ومن يشابِهْ أباه فما ظلم.","en":"Al-Sa'di: Adam was commanded and covenanted with, yet he forgot and his resolve broke; he became a lesson for his offspring, whose natures are like his."}}],"ctx":{"bk":"ibnkathir","w":"ابن كثير","s":2,"ay":30,"x":"يُخْبِرُ تَعَالَى بِامْتِنَانِهِ عَلَى بَنِي آدَمَ، بِتَنْوِيهِهِ بِذِكْرِهِمْ فِي الْمَلَأِ الْأَعْلَى قَبْلَ إِيجَادِهِمْ، فَقَالَ تَعَالَى: ﴿وَإِذْ قَالَ رَبُّكَ لِلْمَلائِكَةِ﴾ أَيْ: وَاذْكُرْ يَا مُحَمَّدُ إِذْ قَالَ رَبُّكَ لِلْمَلَائِكَةِ، وَاقْصُصْ عَلَى قَوْمِكَ ذَلِكَ.","en":"Ibn Kathir: Allah informs of His favour upon the children of Adam by honouring their mention in the highest assembly before their creation, saying \"And when your Lord said to the angels...\""}},{"id":"nuh","cat":"a","n":"نوح وقومه والطوفان","intro":"أول الرسل إلى أهل الأرض بعد ما ظهر الشرك؛ لبث في قومه ألف سنة إلا خمسين عاماً، يدعوهم ليلاً ونهاراً سراً وجهراً، فلم يؤمن معه إلا قليل، ثم أمره الله بصنع السفينة فكان الطوفان، وفيه دعاؤه لابنه وبيان الله له.","eps":[{"t":"دعوة ليلاً ونهاراً","r":[71,5,12]},{"t":"الملأ وحجتهم الواهية","r":[11,25,31]},{"t":"السفينة والطوفان","r":[11,36,41]},{"t":"دعاء نوح لابنه","r":[11,42,47]},{"t":"ألف سنة إلا خمسين عاماً","r":[29,14,15]}],"ls":[{"t":"الصبر الطويل على الدعوة لا يفتر","r":[29,14,14],"q":{"bk":"saadi","w":"السعدي","s":29,"ay":14,"x":"{14} يخبر تعالى عن حكمِهِ وحكمتِهِ في عقوبات الأمم المكذِّبة، وأنَّ الله أرسل عبده ورسوله نوحاً عليه [الصلاة و] السلام إلى قومه يدعوهم إلى التوحيد وإفراد الله بالعبادةِ والنهي عن الأنداد والأصنام، {فَلَبِثَ فيهم}: نبيًّا داعياً {ألفَ سنة إلاَّ خمسينَ عاماً}: وهو لا يني بدعوتِهِم ولا يفتُرُ في نصحهم؛ يدعوهم ليلاً ونهاراً وسرًّا وجهاراً، فلم يرشُدوا ولا اهتدوا بل استمرُّوا على كفرهم وطغيانهم، حتى دعا عليهم نبيُّهم نوحٌ عليه الصلاة والسلام مع شدَّة صبرِهِ وحلمه واحتماله، فقال:{ربِّ لا تَذَرۡ على الأرض من الكافرين دياراً}، {فأخَذَهُمُ الطوفانُ}؛ أي: الماء الذي نزل من السماء بكثرةٍ ونَبَعَ من الأرض بشدَّةٍ، {وهم ظالمونَ}؛ مستحقُّون للعذاب.","en":"Al-Sa'di: Allah sent Nuh to call to tawhid; he stayed a thousand years less fifty without ceasing his call or tiring in his counsel."}},{"t":"من عاند الحق لا يزيده الدعاء إلا فراراً","r":[71,6,6],"q":{"bk":"saadi","w":"السعدي","s":71,"ay":1,"x":"فلم يزِدۡهم دعائي إلاَّ فراراً}؛ أي: نفوراً عن الحقِّ وإعراضاً، فلم يبق لذلك فائدةٌ؛ لأنَّ فائدة الدَّعوة أن يحصل جميع المقصود أو بعضه، {وإنِّي كلَّما دعوتُهم لتغفرَ لهم}؛ أي: لأجل أن يستجيبوا؛ فإذا استجابوا؛ غفرتَ لهم، وهذا محضُ مصلحتهم، ولكن أبوا إلاَّ تمادياً على باطلهم ونفوراً عن الحقِّ، {جعلوا أصابِعَهم في آذانهم}؛ حَذَرَ سماع ما يقول لهم نبيُّهم نوحٌ عليه السلام، {واستَغۡشَوا ثيابَهم}؛ أي: تغطوا بها غطاءً يغشاهم بعداً عن الحقِّ وبغضاً له، {وأصرُّوا}: على كفرهم وشرِّهم، {واستَكۡبَروا}: على الحقِّ {استِكۡباراً}: فشرهم ازداد وخيرهم بعد.","en":"Al-Sa'di: Nuh says his calling increased them only in aversion; the benefit of calling is that all or some of its purpose be achieved."}},{"t":"الاستدلال على الحق بقلة الأتباع جهل","r":[11,29,29],"q":{"bk":"saadi","w":"السعدي","s":11,"ay":25,"x":"{ولكنِّي أراكم قوماً تجهلون}: حيث تأمرونني بطرد أولياء الله وإبعادهم عنِّي، وحيث رددتُم الحقَّ لأنهم أتباعه، وحيث استدللتم على بطلان الحقِّ بقولكم: إني بشرٌ مثلكم، وإنَّه ليس لنا عليكم من فضل.","en":"Al-Sa'di: Nuh tells them they are a people who are ignorant: they order him to drive away the friends of Allah, reject the truth because of its followers, and argue that he is only a man like them."}},{"t":"الأخذ بالأسباب مع ذكر الله: «بسم الله مجراها»","r":[11,41,41],"q":{"bk":"saadi","w":"السعدي","s":11,"ay":25,"x":"{41}{وقال} نوحٌ لمن أمره الله أن يحمِلَهم: {ارۡكَبوا فيها بسم الله مَجۡريها ومُرۡساها}؛ أي: تجري على اسم الله وترسي [على اسم الله وتجري] بتسخيره وأمره.","en":"Al-Sa'di: Nuh said, \"Embark in it; in the name of Allah is its course and its anchorage,\" that is, it sails and anchors in Allah's name by His subjection and command."}},{"t":"لا تنفع القرابة مع الكفر، والنبي يرجع إذا بُيّن له","r":[11,46,46],"q":{"bk":"saadi","w":"السعدي","s":11,"ay":25,"x":"{46} فقال اللهُ له: {إنَّه ليس من أهلك}: الذين وعدتُك بإنجائهم، {إنَّه عملٌ غيرُ صالح}؛ أي: هذا الدُّعاء الذي دعيتَ به لنجاة كافر لا يؤمنُ بالله ولا رسوله، {فلا تَسۡألۡنِ ما ليس لك به علمٌ}؛ أي: ما لا تعلم عاقبته ومآله، وهل يكون خيراً أو غير خير. {إني أعظُك أن تكونَ من الجاهلين}؛ أي: إني أعظُك وعظاً تكون به من الكاملين، وتنجو به من صفات الجاهلين. {47} فحينئذٍ ندمَ نوحٌ عليه السلام ندامةً شديدةً على ما صَدَرَ منه، و {قال ربِّ إنِّي أعوذُ بك أن أسألَكَ ما ليس لي به علمٌ وإلاَّ تَغۡفِرۡ لي وترحَمۡني أكن من الخاسرينَ}: فبالمغفرة والرحمة ينجو العبدُ من أن يكون من الخاسرين. ودلَّ هذا على أنَّ نوحاً عليه السلام لم يكنْ عندَه علمٌ بأنَّ سؤاله لربِّه في نجاة ابنه محرَّمٌ داخلٌ في قوله:{ولا تخاطِبۡني في الذين ظَلَموا إنَّهم مغرقونَ}، بل تعارض عندَه الأمران، وظنَّ دخوله في قوله:{وأهلَكَ}، وبعد هذا تبيَّن له أنَّه داخلٌ في المنهيِّ عن الدعاء لهم والمراجعة فيهم.","en":"Al-Sa'di: Allah told him the son was not of the family promised salvation; Nuh felt deep regret; he had not known that asking for a disbeliever was forbidden."}},{"t":"القصة آية: من كذّب الرسل فآخر أمره الهلاك","r":[23,30,30],"q":{"bk":"saadi","w":"السعدي","s":23,"ay":23,"x":"{30}{إنَّ في ذلك}؛ أي: في هذه القصة {لآياتٍ}: تدلُّ على أنَّ الله وحدَه المعبود، وعلى أنَّ رسوله نوحاً صادقٌ، وأنَّ قومه كاذبون، وعلى رحمة الله بعباده؛ حيث حملهم في صُلْبِ أبيهم نوح في الفلك لما غَرِقَ أهلُ الأرض، والفلك أيضاً من آيات الله؛ قال تعالى:{ولقد تَرَكۡناها آيةً فهل مِن مُدَّكِرٍ}.","en":"Al-Sa'di: in this story are signs that Allah alone is worshipped, that Nuh is truthful and his people liars, and of Allah's mercy in carrying mankind in their father's loins."}},{"t":"العاقبة للمتقين","r":[11,49,49],"q":{"bk":"saadi","w":"السعدي","s":11,"ay":25,"x":"{إنَّ العاقبةَ للمتَّقين}: الذين يتَّقون الشرك وسائر المعاصي، فستكون لك العاقبةُ على قومِكَ كما كانت لنوح على قومِهِ.","en":"Al-Sa'di: the final outcome is for those who guard against shirk and all sins; it will be yours over your people as it was Nuh's over his."}}],"ctx":{"bk":"ibnkathir","w":"ابن كثير","s":11,"ay":40,"x":"هَذِهِ مُواعدة مِنَ اللَّهِ تَعَالَى لِنُوحٍ، عَلَيْهِ السَّلَامُ، إِذَا جَاءَ أَمْرُ اللَّهِ مِنَ الْأَمْطَارِ الْمُتَتَابِعَةِ، والهَتَّان الَّذِي لَا يُقْلع وَلَا يَفتُر، بَلْ هُوَ كَمَا قَالَ تَعَالَى: ﴿فَفَتَحْنَا أَبْوَابَ السَّمَاءِ بِمَاءٍ مُنْهَمِرٍ وَفَجَّرْنَا الأرْضَ عُيُونًا فَالْتَقَى الْمَاءُ عَلَى أَمْرٍ قَدْ قُدِرَ وَحَمَلْنَاهُ عَلَى ذَاتِ أَلْوَاحٍ وَدُسُرٍ تَجْرِي بِأَعْيُنِنَا جَزَاءً لِمَنْ كَانَ كُفِرَ﴾ [الْقَمَرِ:١١ -١٤] .","en":"Ibn Kathir: this is Allah's promise to Nuh that when His command came, successive rain would fall without ceasing."}},{"id":"ibrahim","cat":"a","n":"إبراهيم الخليل","intro":"إمام الحنفاء وأبو الأنبياء: ناظر قومه في الكواكب وحطّم أصنامهم وأُلقي في النار فكانت برداً وسلاماً، وحاجّ النمرود، وهاجر، وابتُلي بكلمات فأتمّهن فجعله الله للناس إماماً، ثم ابتُلي بذبح ابنه فكان البلاء المبين.","eps":[{"t":"النظر في الكوكب والقمر والشمس","r":[6,74,79]},{"t":"تحطيم الأصنام والنار","r":[21,51,70]},{"t":"محاجّة الذي حاجّه في ربه","r":[2,258,258]},{"t":"الابتلاء بالكلمات والإمامة","r":[2,124,127]},{"t":"الذبح والبلاء المبين","r":[37,99,113]},{"t":"الضيوف والبشرى","r":[11,69,76]}],"ls":[{"t":"الحجة بالمناظرة وإبطال إلهية المخلوقات","r":[6,76,79],"q":{"bk":"saadi","w":"السعدي","s":6,"ay":74,"x":"وهذا الذي ذكرنا في تفسير هذه الآيات هو الصواب، وهو أنَّ المقامَ مقامُ مناظرةٍ من إبراهيم لقومِهِ وبيانُ بطلان إلهيَّة هذه الأجرام العلويَّة وغيرها، وأما من قال: إنه مقامُ نظرٍ في حال طفوليَّته؛ فليس عليه دليلٌ.","en":"Al-Sa'di: the correct view is that this was a debate with his people showing the falsehood of the divinity of the heavenly bodies; there is no evidence for the view that it was a search in childhood."}},{"t":"الظلم الحقيقي في عبادة الأصنام لا في كسرها","r":[21,59,59],"q":{"bk":"saadi","w":"السعدي","s":21,"ay":51,"x":"{59} فحين رأوا ما حلَّ بأصنامهم من الإهانة والخزي؛ {قالوا مَن فَعَلَ هذا بآلهتنا إنَّه لمن الظالمين}: فرَمَوا إبراهيم بالظُّلم الذي هم أولى به حيث كسَّرها، ولم يدروا أن تكسيره لها من أفضل مناقبه ومن عدلِهِ وتوحيدِهِ، وإنَّما الظالم مَنِ اتَّخذها آلهةً، وقد رأى ما يفعل بها.","en":"Al-Sa'di: they accused Ibrahim of wrong, not knowing that breaking them was among his best merits and his justice; the wrongdoer is the one who took them as gods."}},{"t":"نصر الله لخليله: كوني برداً وسلاماً","r":[21,69,69],"q":{"bk":"saadi","w":"السعدي","s":21,"ay":51,"x":"{69} فانتصر الله لخليلِهِ لمَّا ألقَوْه في النار، وقال لها:{كوني بَرۡداً وسلاماً على إبراهيم}: فكانت عليه برداً وسلاماً، لم يَنَلْهُ فيها أذى، ولا أحسَّ بمكروه.","en":"Al-Sa'di: Allah supported His friend when they threw him in the fire and said to it \"Be coolness and safety for Ibrahim,\" so it harmed him not at all."}},{"t":"الإمامة في الدين أعلى مقام يتنافس فيه العاملون","r":[2,124,124],"q":{"bk":"saadi","w":"السعدي","s":2,"ay":124,"x":"وهذه ـ لعمر الله ـ أفضل درجة تنافس فيها المتنافسون، وأعلى مقام شمر إليه العاملون، وأكمل حالة حصلها أولو العزم من المرسلين وأتباعهم من كل صِدِّيق متبع لهم داعٍ إلى الله وإلى سبيله، فلما اغتبط إبراهيم بهذا المقام، وأدرك هذا، طلب ذلك لذريته لتعلو درجته ودرجة ذريته، وهذا أيضاً من إمامته ونصحه لعباد الله ومحبته أن يكثر فيهم المرشدون، فلله عظمة هذه الهمم العالية والمقامات السامية.","en":"Al-Sa'di: this is the highest rank people compete for, the state of the resolute messengers and every truthful follower; Ibrahim, content with it, asked it for his offspring."}},{"t":"الابتلاء الذي يُظهر كمال المحبة","r":[37,106,106],"q":{"bk":"saadi","w":"السعدي","s":37,"ay":99,"x":"{106}{إنَّ هذا}: الذي امتحنَّا به إبراهيمَ عليه السلام {لهو البَلاءُ المُبينُ}؛ أي: الواضح الذي تَبَيَّنَ به صفاءُ إبراهيم وكمالُ محبَّتِهِ لربِّه وخلَّتِهِ؛ فإن إسماعيلَ عليه الصلاة (والسلام) لما وَهَبَهُ الله لإبراهيم؛ أحبَّه حبًّا شديداً، وهو خليل الرحمن، والخلَّة أعلى أنواع المحبة، وهو منصبٌ لا يقبل المشاركة، ويقتضي أن تكونَ جميعُ أجزاء القلب متعلقةً بالمحبوب، فلما تعلقتْ شعبةٌ من شُعَبِ قلبِهِ بابنه إسماعيلَ؛ أراد الله تعالى أن يُصَفِّي وُدَّه ويختبرَ خُلَّتَهَ، فأمره أن يذبح مَنْ زاحَمَ حبُّه حبَّ ربِّه، فلما قَدَّمَ حبَّ الله وآثره على هواه وعزم على ذبحِهِ وزال ما في القلب من المزاحم، بقي الذبحُ لا فائدة فيه؛ فلهذا قال:{إنَّ هذا لهو البلاءُ المبينُ}.","en":"Al-Sa'di: this is the clear trial showing Ibrahim's purity and complete love of his Lord, for he loved Ismail intensely, yet khulla, the highest love, was for Allah."}},{"t":"السلام قبل الكلام والرد بأحسن منه","r":[11,69,69],"q":{"bk":"saadi","w":"السعدي","s":11,"ay":69,"x":"ففي هذا مشروعية السلام، وأنَّه لم يزْل من ملَّة إبراهيم عليه السلام، وأنَّ السلام قبل الكلام، وأنَّه ينبغي أن يكون الردُّ أبلغَ من الابتداء؛ لأنَّ سلامهم بالجملة الفعليَّة الدالَّة على التجدُّد، وردُّه بالجملة الاسمية الدالَّة على الثُّبوت والاستمرار، وبينهما فرقٌ كبيرٌ؛ كما هو معلومٌ في علم العربية.","en":"Al-Sa'di: here is the legislation of greeting, that it is from the creed of Ibrahim, that greeting precedes speech, and that the reply should be better than the greeting."}},{"t":"دعاؤه لمكة: الأمن والرزق والذرية","r":[14,37,37],"q":{"bk":"saadi","w":"السعدي","s":14,"ay":35,"x":"{وارزُقۡهم من الثمرات لعلَّهم يشكرون}: فأجاب الله دعاءه، فصار يُجبى إليه ثمرات كل شيء؛ فإنك ترى مكة المشرفة كلَّ وقت، والثمارُ فيها متوفِّرة، والأرزاق تتوالى إليها من كل جانب.","en":"Al-Sa'di: Allah answered his prayer; the fruits of everything are brought to it, so you see Makkah always with fruit abundant and provision arriving from every side."}},{"t":"البراءة من الشرك وأهله من ملة إبراهيم","r":[60,4,4],"q":{"bk":"saadi","w":"السعدي","s":60,"ay":4,"x":"وهذه الآيات فيها النهيُ الشديد عن موالاة الكفَّار من المشركين وغيرهم وإلقاءِ المودَّةِ إليهم، وأنَّ ذلك منافٍ للإيمان ومخالفٌ لملَّة إبراهيم الخليل عليه الصلاة والسلام، ومناقضٌ للعقل الذي يوجِبُ الحذر كلَّ الحذر من العدوِّ الذي لا يُبقي من مجهوده في العداوة شيئاً وينتهز الفرصة في إيصال الضرر إلى عدوِّه.","en":"Al-Sa'di: these verses sternly forbid taking disbelievers as friends and offering them affection; this contradicts faith and the creed of Ibrahim and reason which demands caution against an enemy."}}]},{"id":"yusuf","cat":"a","n":"يوسف الصديق","intro":"«أحسن القصص»: رؤيا طفولته وحسد إخوته والجب والبيع في مصر، ثم فتنة بيت العزيز وفتنة النسوة والسجن، وتأويل الرؤيا والتمكين في الأرض، وامتحان إخوته ولقاء أبويه؛ قصة واحدة في سورة واحدة تجمع الابتلاء والصبر والعفة والعفو.","eps":[{"t":"الرؤيا ووصية يعقوب","r":[12,4,6]},{"t":"الجب والبيع","r":[12,7,20]},{"t":"بيت العزيز والمراودة","r":[12,21,29]},{"t":"النسوة والسجن","r":[12,30,42]},{"t":"رؤيا الملك والتمكين","r":[12,43,57]},{"t":"امتحان الإخوة والصواع","r":[12,58,93]},{"t":"اللقاء وتأويل الرؤيا","r":[12,94,101]}],"ls":[{"t":"كتمان ما تُخشى مضرته والبعد عن أسباب الشر","r":[12,5,5],"q":{"bk":"saadi","w":"السعدي","s":12,"ay":111,"x":"أنه ينبغي البعد عن أسباب الشرِّ وكتمانُ ما تُخشى مضرَّته؛ لقول يعقوب ليوسف:{[يا بني] لا تَقۡصُصۡ رؤياكَ على إخوتِكَ فيكيدوا لك كَيۡداً}.","en":"Al-Sa'di: one should keep away from causes of evil and conceal what is feared to be harmful, as Yaqub told Yusuf, \"Do not relate your vision to your brothers.\""}},{"t":"شؤم الذنوب: الذنب الواحد يستتبع ذنوباً","r":[12,9,9],"q":{"bk":"saadi","w":"السعدي","s":12,"ay":111,"x":"الحذر من شؤم الذنوب، وأنَّ الذنب الواحد يستتبع ذنوباً متعدِّدة، ولا يتمُّ لفاعله إلا بعدة جرائم؛ فإخوة يوسف لما أرادوا التفريق بينه وبين أبيه؛ احتالوا لذلك بأنواع من الحيل، وكذبوا عدة مراتٍ، وزوَّروا على أبيهم في القميص والدَّم الذي فيه، وفي إتيانهم عشاء يبكون، ولا تستبعدْ أنَّه قد كَثُرَ البحث فيها في تلك المدَّة، بل لعلَّ ذلك اتَّصل إلى أن اجتمعوا بيوسف، وكلما صار البحث؛ حصل من الإخبار بالكذب والافتراء ما حصل، وهذا شؤمُ الذنب وآثاره التابعة والسابقة واللاحقة.","en":"Al-Sa'di: beware of the ill effect of sins, for a single sin drags after it many sins and is not completed except through several crimes, as with Yusuf's brothers."}},{"t":"الحذر من الخلوة بما يُخشى منه الفتنة","r":[12,23,23],"q":{"bk":"saadi","w":"السعدي","s":12,"ay":111,"x":"الحذر من الخلوة بالنساء التي يُخشى منهنَّ الفتنة، والحذر أيضاً من المحبَّة التي يُخشى ضررها؛ فإنَّ امرأة العزيز جرى منها ما جرى بسبب توحدها بيوسفَ وحبِّها الشديدِ له، الذي ما تركها حتَّى راودتْه تلك المراودة، ثم كذبت عليه، فسُجِنَ بسببها مدة طويلة.","en":"Al-Sa'di: beware of being alone with women from whom temptation is feared, and of a love whose harm is feared."}},{"t":"الفرار من مواضع الفتنة غاية الجهد","r":[12,25,25],"q":{"bk":"saadi","w":"السعدي","s":12,"ay":111,"x":"أنه ينبغي للعبد إذا رأى محلاًّ فيه فتنة وأسباب معصية أن يفرَّ منه ويهربَ غاية ما يمكِنُه؛ ليتمكَّن من التخلُّص من المعصية؛ لأنَّ يوسف عليه السلام لما راودته التي هو في بيتها؛ فرَّ هارباً يطلُبُ الباب ليتخلَّص من شرِّها.","en":"Al-Sa'di: when a servant sees a place of temptation and causes of sin he should flee from it as far as he can, in order to be free of it."}},{"t":"اختيار السجن على المعصية","r":[12,33,33],"q":{"bk":"saadi","w":"السعدي","s":12,"ay":111,"x":"أن يوسف عليه السلام اختار السجنَ على المعصية؛ فهكذا ينبغي للعبد إذا ابْتُلِيَ بين أمرين: إما فعل معصية، وإما عقوبة دنيويَّة: أن يختار العقوبة الدنيويَّة على مواقعة الذنب الموجب للعقوبة الشديدة في الدُّنيا والآخرة، ولهذا من علامات الإيمان أن يكره العبدُ أن يعودَ في الكفر بعد أن أنقذه الله منه كما يكرهُ أنْ يُلقى في النار.","en":"Al-Sa'di: Yusuf chose prison over sin; so a servant tried between sin and a hardship should choose the hardship."}},{"t":"الالتجاء إلى الله والتبرؤ من الحول والقوة","r":[12,33,34],"q":{"bk":"saadi","w":"السعدي","s":12,"ay":111,"x":"أنه ينبغي للعبد أن يلتجئ إلى الله ويَحْتَمِي بحماه عند وجود أسباب المعصية ويتبرَّأ من حوله وقوته؛ لقول يوسف عليه السلام:{وإلاَّ تَصۡرِفۡ عنِّي كيدَهُنَّ أصبُ إليهنَّ وأكُنۡ من الجاهلين}.","en":"Al-Sa'di: a servant should seek refuge with Allah when causes of sin appear and disown his strength and power."}},{"t":"السعي في دفع التهمة وطلب البراءة محمود","r":[12,50,50],"q":{"bk":"saadi","w":"السعدي","s":12,"ay":111,"x":"أنه لا يُلام الإنسان على السعي في دفع التُّهمة عن نفسه وطلب البراءة لها، بل يُحْمَدُ على ذلك؛ كما امتنع يوسف عن الخروج من السجن حتى تتبيَّن لهم براءته بحال النسوة اللاتي قطعن أيديهنَّ.","en":"Al-Sa'di: a person is not blamed for striving to remove an accusation from himself and seek his innocence; he is praised for it, as Yusuf refused to leave prison until it was cleared."}},{"t":"الفرج مع الكرب واليسر مع العسر","r":[12,87,87],"q":{"bk":"saadi","w":"السعدي","s":12,"ay":111,"x":"أنَّ الفرج مع الكرب، وأنَّ مع العسر يسراً؛ فإنَّه لما طال الحزن على يعقوب واشتدَّ به إلى أنهى ما يكون، ثم حصل الاضطرار لآل يعقوب ومسَّهم الضرُّ؛ أذِنَ الله حينئذٍ بالفرج، فحصل التلاقي في أشدِّ الأوقات إليه حاجة واضطراراً، فتمَّ بذلك الأجر وحصل السرورُ وعُلِمَ مِن ذلك أنَّ الله يبتلي أولياءه بالشدَّة والرَّخاء والعسر واليسر؛ ليمتحنَ صبرهم وشكرهم، ويزداد بذلك إيمانُهم ويقينُهم وعِرْفانُهم.","en":"Al-Sa'di: relief comes with distress and with hardship comes ease; when Yaqub's grief reached its extreme, relief came."}},{"t":"كل خير في الدنيا والآخرة من آثار التقوى والصبر","r":[12,90,90],"q":{"bk":"saadi","w":"السعدي","s":12,"ay":111,"x":"فضيلة التقوى والصبر، وأنَّ كلَّ خير في الدنيا والآخرة فمن آثار التقوى والصبر، وأنَّ عاقبة أهلهما أحسن العواقب؛ لقوله:{قد منَّ الله علينا إنَّه من يتَّقِ ويَصۡبِرۡ فإنَّ الله لا يضيع أجر المحسنين}.","en":"Al-Sa'di: the merit of taqwa and patience, and that every good in this world and the next is among their effects and the outcome of their people is best."}},{"t":"لطف الله بيوسف: شدائد توصل إلى أعلى الغايات","r":[12,100,100],"q":{"bk":"saadi","w":"السعدي","s":12,"ay":111,"x":"لطف الله العظيم بيوسف؛ حيث نقله في تلك الأحوال، وأوصل إليه الشدائد والمحن؛ ليوصله بها إلى أعلى الغايات ورفيع الدرجات.","en":"Al-Sa'di: the great kindness of Allah to Yusuf, moving him through those states and bringing hardships to him, to bring him through them to the highest ends."}}],"ctx":{"bk":"ibnkathir","w":"ابن كثير","s":12,"ay":111,"x":"يَقُولُ تَعَالَى: لَقَدْ كَانَ فِي خَبَرِ الْمُرْسَلِينَ مَعَ قَوْمِهِمْ، وَكَيْفَ أَنْجَيْنَا الْمُؤْمِنِينَ وَأَهْلَكْنَا الْكَافِرِينَ ﴿عِبْرَةٌ لأولِي الألْبَابِ﴾ وَهِيَ الْعُقُولُ، ﴿مَا كَانَ حَدِيثًا يُفْتَرَى﴾ أَيْ: وَمَا كَانَ لِهَذَا الْقُرْآنِ أَنْ يُفْتَرَى مِنْ دُونِ اللَّهِ، أَيْ: يُكَذَّبَ ويُختلق، ﴿وَلَكِنْ تَصْدِيقَ الَّذِي بَيْنَ يَدَيْهِ﴾ أَيْ: مِنَ الْكُتُبِ الْمُنَزَّلَةِ مِنَ السَّمَاءِ، وَهُوَ يُصَدِّقُ مَا فِيهَا مِنَ الصَّحِيحِ، وَيَنْفِي مَا وَقَعَ فِيهَا مِنْ تَحْرِيفٍ وَتَبْدِيلٍ وَتَغْيِيرٍ، وَيَحْكُمُ عَلَيْهَا بِالنَّسَخِ أَوِ التَّقْرِيرِ، ﴿وَتَفْصِيلَ كُلِّ شَيْءٍ﴾ مِنْ تَحْلِيلٍ وَتَحْرِيمٍ، وَمَحْبُوبٍ وَمَكْرُوهٍ، وَغَيْرِ ذَلِكَ مِنَ الْأَمْرِ بِالطَّاعَاتِ وَالْوَاجِبَاتِ وَالْمُسْتَحَبَّاتِ، وَالنَّهْيِ عَنِ الْمُحَرَّمَاتِ وَمَا شَاكَلَهَا مِنَ الْمَكْرُوهَاتِ، وَالْإِخْبَارِ عَنِ الْأُمُورِ عَلَى الْجَلِيَّةِ، وَعَنِ الْغُيُوبِ الْمُسْتَقْبَلَةِ الْمُجْمَلَةِ وَالتَّفْصِيلِيَّةِ، وَالْإِخْبَارِ عَنِ الرَّبِّ تَبَارَكَ وَتَعَالَى بِالْأَسْمَاءِ وَالصِّفَاتِ، وَتَنْزِيهِهِ عَنْ مُمَاثَلَةِ الْمَخْلُوقَاتِ، فَلِهَذَا كَانَ: ﴿هُدًى وَرَحْمَةً لِقَوْمٍ يُؤْمِنُونَ﴾ تَهْتَدِي بِهِ قُلُوبُهُمْ مِنَ الْغَيِّ إِلَى الرَّشَادِ، وَمِنَ الضَّلَالَةِ إِلَى السَّدَادِ، وَيَبْتَغُونَ بِهِ الرَّحْمَةَ مِنْ رَبِّ الْعِبَادِ، فِي هَذِهِ الْحَيَاةِ الدُّنْيَا وَيَوْمَ الْمَعَادِ.","en":"Ibn Kathir: in the account of the messengers with their peoples, how We saved the believers and destroyed the disbelievers, is a lesson for people of understanding, that is, minds."}},{"id":"musa","cat":"a","n":"موسى وفرعون","intro":"أكثر الأنبياء ذكراً في القرآن: ميلاده في زمن القتل، وصندوقه في اليم وتربيته في قصر فرعون، وخروجه إلى مدين ثم تكليفه عند النار والمواجهة مع فرعون والسحرة، ثم النجاة بالبحر وإغراق فرعون؛ وفيها يتبين صراع الحق والجبروت.","eps":[{"t":"الميلاد والصندوق","r":[28,7,13]},{"t":"القتل والخروج","r":[28,14,21]},{"t":"مدين وتكليف الرعي","r":[28,22,28]},{"t":"النار والتكليف","r":[20,9,36]},{"t":"المواجهة والسحرة","r":[7,103,126]},{"t":"الخروج والغرق","r":[10,90,92]}],"ls":[{"t":"الله إذا أراد أمراً هيأ أسبابه بالتدريج","r":[28,7,7],"q":{"bk":"saadi","w":"السعدي","s":28,"ay":3,"x":"أنَّ الله تعالى إذا أراد أمراً؛ هيأ أسبابَه، وأتى بها شيئاً فشيئاً بالتدريج لا دفعة واحدة.","en":"Al-Sa'di: when Allah wills a matter He prepares its causes and brings them one by one, gradually, not all at once."}},{"t":"تثبيت الله القلب عند المخاوف أعظم نعمة","r":[28,10,10],"q":{"bk":"saadi","w":"السعدي","s":28,"ay":3,"x":"أنَّ من أعظم نعم الله على عبدِهِ وأعظم معونةٍ للعبد على أمورِهِ تثبيتُ الله إيَّاه وربطُ جأشِهِ وقلبِهِ عند المخاوف وعند الأمور المذهلةِ؛ فإنَّه بذلك يتمكَّن من القول الصواب والفعل الصواب؛ بخلاف من استمرَّ قلقُه وروعه وانزعاجُه؛ فإنَّه يضيع فكرُه، ويذهَلُ عقلُه؛ فلا ينتفعُ بنفسه في تلك الحال.","en":"Al-Sa'di: among the greatest blessings is Allah's steadying of His servant and calming his heart in frightening matters, which lets him say and do what is right."}},{"t":"العلم بالقدر لا يُسقط فعل الأسباب","r":[28,11,11],"q":{"bk":"saadi","w":"السعدي","s":28,"ay":3,"x":"أنَّ العبد ولو عَرَفَ أنَّ القضاء والقدر ووعدَ الله نافذٌ لا بدَّ منه؛ فإنَّه لا يهمل فعل الأسباب التي أُمِرَ بها، ولا يكون ذلك منافياً لإيمانِهِ بخبر الله؛ فإنَّ الله قد وعد أمَّ موسى أن يردَّه عليها، ومع ذلك اجتهدت في ردِّه، وأرسلتْ أختَه لتقُصَّه وتطلُبَه.","en":"Al-Sa'di: even if a servant knows that Allah's decree and promise will come about, he must not neglect the means he was commanded to take, which does not conflict with his faith."}},{"t":"يقدّر الله المشاق ليبلّغ سروراً أعظم منها","r":[28,13,13],"q":{"bk":"saadi","w":"السعدي","s":28,"ay":3,"x":"أنَّ الله يقدِّرُ على عبده بعضَ المشاقِّ لِيُنيلَه سروراً أعظم من ذلك، أو يدفعَ عنه شرًّا أكثر منه؛ كما قدَّر على أمِّ موسى ذلك الحزن الشديد والهمَّ البليغ الذي هو وسيلةٌ إلى أن يَصِلَ إليها ابنُها على وجهٍ تطمئنُّ به نفسها، وتَقَرُّ به عينُها، وتزداد به غبطةً وسروراً.","en":"Al-Sa'di: Allah decrees some hardships on His servant to give him greater joy or to ward off greater harm, as with the great grief decreed on Musa's mother."}},{"t":"الخوف الطبيعي لا ينافي الإيمان","r":[28,18,18],"q":{"bk":"saadi","w":"السعدي","s":28,"ay":3,"x":"أنَّ الخوف الطبيعيَّ من الخَلْقِ لا يُنافي الإيمان ولا يزيلُه؛ كما جرى لأمِّ موسى، ولموسى من تلك المخاوف.","en":"Al-Sa'di: natural fear of creatures neither contradicts nor removes faith, as happened to Musa's mother and to Musa."}},{"t":"من خُلق الأنبياء الرحمة بالخلق والإحسان إليهم","r":[28,24,24],"q":{"bk":"saadi","w":"السعدي","s":28,"ay":3,"x":"أنَّ الرحمة بالخلق والإحسان على مَن يعْرِفُ ومَن لا يَعْرِفُ من أخلاق الأنبياء، وأنَّ من الإحسان سقي الماشية الماء وإعانة العاجز.","en":"Al-Sa'di: mercy to creation and doing good to those one knows and does not know are among the character of the prophets, and giving water to cattle and helping the weak are part of it."}},{"t":"خير من يُستأجر القوي الأمين","r":[28,26,26],"q":{"bk":"saadi","w":"السعدي","s":28,"ay":3,"x":"أنَّ خير أجيرٍ وعامل يعمل للإنسان أن يكونَ قويًّا أميناً.","en":"Al-Sa'di: the best employee and worker one can hire is one who is strong and trustworthy."}},{"t":"أعظم العقوبات أن يكون الإنسان إماماً في الشر","r":[28,41,41],"q":{"bk":"saadi","w":"السعدي","s":28,"ay":3,"x":"أنَّ من أعظم العقوبات أن يكون الإنسانُ إماماً في الشرِّ، وذلك بحسب معارضتِهِ لآياتِ الله وبيناتِهِ؛ كما أنَّ من أعظم نعمةٍ أنعم الله بها على عبده، أن يجعله إماماً في الخير هادياً مهديًّا.","en":"Al-Sa'di: among the greatest punishments is for a person to be a leader in evil, according to his opposing Allah's signs; and among the greatest blessings is to be a leader in good, guiding and guided."}}],"ctx":{"bk":"ibnkathir","w":"ابن كثير","s":28,"ay":7,"x":"فَلَمَّا ضَاقَتْ ذَرْعًا بِهِ أُلْهِمَتْ فِي سِرِّهَا، وَأُلْقِي فِي خَلَدِهَا، وَنُفِثَ فِي رَوْعِهَا، كَمَا قَالَ اللَّهُ تَعَالَى: ﴿وَأَوْحَيْنَا إِلَى أُمِّ مُوسَى أَنْ أَرْضِعِيهِ فَإِذَا خِفْتِ عَلَيْهِ فَأَلْقِيهِ فِي الْيَمِّ وَلا تَخَافِي وَلا تَحْزَنِي إِنَّا رَادُّوهُ إِلَيْكِ وَجَاعِلُوهُ مِنَ الْمُرْسَلِينَ﴾ .","en":"Ibn Kathir: when she could no longer bear it, it was inspired in her heart and put in her mind to place the child in a chest on the river."}},{"id":"khidr","cat":"a","n":"موسى والعبد الصالح","intro":"رحلة موسى عليه السلام إلى مجمع البحرين لطلب العلم، وصحبته عبداً آتاه الله رحمة وعلماً لدنياً، وثلاثة مشاهد ظاهرها منكر وباطنها حكمة: السفينة والغلام والجدار؛ ثم تأويل ما لم يستطع عليه صبراً.","eps":[{"t":"طلب العلم والرحلة","r":[18,60,64]},{"t":"الشرط والصحبة","r":[18,65,70]},{"t":"السفينة","r":[18,71,73]},{"t":"الغلام","r":[18,74,76]},{"t":"الجدار","r":[18,77,78]},{"t":"التأويل","r":[18,79,82]}],"ls":[{"t":"فضيلة العلم والرحلة في طلبه","r":[18,60,60],"q":{"bk":"saadi","w":"السعدي","s":18,"ay":60,"x":"وفي هذه القصة العجيبة الجليلة من الفوائد والأحكام والقواعد شيءٌ كثيرٌ ننبِّه على بعضه بعون الله: فمنها: فضيلة العلم والرِّحلة في طلبه، وأنَّه أهمُّ الأمورِ؛ فإنَّ موسى عليه السلام رحل مسافةً طويلةً، ولقي النَّصب في طلبه، وترك القعود عند بني إسرائيل لتعليمهم وإرشادهم، واختار السفر لزيادة العلم على ذلك.","en":"Al-Sa'di begins the benefits of the story: the merit of knowledge and travelling in its pursuit, for Musa travelled a long distance and met hardship."}},{"t":"تواضع الفاضل للتعلم ممن دونه","r":[18,66,66],"q":{"bk":"saadi","w":"السعدي","s":18,"ay":60,"x":"تواضع الفاضل للتعلُّم ممَّن دونه؛ فإنَّ موسى بلا شكٍّ أفضل من الخضر. ومنها: تعلُّم العالم الفاضل للعلم الذي لم يتمهَّر فيه ممَّن مَهَرَ فيه، وإنْ كان دونَه في العلم بدرجاتٍ كثيرةٍ؛ فإنَّ موسى عليه السلام من أولي العزم من المرسلين، الذين منحهم الله وأعطاهم من العلم ما لم يعطِ سواهم، ولكن في هذا العلم الخاصِّ كان عند الخضر ما ليس عنده؛ فلهذا حرص على التعلُّم منه؛ فعلى هذا لا ينبغي للفقيه المحدِّث إذا كان قاصراً في علم النحو أو الصرف أو نحوه من العلوم أن لا يتعلَّمه ممَّن مَهَرَ فيه، وإنْ لم يكنْ محدِّثاً ولا فقيهاً.","en":"Al-Sa'di: Musa, without doubt better than al-Khidr and among the messengers of firm resolve, humbled himself to learn what he had not mastered."}},{"t":"من لا صبر له لا يدرك العلم","r":[18,67,68],"q":{"bk":"saadi","w":"السعدي","s":18,"ay":60,"x":"أن من ليس له قوَّة الصبر على صحبة العالم والعلم وحسن الثَّبات على ذلك؛ أنَّه [يفوته بحسب عدم صبره كثير من] العلم؛ فمن لا صبر له؛ لا يدرِكُ العلم، ومن استعمل الصبر ولازمه؛ أدرك به كل أمرٍ سعى فيه؛ لقول الخضر يتعذر من موسى بذكر المانع لموسى من الأخذ عنه: إنَّه لا يصبر معه.","en":"Al-Sa'di: whoever lacks the strength of patience with the scholar and knowledge loses much knowledge; whoever uses patience and keeps to it attains whatever he strives for."}},{"t":"التأني وعدم المبادرة إلى الحكم قبل معرفة المقصود","r":[18,70,70],"q":{"bk":"saadi","w":"السعدي","s":18,"ay":60,"x":"الأمر بالتأنِّي والتثبُّت وعدم المبادرة إلى الحكم على الشيء حتى يعرفَ ما يُراد منه وما هو المقصود.","en":"Al-Sa'di: the command to deliberate and verify, and not to hasten to judge a matter until one knows what is intended by it."}},{"t":"تعليق المستقبل بالمشيئة، والعزم ليس كالفعل","r":[18,69,69],"q":{"bk":"saadi","w":"السعدي","s":18,"ay":60,"x":"تعليقُ الأمور المستقبلة التي من أفعال العباد بالمشيئة، وأن لا يقولَ الإنسان للشيء: إني فاعل ذلك في المستقبل إلاَّ أن يقول إن شاء الله. ومنها: أن العزم على فعل الشيء ليس بمنزلة فعله؛ فإنَّ موسى قال:{سَتَجِدُني إن شاء الله صابراً}: فوطَّن نفسه على الصبر ولم يفعل.","en":"Al-Sa'di: one must not say \"I shall do this\" without \"if Allah wills\"; and resolve to do a thing is not like doing it, for Musa resolved to be patient and did not do so."}},{"t":"يُدفع الشر الكبير بارتكاب الصغير ويُراعى أكبر المصلحتين","r":[18,80,80],"q":{"bk":"saadi","w":"السعدي","s":18,"ay":60,"x":"القاعدة الكبيرة الجليلة، وهو أنَّه يُدْفَعُ الشرُّ الكبير بارتكاب الشرِّ الصغير، ويُراعى أكبر المصلحتين بتفويت أدناهما؛ فإنَّ قتل الغلام شرٌّ، ولكنَّ بقاءه حتى يفتن أبويه عن دينهما أعظمُ شرًّا منه، وبقاء الغلام من دون قتل وعصمته وإن كان يظنُّ أنه خيرٌ؛ فالخير ببقاء دين أبويه وإيمانهما خيرٌ من ذلك؛ فلذلك قَتَلَهُ الخضر.","en":"Al-Sa'di: a great and noble rule: the great evil is repelled by committing the small evil; killing the boy was an evil but his remaining until he tempted his parents from their religion was greater."}},{"t":"الأدب مع الله في الألفاظ","r":[18,79,79],"q":{"bk":"saadi","w":"السعدي","s":18,"ay":60,"x":"استعمال الأدب مع الله تعالى في الألفاظ؛ فإنَّ الخضر أضاف عَيْبَ السفينة إلى نفسه؛ بقوله:{فأردتُ أن أعيبها}، وأما الخيرُ؛ فأضافه إلى الله تعالى؛ لقوله:{فأراد ربُّك أن يَبۡلُغا أشدَّهما ويستخرِجا كَنزَهما رحمةً من ربِّك}؛ كما قال إبراهيم عليه السلام:{وإذا مرضۡتُ فهو يشفينِ}، وقالت الجنُّ:{وأنَّا لا ندري أشرٌّ أريدَ بِمَن في الأرض أم أرادَ بهم ربُّهم رَشَداً}؛ مع أنَّ الكلَّ بقضاء الله وقدره.","en":"Al-Sa'di: courtesy with Allah in words: al-Khidr attributed the flaw of the boat to himself (\"I wished to damage it\") but attributed the good to Allah (\"your Lord intended\")."}},{"t":"الله يحفظ العبد الصالح في ذريته","r":[18,82,82],"q":{"bk":"saadi","w":"السعدي","s":18,"ay":60,"x":"أنَّ العبد الصالح يحفظُهُ الله في نفسه وفي ذُرِّيَّتِهِ. ومنها: أن خدمة الصالحين أو مَنْ يتعلَّق بهم أفضل من غيرها؛ لأنَّه علَّل استخراج كنزهما وإقامة جدارهما بأنَّ أباهما صالح.","en":"Al-Sa'di: the righteous servant is protected by Allah in himself and in his offspring, and serving the righteous or those connected with them is better than other service."}}]},{"id":"kahf","cat":"a","n":"أصحاب الكهف","intro":"فتية آمنوا بربهم فزادهم هدى، فاعتزلوا قومهم المشركين ولجؤوا إلى الكهف، فضرب الله على آذانهم سنين عدداً ثم بعثهم ليتساءلوا، وجعل أمرهم آية على البعث وعلى لطفه بأوليائه.","eps":[{"t":"الفتية وهجرة القوم","r":[18,9,16]},{"t":"النوم الطويل","r":[18,17,18]},{"t":"البعث والرسول إلى المدينة","r":[18,19,20]},{"t":"العثور عليهم","r":[18,21,21]},{"t":"عددهم والمراء","r":[18,22,26]}],"ls":[{"t":"شباب آمنوا فزادهم الله هدى","r":[18,13,13],"q":{"bk":"saadi","w":"السعدي","s":18,"ay":13,"x":"{إنَّهم فتيةٌ آمنوا بربِّهم}: وهذا من جموع القلَّة، يدلُّ ذلك على أنَّهم دون العشرة، آمنوا بالله وحدَه لا شريك له من دون قومهم، فشكر اللهُ لهم إيمانَهم، فزادهم هدىً؛ أي: بسبب أصل اهتدائهم إلى الإيمان زادهم الله من الهدى الذي هو العلم النافع والعمل الصالح؛ كما قال تعالى:{ويزيدُ الله الذين اهتَدَوۡا هدىً}.","en":"Al-Sa'di: \"youths who believed in their Lord,\" a plural of fewness, indicating fewer than ten; they believed in Allah alone and He increased them in guidance."}},{"t":"فرارهم بدينهم من الفتن وترك الأوطان لله","r":[18,16,16],"q":{"bk":"saadi","w":"السعدي","s":18,"ay":19,"x":"شدة رغبة هؤلاء الفتية في الدين وفرارهم من كلِّ فتنةٍ في دينهم وتركُهم أوطانَهم في الله.","en":"Al-Sa'di: the strong desire of these youths for their religion, their flight from every temptation in their faith and leaving their homelands for Allah."}},{"t":"الحث على العلم والمباحثة فيه","r":[18,19,19],"q":{"bk":"saadi","w":"السعدي","s":18,"ay":19,"x":"وقد دلَّت هاتان الآيتان على عدة فوائد: منها: الحثُّ على العلم وعلى المباحثة فيه؛ لكون الله بعثهم لأجل ذلك.","en":"Al-Sa'di: the two verses indicate several benefits, among them urging knowledge and discussion of it, since Allah raised them for that."}},{"t":"من اشتبه عليه العلم رده إلى عالمه","r":[18,19,19],"q":{"bk":"saadi","w":"السعدي","s":18,"ay":19,"x":"الأدب فيمن اشتبه عليه العلم أن يردَّه إلى عالمه، وأن يَقِفَ عند حدِّه.","en":"Al-Sa'di: courtesy for one to whom knowledge is unclear: refer it to its knower and stop at one's limit."}},{"t":"التحرز والاستخفاء واتقاء مواقع الفتن في الدين","r":[18,19,19],"q":{"bk":"saadi","w":"السعدي","s":18,"ay":19,"x":"الحثُّ على التحرُّز والاستخفاء والبعد عن مواقع الفتن في الدين واستعمال الكِتْمان في ذلك على الإنسان وعلى إخوانه في الدين.","en":"Al-Sa'di: urging caution, concealment and keeping away from places of temptation in religion, using discretion for oneself and for others."}},{"t":"النهي عن المراء في المغيّبات بغير علم","r":[18,22,22],"q":{"bk":"saadi","w":"السعدي","s":18,"ay":22,"x":"{فلا تمارِ}: تجادل وتُحاج {فيهم إلاَّ مراء ظاهرا}؛ أي: مبنياً على العلم واليقين، ويكون أيضاً فيه فائدةٌ، وأما المماراة المبنيَّة على الجهل والرجم بالغيب أو التي لا فائدةَ فيها: إما أنْ يكونَ الخصمُ معانداً، أو تكون المسألةُ لا أهميَّة فيها ولا تحصُلُ فائدةٌ دينيَّةٌ بمعرفتها؛ كعدد أصحاب الكهف ونحو ذلك؛ فإنَّ في كثرة المناقشات فيها والبحوث المتسلسلة تضييعاً للزَّمان وتأثيراً في مودَّة القلوب بغير فائدة.","en":"Al-Sa'di: do not dispute about them except with apparent disputation, based on knowledge and certainty and with benefit in it."}}],"ctx":{"bk":"ibnkathir","w":"ابن كثير","s":18,"ay":13,"x":"مِنْ هَاهُنَا شَرَعَ فِي بَسْطِ الْقِصَّةِ وَشَرْحِهَا، فَذَكَرَ تَعَالَى أَنَّهُمْ فِتْيَةٌ -وَهُمُ الشَّبَابُ-وَهُمْ أَقْبَلُ لِلْحَقِّ، وَأَهْدَى لِلسَّبِيلِ مِنَ الشُّيُوخِ، الَّذِينَ قَدْ عَتَوْا وعَسَوا فِي دِينِ الْبَاطِلِ؛ وَلِهَذَا كَانَ أَكْثَرُ الْمُسْتَجِيبِينَ لِلَّهِ وَلِرَسُولِهِ ﷺ شَبَابًا.","en":"Ibn Kathir: from here Allah begins to expand the story: they were youths, who are readier for the truth and better guided than the old who have grown hardened in the religion of falsehood."}},{"id":"dq","cat":"a","n":"ذو القرنين والسد","intro":"ملك مكّن الله له في الأرض وآتاه من كل شيء سبباً، فبلغ مغرب الشمس ومطلعها وما بين السدين، وأقام السد على يأجوج ومأجوج؛ يُعرض في صورة الحاكم الذي يجمع القوة والعدل والتواضع لله.","eps":[{"t":"التمكين والأسباب","r":[18,83,85]},{"t":"عند مغرب الشمس","r":[18,86,88]},{"t":"عند مطلع الشمس","r":[18,89,91]},{"t":"بين السدين","r":[18,92,98]}],"ls":[{"t":"السياسة العادلة: العقوبة للظالم والإحسان للمؤمن","r":[18,87,87],"q":{"bk":"saadi","w":"السعدي","s":18,"ay":83,"x":"{87} فكان عند ذي القرنين من السياسة الشرعيَّة ما استحقَّ به المدح والثناء؛ لتوفيق الله له لذلك، فقال: سأجعلهم قسمين: {أمَّا مَنۡ ظَلَمَ}: بالكفر، {فسوف نعذِّبُه ثم يردُّ إلى ربِّه فيعذِّبه عذاباً نُكۡراً}؛ أي: تحصُلُ له العقوبتان؛ عقوبة الدنيا، وعقوبة الآخرة.","en":"Al-Sa'di: Dhul-Qarnayn had a lawful policy for which he deserved praise, by Allah's granting."}},{"t":"كل ما بيده من الأسباب بتقدير الله وعلمه","r":[18,91,91],"q":{"bk":"saadi","w":"السعدي","s":18,"ay":92,"x":"{91} ومع هذا؛ فكلُّ هذا بتقدير الله له وعلمه به، ولهذا قال:{كذلك وقَدۡ أَحَطۡنا [بما لديه خبراً}؛ أي:] بما عنده من الخير والأسباب العظيمة، وعِلْمُنا معه حيثما توجَّه وسار.","en":"Al-Sa'di: all of this was by Allah's decree for him and His knowledge of it."}},{"t":"الأسباب العلمية: فقه ألسنة القوم وتفاهمهم","r":[18,94,94],"q":{"bk":"saadi","w":"السعدي","s":18,"ay":92,"x":"{94} وقد أعطى الله ذا القرنين من الأسباب العلميَّة ما فقه به ألسنة أولئك القوم وفقههم وراجعهم وراجعوه، فاشْتَكَوا إليه ضرر يأجوج ومأجوج، وهما أمَّتان عظيمتان من بني آدم، فقالوا:{إنَّ يأجوج ومأجوجَ مفسدون في الأرض}: بالقتل وأخذ الأموال وغير ذلك.","en":"Al-Sa'di: Allah gave him knowledge-based means with which he understood their language and they conversed with him."}},{"t":"الزهد في أجرة الدنيا مع الإصلاح","r":[18,95,95],"q":{"bk":"saadi","w":"السعدي","s":18,"ay":92,"x":"{95} فلم يكن ذو القرنين ذا طمع ولا رغبةٍ في الدُّنيا ولا تاركاً لإصلاح أحوال الرعيَّة، بل قصدُهُ الإصلاح؛ فلذلك أجاب طلبتهم؛ لما فيها من المصلحة، ولم يأخذ منهم أجرةً، وشَكَرَ ربَّه على تمكينه واقتداره، فقال لهم:{ما مَكَّنِّي فيه ربِّي خيرٌ}؛ أي: مما تبذلون لي وتعطوني، وإنَّما أطلب منكم أن تعينوني بقوَّةٍ منكم بأيديكم؛ {أجۡعَلۡ بينَكم وبينهم رَدۡماً}؛ أي: مانعاً من عبورهم عليكم.","en":"Al-Sa'di: Dhul-Qarnayn was not greedy or desirous of the world nor neglecting reform of the subjects; his aim was reform."}},{"t":"إضافة النعمة إلى موليها: «هذا رحمة من ربي»","r":[18,98,98],"q":{"bk":"saadi","w":"السعدي","s":18,"ay":92,"x":"{98} فلما فَعَلَ هذا الفعل الجميل والأثر الجليل؛ أضاف النعمةَ إلى موليها، وقال:{هذا رحمةٌ من ربِّي}؛ أي: من فضله وإحسانه عليَّ، وهذه حال الخلفاء والصالحين إذا منَّ الله عليهم بالنِّعم الجليلة؛ ازدادَ شكرُهُم وإقرارُهُم واعترافُهم بنعمة الله؛ كما قال سليمانُ عليه السلام لما حَضَرَ عنده عرشُ ملكة سبأ مع البعد العظيم؛ قال:{هذا من فضل ربِّي لِيَبۡلُوَني أأشكُرُ أم أكۡفُرُ}؛ بخلاف أهل التجبُّر والتكبُّر والعلوِّ في الأرض؛ فإنَّ النعم الكبار تزيدُهم أشراً وبطراً؛ كما قال قارونُ لما آتاه الله من الكنوز ما إنَّ مفاتِحَهُ لتنوءُ بالعُصْبَةِ أولي القوَّة؛ قال:{إنَّما أوتيتُهُ على علم عندي}.","en":"Al-Sa'di: after this noble deed he attributed the blessing to the One who gave it, saying, \"This is a mercy from my Lord.\""}}],"ctx":{"bk":"ibnkathir","w":"ابن كثير","s":18,"ay":83,"x":"يَقُولُ تَعَالَى لِنَبِيِّهِ ﷺ: ﴿وَيَسْأَلُونَكَ﴾ يَا مُحَمَّدُ ﴿عَنْ ذِي الْقَرْنَيْنِ﴾ أَيْ: عَنْ خَبَرِهِ.","en":"Ibn Kathir: Allah says to His Prophet: they ask you, Muhammad, about Dhul-Qarnayn."}},{"id":"sulayman","cat":"a","n":"داود وسليمان","intro":"ملك ونبوة اجتمعا: داود بالزبور وصنعة الدروع وفصل الخطاب، وسليمان بتسخير الريح والجن وفهم منطق الطير وقصة الهدهد وملكة سبأ؛ وهما أمثلة على شكر النعمة والأوبة إلى الله.","eps":[{"t":"نعمة العلم والشكر","r":[27,15,19]},{"t":"الهدهد وسبأ","r":[27,20,44]},{"t":"فتنة الخيل والأوبة","r":[38,30,40]},{"t":"تسخير الريح والجن","r":[34,12,14]}],"ls":[{"t":"الله يحب القوة في طاعته","r":[38,30,30],"q":{"bk":"saadi","w":"السعدي","s":38,"ay":30,"x":"أنَّ الله تعالى يمدحُ ويحبُّ القوَّة في طاعته؛ قوَّةَ القلب والبدن؛ فإنَّه يحصُلُ منها من آثار الطاعة وحسنِها وكثرتِها ما لا يحصُلُ مع الوهن وعدم القوَّة، وأنَّ العبد ينبغي له تعاطي أسبابها وعدم الركونِ إلى الكسل والبطالة المخلَّةِ بالقوَّة المضعفة للنفس.","en":"Al-Sa'di: Allah praises and loves strength in obeying Him, strength of heart and body, for it brings the fruits of obedience."}},{"t":"الرجوع إلى الله من أوصاف الأنبياء","r":[38,30,30],"q":{"bk":"saadi","w":"السعدي","s":38,"ay":30,"x":"أنَّ الرجوع إلى الله في جميع الأمورِ من أوصاف أنبياء الله وخواصِّ خلقِهِ؛ كما أثنى الله على داود وسليمان بذلك؛ فَلْيَقْتَدِ بهما المقتدون، ولْيَهْتَدِ بُهداهم السالكون، {أولئك الذين هدى الله فبِهُداهُمُ اقۡتَدِه}.","en":"Al-Sa'di: returning to Allah in all matters is among the attributes of the prophets and the elect of His creation, as Allah praised Dawud and Sulayman."}},{"t":"العلم النافع والحكم بين الناس من أعظم النعم","r":[27,15,15],"q":{"bk":"saadi","w":"السعدي","s":38,"ay":30,"x":"أنَّ من أكبر نعم الله على عبدِهِ أن يرزُقَه العلم النافع ويعرِفَ الحُكْمَ والفصلَ بين الناس؛ كما امتنَّ الله به على عبدِهِ داود عليه السلام.","en":"Al-Sa'di: among the greatest blessings is that Allah grants a servant beneficial knowledge and knowledge of judgment and decision between people."}},{"t":"الحاكم يحذر الهوى","r":[38,26,26],"q":{"bk":"saadi","w":"السعدي","s":38,"ay":30,"x":"أنَّه ينبغي للحاكم أن يَحْذَرَ الهوى ويَجْعَلَه منه على بال؛ فإنَّ النفوس لا تَخْلو منه، بل يجاهدُ نفسَه بأن يكونَ الحقُّ مقصودَه، وأن يلقي عنه وقتَ الحكم كلَّ محبةٍ أو بغضٍ لأحدِ الخصمين.","en":"Al-Sa'di: a ruler should beware of whim and keep it in mind, since souls are never free of it; he strives against his soul against it."}},{"t":"تدبير الملك بنفسه ودقة الحزم","r":[27,20,20],"q":{"bk":"saadi","w":"السعدي","s":27,"ay":15,"x":"والشاهدُ أنَّ تفقُّدَ سليمان عليه السلام للطير وفَقْدَهُ الهدهدَ يدلُّ على كمال حزمِهِ وتدبيرِهِ للمُلك بنفسه وكمال فطنتِهِ، حتى فَقَدَ هذا الطائر الصغير، {فقال ما لي لا أرى الهُدۡهُدَ أم كان من الغائبين}؛ أي: هل عدم رؤيتي إيَّاه لقلَّة فطنتي به لكونه خفيًّا بين هذه الأمم الكثيرة؟","en":"Al-Sa'di: Sulayman's checking on the birds and missing the hoopoe shows his perfect firmness and management of the kingdom himself."}},{"t":"محبة الله مقدّمة على كل شيء","r":[38,32,32],"q":{"bk":"saadi","w":"السعدي","s":38,"ay":30,"x":"تقديم سليمان محبَّةَ الله تعالى على محبَّةِ كل شيء.","en":"Al-Sa'di: Sulayman put the love of Allah before the love of everything."}},{"t":"ما شغل عن الله مشؤوم، ومن ترك شيئاً لله عوّضه خيراً","r":[38,33,34],"q":{"bk":"saadi","w":"السعدي","s":38,"ay":30,"x":"أنَّ كل ما شغل العبد عن الله؛ فإنَّه مشؤومٌ مذمومٌ؛ فليفارِقْه ولْيُقْبِلْ على ما هو أنفعُ له. ومنها: القاعدة المشهورةُ: من ترك شيئاً لله؛ عوَّضَه الله خيراً منه.","en":"Al-Sa'di: whatever occupies the servant from Allah is ill-omened and blameworthy; let him leave it; and the famous rule: whoever leaves something for Allah, Allah gives him better in exchange."}}],"ctx":{"bk":"ibnkathir","w":"ابن كثير","s":27,"ay":15,"x":"يُخْبِرُ تَعَالَى عَمَّا أَنْعَمَ بِهِ عَلَى عَبْدَيْهِ وَنَبِيَّيْهِ دَاوُدَ وَابْنِهِ سُلَيْمَانَ، عَلَيْهِمَا مِنَ اللَّهِ السَّلَامُ، مِنَ النِّعَمِ الْجَزِيلَةِ، وَالْمَوَاهِبِ الْجَلِيلَةِ، وَالصِّفَاتِ الْجَمِيلَةِ، وَمَا جَمَعَ لَهُمَا بَيْنَ سَعَادَةِ الدُّنْيَا وَالْآخِرَةِ، وَالْمُلْكِ وَالتَّمْكِينِ التَّامِّ فِي الدُّنْيَا، وَالنُّبُوَّةِ وَالرِّسَالَةِ فِي الدِّينِ؛ وَلِهَذَا قَالَ: ﴿وَلَقَدْ آتَيْنَا دَاوُدَ وَسُلَيْمَانَ عِلْمًا وَقَالا الْحَمْدُ لِلَّهِ الَّذِي فَضَّلَنَا عَلَى كَثِيرٍ مِنْ عِبَادِهِ الْمُؤْمِنِينَ﴾ .","en":"Ibn Kathir: Allah informs of what He blessed His two servants and prophets Dawud and his son Sulayman with, of knowledge and thankfulness."}},{"id":"maryam","cat":"a","n":"مريم وعيسى","intro":"اصطفاء بيت عمران، ونذر امرأته وولادة مريم، وكفالة زكريا ورزقها في المحراب، ثم البشارة بكلمة من الله اسمه المسيح عيسى ابن مريم، وولادته بلا أب، وكلامه في المهد؛ آية على كمال قدرة الله وعبودية المسيح.","eps":[{"t":"نذر امرأة عمران ومريم","r":[3,35,37]},{"t":"البشارة","r":[19,16,21]},{"t":"الحمل والمخاض","r":[19,22,26]},{"t":"مع قومها وكلام المهد","r":[19,27,33]}],"ls":[{"t":"رزق الكرامة بلا كدّ وبركة الصلاح","r":[3,37,37],"q":{"bk":"saadi","w":"السعدي","s":3,"ay":42,"x":"ثم إن الله تعالى أكرم مريم وزكريا حيث يسَّر لمريم من الرزق الحاصل بلا كدٍّ ولا تعب، وإنما هو كرامة أكرمها الله به، إذ {كلما دخل عليها زكريا المحراب}؛ وهو محل العبادة وفيه إشارة إلى كثرة صلاتها وملازمتها لمحرابها {وجد عندها رزقاً}؛ هنيئاً معدًّا قال:{أنى لك هذا قالت هو من عند الله إن الله يرزقُ من يشاء بغير حساب}؛ فلما رأى زكريا هذه الحال والبر واللطف من الله بها، ذكَّرَه أن يسأل الله تعالى حصول الولد على حين اليأس منه فقال:{رب هَب لي من لَدُنك ذرية طيبة إنك سميعُ الدُّعاء.","en":"Al-Sa'di: Allah honoured Maryam and Zakariyya by making easy for Maryam provision that came without toil, a mark of honour."}},{"t":"قدرة الله بلا أب: آية للناس ورحمة","r":[19,21,21],"q":{"bk":"saadi","w":"السعدي","s":19,"ay":16,"x":"{21}{قال كذلكِ قال ربُّكِ هو عليَّ هيِّنٌ ولِنَجۡعَلَه آيةً للناسِ}: تدلُّ على كمال قدرةِ الله تعالى وعلى أنَّ الأسباب جميعها لا تستقلُّ بالتأثير، وإنَّما تأثيرها بتقدير الله، فيُري عباده خرقَ العوائد في بعض الأسباب العاديَّة؛ لئلاَّ يقفوا مع الأسباب، ويقطعوا النظر عن مقدِّرها ومسبِّبها. {ورحمة منَّا}؛ [أي]: ولنجعله رحمةً منَّا به وبوالدته وبالناس: أما رحمةُ الله به؛ فَلِمَا خَصَّه الله بوحيه، ومنَّ عليه بما منَّ به على أولي العزم.","en":"Al-Sa'di: \"Thus said your Lord, it is easy for Me, and that We make him a sign\" shows the perfection of Allah's power; and \"a mercy from Us\" to him, to his mother and to the people."}},{"t":"الطمأنينة بعد الشدة: فكلي واشربي وقري عيناً","r":[19,26,26],"q":{"bk":"saadi","w":"السعدي","s":19,"ay":22,"x":"{26}{فكُلي}: من التمر، {واشۡربي}: من النهر، {وقَرِّي عَيۡناً}: بعيسى؛ فهذا طمأنينتها من جهة السلامة من ألم الولادة وحصول المأكل والمشرب الهنيِّ، وأما من جهة قالة الناس؛ فأمرها أنَّها إذا رأت أحداً من البشر أنْ تقولَ على وجه الإشارة:{إنِّي نذرتُ للرحمن صوماً}؛ أي: سكوتاً، {فلن أكلِّمَ اليوم إنسيًّا}؛ أي: لا تخاطبيهم بكلام لتستريحي من قولهم وكلامهم، وكان معروفاً عندهم أنَّ السكوت من العبادات المشروعة.","en":"Al-Sa'di: eat from the dates, drink from the stream and be glad with Isa; this is her reassurance from the pain of labour."}},{"t":"براءتها بآية لا بدعوى: أشارت إليه","r":[19,29,29],"q":{"bk":"saadi","w":"السعدي","s":19,"ay":22,"x":"وإنَّما لم تؤمَرْ بمخاطبتهم في نفي ذلك عن نفسها، لأنَّ الناس لا يصدِّقونها، ولا فيه فائدة، وليكون تبرئتها بكلام عيسى في المهد أعظم شاهدٍ على براءتها؛ فإنَّ إتيان المرأة بولدٍ من دون زوج ودعواها أنَّه من غير أحدٍ من أكبر الدعاوى التي لو أقيم عدَّة من الشهود لم تصدَّق بذلك، فجُعِلَتْ بيِّنةُ هذا الخارق للعادة أمراً من جنسه، وهو كلام عيسى في حال صغره جدًّا، ولهذا قال تعالى:","en":"Al-Sa'di: she was not commanded to address them, because they would not believe her and there was no benefit; so that her vindication would come by a greater speech."}},{"t":"عبودية المسيح وبركته: «إني عبد الله»","r":[19,30,31],"q":{"bk":"saadi","w":"السعدي","s":19,"ay":27,"x":"{30} فحينئذٍ قال عيسى عليه السلام وهو في المهد صبيٌّ: {إنِّي عبد الله آتانيَ الكتاب وجَعَلَني نبيًّا}: فخاطبهم بوصفه بالعبوديَّة، وأنه ليس فيه صفةٌ يستحقُّ بها أن يكون إلهاً أو ابناً للإله، تعالى الله عن قول النصارى المخالفين لعيسى في قوله:{إنِّي عبدُ الله}، ومدَّعون موافقته، {آتانيَ الكتابَ}؛ أي: قضى أن يؤتيني الكتابَ، {وجَعَلَني نبيًّا}: فأخبرهم بأنَّه عبدُ الله، وأنَّ الله علَّمه الكتاب وجعله من جملة أنبيائه؛ فهذا من كماله لنفسه. {31} ثم ذكر تكميلَه لغيره، فقال:{وجَعَلَني مباركاً أينما كنت}؛ أي: في أيِّ مكانٍ وأيِّ زمان؛ فالبركةُ جعلها الله فيَّ من تعليم الخير والدعوة إليه والنهي عن الشرِّ والدعوة إلى الله في أقوالِهِ وأفعالِهِ؛ فكلُّ من جالسه أو اجتمع به؛ نالتْه بركتُه وسَعِدَ به مصاحبه.","en":"Al-Sa'di: Isa said while in the cradle, \"I am the servant of Allah, He has given me the Book and made me a prophet,\" and \"He made me blessed wherever I am.\""}},{"t":"من تمسك بدينه نصره الله ومن تركه خُذل","r":[3,55,55],"q":{"bk":"saadi","w":"السعدي","s":3,"ay":42,"x":"ولكن حكمة الله عادلة فإنها اقتضت أن من تمسك بالدين نصره النصر المبين، وأن من ترك أمره ونهيه ونبذ شرعه وتجرأ على معاصيه أن يعاقبه ويسلط عليه الأعداء.","en":"Al-Sa'di: Allah's just wisdom decreed that whoever holds to the religion He gives clear victory, and whoever abandons His command and law is left to defeat."}}],"ctx":{"bk":"ibnkathir","w":"ابن كثير","s":19,"ay":16,"x":"لَمَّا ذَكَرَ تَعَالَى قِصَّةَ زَكَرِيَّا، عَلَيْهِ السَّلَامُ، وَأَنَّهُ أَوْجَدَ مِنْهُ، فِي حَالِ كِبَرِهِ وَعُقْمِ زَوْجَتِهِ، وَلَدًا زَكِيًّا طَاهِرًا مُبَارَكًا -عَطَفَ بِذِكْرِ قِصَّةِ مَرْيَمَ فِي إِيجَادِهِ وَلَدَهَا عِيسَى، عَلَيْهِمَا السَّلَامُ، مِنْهَا مِنْ غَيْرِ أَبٍ، فَإِنَّ بَيْنَ الْقِصَّتَيْنِ مُنَاسَبَةً وَمُشَابَهَةً ؛ وَلِهَذَا ذَكَرَهُمَا فِي آلِ عِمْرَانَ وَهَاهُنَا وَفِي سُورَةِ الْأَنْبِيَاءِ، يُقْرِنُ بَيْنَ الْقِصَّتَيْنِ لِتَقَارُبِ مَا بَيْنَهُمَا فِي الْمَعْنَى، لِيَدُلَّ عِبَادَهُ عَلَى قُدْرَتِهِ وعظمة سلطانه، وأنه على ما يشاء قَادِرٌ ، فَقَالَ: ﴿وَاذْكُرْ فِي الْكِتَابِ مَرْيَمَ﴾ وَهِيَ مَرْيَمُ بِنْتُ عِمْرَانَ، مِنْ سُلَالَةِ دَاوُدَ، عَلَيْهِ السَّلَامُ، وَكَانَتْ مِنْ بَيْتٍ طَاهِرٍ طَيِّبٍ فِي بَنِي إِسْرَائِيلَ.","en":"Ibn Kathir: having mentioned the story of Zakariyya and how Allah brought a child from him, He moves to an even more wondrous one: the creation of Isa from Maryam without a father."}}],"u":[{"id":"ad","cat":"u","n":"عاد","intro":"قوم هود بالأحقاف، أعطاهم الله بسطة في الخلق وقوة وعماراً، فاغتروا بقوتهم وكذّبوا رسولهم وقالوا «من أشد منا قوة»، فأهلكهم الله بريح صرصر عاتية.","eps":[{"t":"دعوة هود وحجة القوم","r":[7,65,72]},{"t":"الريح العارض","r":[46,21,26]},{"t":"اغترارهم بقوتهم","r":[41,15,16]},{"t":"الحاقة: ريح صرصر","r":[69,6,8]}],"ls":[{"t":"تذكير النعمة: خلفاء من بعد قوم نوح","r":[7,69,69],"q":{"bk":"saadi","w":"السعدي","s":7,"ay":65,"x":"{واذۡكُروا إذۡ جَعَلَكم خلفاء من بعد قوم نوح}؛ أي: واحمدوا ربَّكم، واشكُروه إذ مَكَّنَ لكم في الأرض، وجعلكم تخلُفون الأمم الهالكة الذين كذَّبوا الرسل، فأهلكهم الله، وأبقاكم لينظر كيف تعملون، واحذروا أن تقيموا على التكذيب كما أقاموا، فيصيبكم ما أصابهم، {و} اذكروا نعمة الله عليكم التي خصَّكم بها، وهي أن {زادكم في الخلق بَسۡطَةً}: في القوة وكبر الأجسام وشدَّة البطش، {فاذكُروا آلاءَ اللهِ}؛ أي: نعمه الواسعة وأياديه المتكررة، {لعلَّكُم}: إذا ذَكَرْتُموها بشكرها وأداء حقِّها، {تفلحونَ}؛ أي: تفوزون بالمطلوب، وتنجون من المرهوب.","en":"Al-Sa'di: remember and thank your Lord that He established you in the land and made you successors after the perished nations."}},{"t":"الجدال في أسماء لا حقيقة لها","r":[7,71,71],"q":{"bk":"saadi","w":"السعدي","s":7,"ay":65,"x":"{أتجادِلونَني في أسماءٍ سمَّيۡتموها أنتم وآباؤكم}؛ أي: كيف تجادلون على أمور لا حقائق لها وعلى أصنام سمَّيْتُموها آلهة وهي لا شيء من الإلهية فيها ولا مثقال ذرَّة و {ما أنزل الله بها من سلطانٍ}؛ فإنها لو كانت صحيحةً؛ لأنزل الله بها سلطانًا، فعدم إنزاله له دليلٌ على بطلانها؛ فإنه ما من مطلوب ومقصود ـ وخصوصاً الأمورَ الكبارَ ـ إلا وقد بيَّن الله فيها من الحجج ما يدلُّ عليها ومن السلطان ما لا تخفى معه، {فانتظروا}: ما يقعُ بكم من العقاب الذي وَعَدْتكم به.","en":"Al-Sa'di: how can you argue about things with no reality, idols you named gods that are nothing?"}},{"t":"عقوبة تناسب ما اغتروا به","r":[41,16,16],"q":{"bk":"saadi","w":"السعدي","s":41,"ay":15,"x":"{16} فعاقبهم الله عقوبةً تناسب قوَّتهم التي اغترُّوا بها، {فأرسلنا عليهم ريحاً صرصراً}؛ أي: ريحاً عظيمةً من قوتها وشدَّتها، لها صوتٌ مزعجٌ كالرعد القاصف، فسخَّرها الله {عليهم سبعَ ليالٍ وثمانيةَ أيَّام حسوماً فترى القومَ فيها صرعى كأنَّهم أعجازُ نخل خاويةٍ}، {نحسات}: فدمَّرتهم وأهلكتهم فأصبحوا لا يُرى إلاَّ مساكنُهم، وقال هنا:{لنذيقَهم عذابَ الخِزۡي في الحياة الدُّنيا}: الذي اختزوا به وافتُضِحوا بين الخليقة، {ولَعذابُ الآخرة أخزى وهم لا يُنصَرونَ}؛ أي: لا يُمنعون من عذاب الله، ولا يَنْفَعون أنفسَهم.","en":"Al-Sa'di: Allah punished them with a punishment suited to the strength they were deluded by: a furious wind of great strength and sound."}},{"t":"جزاء المجرمين بجرمهم وظلمهم","r":[46,25,25],"q":{"bk":"saadi","w":"السعدي","s":46,"ay":21,"x":"{كذلك نجزي القوم المجرمين}: بسبب جرمِهِم وظُلمهم.","en":"Al-Sa'di: \"Thus We repay the criminal people,\" because of their crime and wrongdoing."}},{"t":"التمكين والنعمة لم تغنِ عنهم لما لم يشكروا","r":[46,26,26],"q":{"bk":"saadi","w":"السعدي","s":46,"ay":21,"x":"{26} هذا مع أنَّ الله قد أدرَّ عليهم النِّعم العظيمة فلم يشكُروه ولا ذكَروه، ولهذا قال:{ولقد مكَّنَّاهم فيما إن مَكَّنَّاكم فيه}؛ أي: مكنَّاهم في الأرض يتناولون طيباتها، ويتمتَّعون بشهواتها، وعمَّرناهم عمراً يتذكَّر فيه من تذكَّر ويتَّعظ فيه المهتدي؛ أي: ولقد مكَّنَّا عاداً كما مكَّنَّاكم يا هؤلاء المخاطبون؛ أي: فلا تحسبوا أنَّ ما مَكَّنَّاكم فيه مختصٌّ بكم، وأنَّه سيدفع عنكم من عذاب الله شيئاً، بل غيرُكم أعظمُ منكم تمكيناً، فلم تُغْنِ عنهم أموالُهم ولا أولادُهم ولا جنودُهم من الله شيئاً، {وجَعَلۡنا لهم سمعاً وأبصاراً وأفئدةً}؛ أي: لا قصور في أسماعهم ولا أبصارهم ولا أذهانهم حتى يقال: إنَّهم تركوا الحقَّ جهلاً منهم وعدم تمكُّن من العلم به ولا خلل في عقولهم، ولكنَّ التوفيقَ بيدِ الله، {فما أغنى عنهم سمعُهم ولا أبصارُهم ولا أفئدتُهم من شيءٍ}: لا قليل ولا كثير، وذلك بسبب أنهم يجحدون آيات الله الدَّالَّة على توحيدِهِ وإفرادِهِ بالعبادة، {وحاق بهم ما كانوا به يستهزِئون}؛ أي: نزل بهم العذاب الذي يكذِّبون بوقوعه، ويستهزِئون بالرسل الذين حذَّروهم منه.","en":"Al-Sa'di: Allah had given them great blessings and they gave no thanks and did not remember Him."}}],"ctx":{"bk":"ibnkathir","w":"ابن كثير","s":7,"ay":65,"x":"يَقُولُ تَعَالَى: وَكَمَا أَرْسَلْنَا إِلَى قَوْمِ نُوحٍ نُوحًا، كَذَلِكَ أَرْسَلْنَا إِلَى عَادٍ أَخَاهُمْ هُودًا.","en":"Ibn Kathir: as We sent Nuh to the people of Nuh, so We sent Hud to Aad, the first Aad mentioned by Allah."},"sb":"الكبر والاغترار بالقوة، وتكذيب الرسول، وعبادة ما لا حقيقة له","uq":"ريح صرصر عاتية سُخّرت عليهم سبع ليال وثمانية أيام","sn":"من اغتر بقوته عوقب بما هو أقوى منه، والتمكين لا يمنع الهلاك إذا كُفرت النعمة"},{"id":"thamud","cat":"u","n":"ثمود","intro":"قوم صالح بالحجر، خلفاء من بعد عاد، نحتوا الجبال بيوتاً، فجاءتهم الناقة آية مبصرة، فعقروها وعتوا عن أمر ربهم فأخذتهم الصيحة والرجفة.","eps":[{"t":"دعوة صالح والناقة","r":[7,73,79]},{"t":"قرب الله ومجيبه","r":[11,61,68]},{"t":"الناقة فتنة لهم","r":[54,23,31]},{"t":"الشمس وضحاها: أشقاها","r":[91,11,15]}],"ls":[{"t":"الطغيان سبب التكذيب","r":[91,11,11],"q":{"bk":"saadi","w":"السعدي","s":91,"ay":11,"x":"{11 ـ 15}{كذَّبت ثمود بطَغۡواها}؛ أي: بسبب طغيانها وترفُّعها عن الحقِّ وعتوِّها على رسولهم ، {إذ انبعث أشقاها}؛ أي: أشقى القبيلة ، وهو قُدَار بن سالف؛ لعقرها؛ حين اتَّفقوا على ذلك وأمروه فائتمر لهم، {فقال لهم رسولُ اللهِ}: صالحٌ عليه السلام محذِّراً: {ناقة الله وسُقۡياها}؛ أي: احذروا عقر ناقة الله التي جعلها لكم آيةً عظيمةً، ولا تقابلوا نعمة الله عليكم بسقي لبنها أن تعقروها، فكذَّبوا نبيَّهم صالحاً، {فعقروها فدمدم عليهم ربُّهم بذنبهم}؛ أي: دمَّر عليهم، وعمَّهم بعقابه، وأرسل عليهم الصَّيحة من فوقهم والرَّجفة من تحتهم، فأصبحوا جاثمين على ركبهم، لا تجد منهم داعياً ولا مجيباً، {فسوَّاها}: عليهم؛ أي: سوَّى بينهم في العقوبة ، {ولا يخافُ عُقۡباها}؛ أي: تبعتها.","en":"Al-Sa'di: Thamud denied because of their transgression, rising above the truth and defiance against their messenger."}},{"t":"النعمة الكبرى صارت سبب هلاكهم","r":[54,27,27],"q":{"bk":"saadi","w":"السعدي","s":54,"ay":23,"x":"{27} لا جرم عاقبهم الله حين اشتدَّ طغيانُهم، فأرسل الله الناقة التي هي من أكبر النعم عليهم آية من آيات الله ونعمة؛ يحلبونَ من دَرِّها ما يكفيهم أجمعين، {فتنةً لهم}؛ أي: اختباراً منه لهم وامتحاناً، {فارتَقِبۡهم واصۡطَبِر}؛ أي: اصبر على دعوتك إيَّاهم وارتقبْ ما يحلُّ بهم، أو ارتقبْ هل يؤمنون أو يكفُرون.","en":"Al-Sa'di: without doubt Allah punished them when their rebellion grew intense; He sent the she-camel, among the greatest blessings and a sign of Allah."}},{"t":"من عتا عن أمر الله أذاقه العذاب","r":[7,77,77],"q":{"bk":"saadi","w":"السعدي","s":7,"ay":73,"x":"{وعَتَوا عن أمر ربِّهم}؛ أي: قسوا عنه واستكبروا عن أمره الذي مَنْ عتا عنه أذاقه العذاب الشديد، لا جرم أحلَّ الله بهم من النَّكال ما لم يُحِلَّ بغيرِهم.","en":"Al-Sa'di: they became hard and arrogant toward His command; whoever defies His command, Allah lets taste harsh punishment."}},{"t":"قوة الله وعزته في إهلاك الأمم الطاغية","r":[11,66,66],"q":{"bk":"saadi","w":"السعدي","s":11,"ay":61,"x":"{إنَّ ربَّك هو القويُّ العزيز}: ومن قوَّته وعزَّته أن أهلك الأممَ الطاغيةَ ونجَّى الرسلَ وأتباعهم.","en":"Al-Sa'di: from His power and might is that He destroyed the transgressing nations and saved the messengers and their followers."}},{"t":"منهج: لا تُنقل الإسرائيليات في تفسير القرآن","r":[7,78,78],"q":{"bk":"saadi","w":"السعدي","s":7,"ay":73,"x":"وهذا من الإسرائيليات التي لا ينبغي نقلها في تفسير كتاب الله، وليس في القرآن ما يدلُّ على شيء منها بوجه من الوجوه، بل لو كانت صحيحةً لَذَكَرها الله تعالى؛ لأن فيها من العجائب والعبر والآيات ما لا يهمله تعالى ويدع ذِكْرَهُ حتى يأتي من طريق مَنْ لا يوثَق بنقله، بل القرآن يكذِّب بعض هذه المذكورات؛ فإنَّ صالحاً قال لهم:{تمتَّعوا في دارِكُم ثلاثة [أيام]}؛ أي: تنعَّموا وتلذَّذوا بهذا الوقت القصير جدًّا؛ فإنه ليس لكم من المتاع واللَّذَّة سوى هذا، وأيُّ لذَّة وتمتُّع لمن وعدهم نبيُّهم وقوع العذاب وذكر لهم وقوع مقدِّماته فوقعت يوماً فيوماً على وجهٍ يعمُّهم ويشمُلهم؛ لأن احمرار وجوههم واصفرارها واسودادها من العذاب؟!","en":"Al-Sa'di: this is of the Isra'iliyyat that should not be transmitted in interpreting the Book of Allah; the Quran has nothing indicating any of it."}}],"ctx":{"bk":"ibnkathir","w":"ابن كثير","s":7,"ay":73,"x":"قَالَ عُلَمَاءُ التَّفْسِيرِ وَالنَّسَبِ: ثَمُودُ بْنُ عَاثِرَ بْنِ إِرَمَ بْنِ سَامَ بْنِ نُوحٍ، وَهُوَ أَخُو جَديس بْنِ عَاثِرَ، وَكَذَلِكَ قَبِيلَةُ طَسْم، كُلُّ هَؤُلَاءِ كَانُوا أَحْيَاءً مِنَ الْعَرَبِ الْعَارِبَةِ قَبْلَ إِبْرَاهِيمَ الْخَلِيلِ، عَلَيْهِ السَّلَامُ، وَكَانَتْ ثَمُودُ بَعْدَ عَادٍ، وَمَسَاكِنُهُمْ مَشْهُورَةٌ فِيمَا بَيْنَ الْحِجَازِ وَالشَّامِ إِلَى وَادِي الْقُرَى وَمَا حَوْلَهُ، وَقَدْ مَرَّ رَسُولُ اللَّهِ ﷺ عَلَى قُرَاهُمْ وَمَسَاكِنِهِمْ، وَهُوَ ذَاهِبٌ إِلَى تَبُوكَ سَنَةَ تِسْعٍ.","en":"Ibn Kathir: exegetes and genealogists say Thamud are the descendants of Athir son of Aram son of Sam son of Nuh."},"sb":"الطغيان والعتو عن أمر الله، وعقر الناقة الآية، واتباع أشقاهم","uq":"صيحة ورجفة فأصبحوا في ديارهم جاثمين","sn":"إذا اشتد الطغيان على الآية الواضحة نزل العذاب، ولا ينفع العاصي أن يرى الآية"},{"id":"lut","cat":"u","n":"قوم لوط","intro":"أهل قرى سدوم، ابتدعوا فاحشة لم يسبقهم بها أحد من العالمين، فنهاهم لوط فأصروا، ثم جاء الرسل إلى إبراهيم بالبشرى ثم إلى لوط بالإهلاك، فجعل الله عاليها سافلها وأمطر عليهم حجارة.","eps":[{"t":"الرسل إلى إبراهيم ثم لوط","r":[11,69,83]},{"t":"الفاحشة وعذاب القرية","r":[15,57,77]},{"t":"نهي لوط وإنكاره","r":[7,80,84]},{"t":"إني لعملكم من القالين","r":[26,160,175]}],"ls":[{"t":"اشتداد الفاحشة وانحلال المروءة","r":[11,78,78],"q":{"bk":"saadi","w":"السعدي","s":11,"ay":77,"x":"{78} ولهذا وَقَعَ ما خطر بباله، فجاءه {قومُهُ يُهۡرَعونَ إليه}؛ أي: يسرعون ويبادرون يريدون أضيافه بالفاحشة التي كانوا يعملونها، ولهذا قال:{ومِن قَبۡلُ كانوا يعملون السِّيئاتِ}؛ أي: الفاحشة التي ما سبقهم عليها أحدٌ من العالمين.","en":"Al-Sa'di: what he feared happened, for his people came rushing to him, wanting his guests for the indecency they used to commit."}},{"t":"دليل على انحلالهم من الخير والمروءة","r":[11,79,79],"q":{"bk":"saadi","w":"السعدي","s":11,"ay":77,"x":"وهذا دليلٌ على مروجهم وانحلالهم من الخير والمروءة.","en":"Al-Sa'di: this is evidence of their corruption and release from goodness and manliness."}},{"t":"كراهية العمل مع بقاء الشفقة على أهله","r":[26,168,168],"q":{"bk":"saadi","w":"السعدي","s":26,"ay":160,"x":"{168 ـ 175} فلما رأى استمرارَهم عليه؛ {قال إنِّي لِعَمَلِكُم من القالينَ}؛ أي: المبغضينَ [له] الناهينَ عنه المحذِّرين، قال:{ربِّ نَجِّني وأهلي ممَّا يعملونَ}: من فعلِهِ وعقوبتِهِ، فاستجابَ اللهُ له {فنجَّيۡناه وأهلَه أجمعينَ.","en":"Al-Sa'di: when he saw their persistence he said \"I am of those who hate your deed\", that is those who despise it, forbid and warn against it."}},{"t":"إذا أراد الله إهلاك قرية ازداد شرهم وطغيانهم","r":[15,77,77],"q":{"bk":"saadi","w":"السعدي","s":15,"ay":57,"x":"أن الله تعالى إذا أراد أن يُهْلِكَ قرية ازداد شرُّهم وطغيانهم؛ فإذا انتهى؛ أوقع بهم من العقوبات ما يستحقُّونه.","en":"Al-Sa'di: when Allah wills to destroy a town their evil and tyranny increase; then when it ends, He inflicts the punishment they deserve."}},{"t":"عناية الله بأوليائه عند الإهلاك","r":[15,77,77],"q":{"bk":"saadi","w":"السعدي","s":15,"ay":57,"x":"{77}{إنَّ في ذلك لآيةً للمؤمنين}: وفي هذه القصة من العبر: عنايتُه تعالى بخليله إبراهيم؛ فإنَّ لوطاً عليه السلام من أتباعه وممَّن آمن به، فكأنه تلميذٌ له؛ فحين أراد الله إهلاك قوم لوطٍ حين استحقُّوا ذلك؛ أمر رسله أن يمرُّوا على إبراهيم عليه السلام كي يبشِّروه بالولد ويخبروه بما بعثوا له، حتى إنَّه جادلهم عليه السلام في إهلاكهم، حتى أقنعوه، فطابت نفسُه، وكذلك لوط عليه السلام، لما كانوا أهل وطَنِهِ؛ فربما أخذتْه الرقة عليهم والرأفة بهم؛ قدَّر الله من الأسباب ما به يشتدُّ غيظُه وحِنْقُهُ عليهم، حتَّى استبطأ إهلاكَهم لمَّا قيل له:{إنَّ موعِدَهم الصبحُ أليس الصبحُ بقريبٍ}.","en":"Al-Sa'di: in this story is Allah's care for His friend Ibrahim, for Lut was among his followers who believed in him."}}],"ctx":{"bk":"ibnkathir","w":"ابن كثير","s":11,"ay":77,"x":"يُخْبِرُ تَعَالَى عَنْ قُدوم رُسُلِهِ مِنَ الْمَلَائِكَةِ بَعْدَ مَا أَعْلَمُوا إِبْرَاهِيمَ بِهَلَاكِهِمْ، وَفَارَقُوهُ وَأَخْبَرُوهُ بِإِهْلَاكِ اللَّهِ قَوْمَ لُوطٍ هَذِهِ اللَّيْلَةَ.","en":"Ibn Kathir: Allah informs of His messengers from the angels coming, after they had told Ibrahim, and they left him and came to Lut."},"sb":"إتيان الفاحشة التي ابتدعوها، وإصرارهم بعد النصح، وطردهم من يتطهر","uq":"قُلبت قراهم وأُمطروا بحجارة من سجيل، وأخذتهم الصيحة مشرقين","sn":"إذا بلغ الفساد منتهاه جاء أمر الله، وينجّي الله أهله وعباده المؤمنين"},{"id":"madyan","cat":"u","n":"أهل مدين","intro":"قوم شعيب، جمعوا الشرك وبخس المكيال والميزان وقطع الطريق على الناس، فدعاهم شعيب إلى التوحيد والعدل في الأموال، فاستهزؤوا وهددوه، فأخذتهم الرجفة والصيحة.","eps":[{"t":"دعوة شعيب إلى التوحيد والعدل","r":[11,84,93]},{"t":"نهيه عن القعود بالطريق","r":[7,85,93]}],"ls":[{"t":"الأمر بالعدل في الكيل والميزان","r":[11,85,85],"q":{"bk":"saadi","w":"السعدي","s":11,"ay":84,"x":"{85}{ويا قوم أوفوا المكيالَ والميزان بالقِسۡطِ}؛ أي: بالعدل الذي ترضَوْن أن تعطوه، {ولا تَبخَسوا الناس أشياءهم}؛ أي: لا تنقصوا من أشياء الناس، فتسرقوها بأخذها بنقص المكيال والميزان، {ولا تَعۡثَوۡا في الأرض مفسِدينَ}: فإنَّ الاستمرار على المعاصي يفسِدُ الأديان والعقائد والدِّين والدُّنيا ويهلِكُ الحرثَ والنسل.","en":"Al-Sa'di: \"give full measure and weight in justice,\" meaning the justice you would like to receive, \"and do not diminish people's due.\""}},{"t":"التهكم بالصلاح والاستهزاء بالناصح","r":[11,87,87],"q":{"bk":"saadi","w":"السعدي","s":11,"ay":84,"x":"{87}{قالوا يا شُعيبُ أصلاتُكَ تأمُرُك أن نَتۡرُكَ ما يعبدُ آباؤنا}؛ أي: قالوا ذلك على وجه التهكُّم بنبيِّهم والاستبعاد لإجابتهم له، ومعنى كلامهم: أنَّه لا موجب لنهيك لنا إلاَّ أنك تصلي لله وتتعبَّد له؛ أفإنْ كنتَ كذلك؛ أفيوجِبُ لنا أن نتركَ ما يعبدُ آباؤنا لقولٍ ليس عليه دليلٌ إلاَّ أنه موافقٌ لك؟!","en":"Al-Sa'di: they said it in mockery of their prophet and finding his response unlikely."}},{"t":"الجزاء من جنس العمل","r":[11,84,84],"q":{"bk":"saadi","w":"السعدي","s":11,"ay":84,"x":"أنَّ الجزاء من جنس العمل؛ فمن بَخَسَ أموال الناس يريد زيادة ماله؛ عوقِبَ بنقيض ذلك، وكان سبباً لزوال الخير الذي عنده من الرزق؛ لقوله:{إني أراكم بخيرٍ}؛ أي: فلا تتسبَّبوا إلى زواله بفعلكم.","en":"Al-Sa'di: the recompense matches the deed; whoever cheats people's property to increase his own is punished with the opposite."}},{"t":"الترهيب بأخذات الأمم في الوعظ","r":[11,94,94],"q":{"bk":"saadi","w":"السعدي","s":11,"ay":84,"x":"الترهيب بأخذات الأمم، وما جرى عليهم، وأنه ينبغي أنْ تُذْكَرَ القَصصُ التي فيها إيقاعُ العقوبات بالمجرمين في سياق الوعظ والزجر؛ كما أنه ينبغي ذِكْرُ ما أكرم الله به أهل التقوى عند الترغيب والحثِّ على التقوى.","en":"Al-Sa'di: warning with the seizures of nations, what befell them, and that stories of punishments of criminals should be mentioned in the context of preaching."}},{"t":"التائب من الذنب يحبه الله","r":[11,90,90],"q":{"bk":"saadi","w":"السعدي","s":11,"ay":84,"x":"أن التائب من الذنب كما يُسمح له عن ذنبه ويُعفى عنه؛ فإنَّ الله تعالى يحبُّه ويودُّه، ولا عبرة بقول من يقول: إنَّ التائبَ إذا تاب؛ فحسبُه أن يُغْفَرَ له ويعودَ عليه العفو، وأما عَوْدُ الودِّ والحبِّ؛ فإنه لا يعودُ؛ فإنَّ الله قال:{واستغفِروا ربَّكم ثمَّ توبوا إليه إنَّ ربي رحيمٌ ودودٌ}.","en":"Al-Sa'di: the repentant is forgiven and pardoned, and Allah loves him and holds him dear."}}],"ctx":{"bk":"ibnkathir","w":"ابن كثير","s":11,"ay":84,"x":"يَقُولُ تَعَالَى: وَلَقَدْ أَرْسَلْنَا إِلَى مَدْيَنَ -وَهُمْ قَبِيلَةٌ مِنَ الْعَرَبِ، كَانُوا يَسْكُنُونَ بَيْنَ الْحِجَازِ وَالشَّامِ، قَرِيبًا مِنْ بِلَادِ مَعَانٍ، فِي بَلَدٍ يُعْرَفُ بِهِمْ، يُقَالُ لَهَا \"مَدْيَنُ\" فَأَرْسَلَ اللَّهُ إِلَيْهِمْ شُعَيْبًا، وَكَانَ مِنْ أَشْرَفِهِمْ نَسَبًا.","en":"Ibn Kathir: We sent to Madyan, an Arab tribe living between the Hijaz and Sham near Ma'an, their brother Shu'ayb."},"sb":"الشرك والغش في المكيال والميزان والقعود بالطريق وصد الناس عن سبيل الله","uq":"الرجفة والصيحة فأصبحوا في ديارهم جاثمين","sn":"الجزاء من جنس العمل، ومن بخس الناس عُوقب بزوال ما عنده"},{"id":"firaun","cat":"u","n":"فرعون وقومه","intro":"طاغية علا في الأرض وجعل أهلها شيعاً يستضعف طائفة منهم، وادعى الربوبية، واستخفّ قومه فأطاعوه، فكذّب موسى وجنوده فأغرقهم الله في اليم، وأبقى بدنه آية.","eps":[{"t":"علو فرعون في الأرض","r":[28,4,6]},{"t":"استكباره وجنوده","r":[28,38,42]},{"t":"رجل مؤمن من آل فرعون","r":[40,23,46]},{"t":"غرّه ملكه","r":[43,46,56]},{"t":"الغرق وبدنه آية","r":[10,90,92]}],"ls":[{"t":"العلو في الأرض من أهل العلو لا من الأعلين","r":[28,4,4],"q":{"bk":"saadi","w":"السعدي","s":28,"ay":38,"x":"{4} فأول هذه القصَّة: {إنَّ فرعون علا في الأرض}: في ملكه وسلطانِهِ وجنودِهِ وجبروتِهِ، فصار من أهل العلوِّ فيها، لا من الأعْلَيْن فيها، {وجعل أهلها شِيَعاً}؛ أي: طوائف متفرِّقة يتصرَّف فيهم بشهوته وينفِّذ فيهم ما أراد من قهره وسطوته، {يستضعِفُ طائفةً منهم}: وتلك الطائفةُ هم بنو إسرائيل، الذين فضَّلهم الله على العالمين، الذي ينبغي له أن يكرِمَهم ويجلَّهم، ولكنه استضعفهم بحيثُ إنه رأى أنَّهم لا مَنَعَةَ لهم تمنعُهم مما أراده فيهم، فصار لا يُبالي بهم ولا يهتمُّ بشأنهم، وبلغت به الحال إلى أنَّه {يُذَبِّح أبناءهم ويَسۡتَحيي نساءهم}: خوفاً من أن يكثرُوا فيغمروه في بلاده، ويصير لهم الملك.","en":"Al-Sa'di: the story begins with Pharaoh exalting himself in the land in his power, soldiers and tyranny, so that he became one of the arrogant and not of the truly high."}},{"t":"الاستكبار بغير الحق هو أصل الهلاك","r":[28,39,39],"q":{"bk":"saadi","w":"السعدي","s":28,"ay":38,"x":"{39} قال تعالى: {واستكبر هو وجنودُهُ في الأرضِ بغيرِ الحقِّ}: استكبروا على عبادِ الله، وساموهم سوء العذاب، واستكبروا على رسل الله وما جاؤوهم به من الآيات، فكذَّبوها، وزعموا أنَّ ما هم عليه أعلى منها وأفضل، {وظنُّوا أنَّهم إلينا لا يُرۡجَعون}: فلذلك تجرَّؤوا، وإلاَّ؛ فلو علموا أو ظنُّوا أنَّهم يُرْجَعون إلى الله؛ لما كان منهم ما كان.","en":"Al-Sa'di: he and his soldiers were arrogant against the servants of Allah, who they oppressed, and arrogant against Allah's messengers."}},{"t":"غرّه ملكه وأطغاه ماله وجنوده","r":[43,51,51],"q":{"bk":"saadi","w":"السعدي","s":43,"ay":46,"x":"{51}{ونادى فرعونُ في قومه قال}: مستعلياً بباطلِهِ قد غرَّه مُلكه وأطغاه مالُه وجنودُه: {يا قوم أليس لي ملكُ مصرَ}؛ أي: ألست المالك لذلك المتصرف فيه؟","en":"Al-Sa'di: Pharaoh called in his people in arrogance with falsehood; his kingdom had deceived him and his wealth and soldiers had made him a tyrant."}},{"t":"استخف عقول قومه بشبه لا حقيقة لها","r":[43,54,54],"q":{"bk":"saadi","w":"السعدي","s":43,"ay":46,"x":"{54}{فاستخفَّ قومَه فأطاعوه}؛ أي: استخفَّ عقولَهم بما أبدى لهم من هذه الشُّبه، التي لا تسمن ولا تغني من جوع، ولا حقيقة تحتها، وليست دليلاً على حقٍّ ولا على باطل، ولا تروج إلاَّ على ضعفاء العقول؛ فأيُّ دليل يدلُّ على أن فرعون محقٌّ لكون ملك مصرَ له وأنهاره تجري من تحته؟!","en":"Al-Sa'di: he made light of their minds with the doubts he showed them, which neither fatten nor satisfy hunger and have no reality."}},{"t":"فسق القوم هو الذي سلّط عليهم فرعون","r":[43,54,54],"q":{"bk":"saadi","w":"السعدي","s":43,"ay":46,"x":"{إنَّهم كانوا قوماً فاسقينَ}: فبسبب فسقِهِم قيَّض لهم فرعونَ، يزيِّن لهم الشركَ والشرَّ.","en":"Al-Sa'di: because of their wickedness Allah appointed Pharaoh for them to adorn shirk and evil."}},{"t":"سنة الأمم: «مثل دأب قوم نوح وعاد وثمود»","r":[40,31,31],"q":{"bk":"saadi","w":"السعدي","s":40,"ay":23,"x":"{31} ثم بيَّنهم فقال: {مثل دأب قوم نوح وعادٍ وثمودَ والذين من بعدِهم}؛ أي: مثل عادتهم في الكفر والتكذيب، وعادة الله فيهم بالعقوبة العاجلة في الدنيا قبل الآخرة، {وما الله يريدُ ظلماً للعبادِ}: فيعذِّبُهم بغير ذنب أذنبوه ولا جرم أسْلَفوه.","en":"Al-Sa'di: like their habit in disbelief and denial, and Allah's habit with them of general punishment."}},{"t":"بدنه آية لمن خلفه","r":[10,92,92],"q":{"bk":"saadi","w":"السعدي","s":10,"ay":75,"x":"{92}{فاليوم ننجِّيك ببدنِكَ لتكون لمن خلفك آيةً}: قال المفسِّرون: إنَّ بني إسرائيل لما في قلوبهم من الرعب العظيم من فرعون، كأنَّهم لم يصدِّقوا بإغراقه، وشكُّوا في ذلك، فأمر الله البحر أن يلقِيَهُ على نجوة مرتفعةٍ ببدنه؛ ليكون لهم عبرة وآية.","en":"Al-Sa'di: the exegetes say Israelites' great fear of Pharaoh made them doubt his drowning, so Allah commanded the sea to cast him up on a high place."}}],"ctx":{"bk":"ibnkathir","w":"ابن كثير","s":28,"ay":4,"x":"ثُمَّ قَالَ: ﴿إِنَّ فِرْعَوْنَ عَلا فِي الأرْضِ﴾ أَيْ: تَكَبَّرَ وَتَجَبَّرَ وَطَغَى. ﴿وَجَعَلَ أَهْلَهَا شِيَعًا﴾ أَيْ: أَصْنَافًا، قَدْ صَرَّفَ كُلَّ صِنْفٍ فِيمَا يُرِيدُ مِنْ أُمُورِ دَوْلَتِهِ.","en":"Ibn Kathir: \"Pharaoh exalted himself in the land,\" that is, he was arrogant, tyrannical and rebellious, \"and made its people factions,\" groups, each directed to what he wanted of the affairs of his state."},"sb":"العلو في الأرض والاستكبار بغير الحق، وادعاء الربوبية، واستخفاف الناس","uq":"الإغراق في اليم، وبقاء بدنه آية لمن خلفه","sn":"سنة الله في المستكبرين: عذاب قوم نوح وعاد وثمود ومن بعدهم، والعبرة لمن خلفهم"},{"id":"qarun","cat":"u","n":"قارون","intro":"من قوم موسى، آتاه الله من الكنوز ما إن مفاتحه لتنوء بالعصبة أولي القوة، فبغى على قومه وقال إنما أوتيته على علم عندي، فخسف الله به وبداره الأرض.","eps":[{"t":"نصيحة قومه","r":[28,76,77]},{"t":"إنما أوتيته على علم","r":[28,78,80]},{"t":"الخسف","r":[28,81,82]},{"t":"عاقبة الدار الآخرة","r":[28,83,84]}],"ls":[{"t":"النهي عن الفرح البطر","r":[28,76,76],"q":{"bk":"saadi","w":"السعدي","s":28,"ay":76,"x":"{إذ قال له قومُهُ}: ناصحين له محذِّرين له عن الطُّغيان: {لا تَفۡرَحۡ إن الله لا يحبُّ الفرِحينَ}؛ أي: لا تفرحْ بهذه الدُّنيا العظيمة، وتفتخرْ بها، وتلهيك عن الآخرة؛ فإنَّ الله لا يحبُّ الفرحين بها المكبِّين على محبَّتها.","en":"Al-Sa'di: his people counselled him, warning him against tyranny: \"Do not exult; Allah does not love the exultant.\""}},{"t":"نسبة النعمة إلى النفس والعلم جحود","r":[28,78,78],"q":{"bk":"saadi","w":"السعدي","s":28,"ay":76,"x":"{78} فَـ {قَالَ} قارونُ رادًّا لنصيحتِهِم كافراً لنعمةِ ربِّه: {إنَّما أوتيتُهُ على علم عندي}؛ أي: إنَّما أدركتُ هذه الأموالَ بكسبي ومعرفتي بوجوه المكاسب وحِذْقي.","en":"Al-Sa'di: Qarun rejected their counsel in ingratitude to his Lord's blessing, saying \"I was given it only because of knowledge.\""}},{"t":"العطاء ليس دليلاً على حسن حال المعطى","r":[28,78,78],"q":{"bk":"saadi","w":"السعدي","s":28,"ay":76,"x":"قال تعالى مبيِّناً أنَّ عطاءَه ليس دليلاً على حسنِ حالةِ المُعْطَى:{أوَلَمۡ يعلمۡ أنَّ الله قد أهۡلَكَ من قبلِهِ من القرونِ مَنۡ هو أشدُّ منه قوَّةً وأكثرُ جمعاً}: فما المانعُ من إهلاك قارون مع مضيِّ عادتِنا وسنَّتِنا بإهلاك مَن هُو مثلُه وأعظمُ منه إذا فَعَلَ ما يوجِب الهلاك؟!","en":"Al-Sa'di: Allah made clear that His giving is not evidence of the receiver's good state: Did he not know that Allah destroyed before him generations stronger and with more wealth?"}},{"t":"أهل العلم ينظرون إلى باطن الدنيا","r":[28,80,80],"q":{"bk":"saadi","w":"السعدي","s":28,"ay":76,"x":"{80}{وقال الذين أوتوا العلم}: الذين عرفوا حقائقَ الأشياء ونظروا إلى باطن الدنيا حين نظر أولئك إلى ظاهرها: {ويلَكُم}: متوجِّعين من ما تمنَّوا لأنفسهم، راثين لحالهم، منكرين لمقالهم، {ثوابُ الله}: العاجلُ من لذَّة العبادة ومحبَّته والإنابة إليه والإقبال عليه، والآجلُ من الجنَّة وما فيها ممَّا تشتهيه الأنفس وتلذُّ الأعينُ خير من هذا الذي تمنَّيْتُم ورغبتُم فيه؛ فهذه حقيقة الأمر، ولكنْ ما كلُّ مَنْ يعلم ذلك يؤثر الأعلى على الأدنى، فما يُلَقَّى ذلك ويوفَّقُ له {إلاَّ الصابِرونَ}: الذين حبسوا أنفسَهم على طاعة الله وعن معصيتِهِ وعلى أقدارِهِ المؤلمةِ وصبروا على جواذب الدُّنيا وشهواتِها أن تَشْغَلَهم عن ربِّهم وأن تحولَ بينهم وبينَ ما خُلِقوا له؛ فهؤلاء الذين يؤثرون ثوابَ الله على الدُّنيا الفانية.","en":"Al-Sa'di: those given knowledge, who knew the realities of things and looked to the inner side of this life when others looked at its outside, said \"Woe to you! Allah's reward is better.\""}},{"t":"إذا بلغ البغي منتهاه بغته العذاب","r":[28,81,81],"q":{"bk":"saadi","w":"السعدي","s":28,"ay":76,"x":"{81} فلما انتهت بقارونَ حالةُ البغي والفخرِ، وازَّيَّنت الدُّنيا عنده، وكَثُر بها إعجابُه؛ بَغَتَهُ العذاب، {فَخَسَفۡنا به وبدارِهِ الأرضَ}: جزاء من جنس عملِهِ؛ فكما رفع نفسه على عباد الله؛ أنزله الله أسفلَ سافلين هو وما اغترَّ به من داره وأثاثِهِ ومتاعِهِ.","en":"Al-Sa'di: when Qarun reached the state of tyranny and boasting and the world was adorned for him, the punishment came suddenly."}},{"t":"لا فئة تنصر من دون الله","r":[28,81,81],"q":{"bk":"saadi","w":"السعدي","s":28,"ay":76,"x":"{فما كان له من فئةٍ}؛ أي: جماعةٍ وعصبةٍ وخدمٍ وجنودٍ، {ينصرونَه من دونِ الله وما كان من المنتصرين}؛ أي: جاءه العذاب فما نُصِرَ ولا انْتَصَرَ.","en":"Al-Sa'di: he had no group, band, servants or soldiers to help him besides Allah, nor was he of the victorious."}},{"t":"عرفنا أن بسطه ليس دليل خير فيه","r":[28,82,82],"q":{"bk":"saadi","w":"السعدي","s":28,"ay":76,"x":"{82}{وأصبح الذين تَمَنَّوا مكانه بالأمس}؛ أي: الذين يريدونَ الحياة الدنيا، الذين قالوا: يا ليت لنا مثل ما أوتي قارونُ {يقولون}: متوجِّعين ومعتَبِرين وخائفينَ من وقوع العذاب بهم: {ويكأنَّ اللهَ يَبۡسُطُ الرزقَ لِمَن يشاءُ من عبادِهِ ويقدِرُ}؛ أي: يضيِّقُ الرزق على من يشاء. فعلمنا حينئذٍ أنَّ بسطَه لقارون ليس دليلاً على خير فيه، وأنَّنا غالطون في قولنا: إنَّه لذو حظٍّ عظيم، و {لولا أن مَنَّ الله علينا}: فلم يعاقِبْنا على ما قُلْنا؛ فلولا فضلُه ومنَّتُه؛ {لخسف بنا}: فصار هلاكُ قارون عقوبةً له وعبرةً وموعظةً لغيرِهِ، حتى إنَّ الذين غبطوه سمعتَ كيف ندِموا، وتغيَّر فِكْرُهم الأول، {ويكأنَّه لا يفلحُ الكافرون}؛ أي: لا في الدنيا، ولا في الآخرة.","en":"Al-Sa'di: those who wished his place saw the result and knew that his expansion was no evidence of good in him and that they had been mistaken."}}],"ctx":{"bk":"ibnkathir","w":"ابن كثير","s":28,"ay":76,"x":"* * وَقَوْلُهُ: ﴿إِذْ قَالَ لَهُ قَوْمُهُ لا تَفْرَحْ إِنَّ اللَّهَ لا يُحِبُّ الْفَرِحِينَ﴾ أَيْ: وَعَظَهُ فِيمَا هُوَ فِيهِ صَالِحُ قَوْمِهِ، فَقَالُوا عَلَى سَبِيلِ النُّصْحِ وَالْإِرْشَادِ: لَا تَفْرَحْ بِمَا أَنْتَ فِيهِ، يَعْنُونَ: لَا تَبْطَرْ بِمَا أَنْتَ فِيهِ مِنَ الْأَمْوَالِ ﴿إِنَّ اللَّهَ لَا يُحِبُّ الْفَرِحِينَ﴾ قَالَ ابْنُ عَبَّاسٍ: يَعْنِي الْمَرِحِينَ.","en":"Ibn Kathir: his righteous people counselled him in guidance and advice: \"Do not exult; Allah does not love the exultant.\""},"sb":"الفرح البطر وجحود النعمة ونسبتها إلى النفس، والبغي على الناس","uq":"خسف به وبداره الأرض فما كان له من فئة ينصرونه","sn":"بسط الرزق ليس دليلاً على رضا الله، والعاقبة لمن لم يرد علواً في الأرض ولا فساداً"},{"id":"saba","cat":"u","n":"قوم سبأ","intro":"أهل مأرب باليمن، جنتان عن يمين وشمال وسد عظيم وبلدة طيبة وقرى ظاهرة، فأعرضوا وبطروا النعمة، فأرسل الله عليهم سيل العرم وبدّلهم بجنتيهم جنتين ذواتي أكل خمط، وتفرقوا في البلاد.","eps":[{"t":"الجنتان والبلدة الطيبة","r":[34,15,16]},{"t":"بطر النعمة والتمزيق","r":[34,17,19]},{"t":"صدّق عليهم إبليس ظنه","r":[34,20,21]}],"ls":[{"t":"الله وعدهم إن شكروا أن يغفر لهم ويرحمهم","r":[34,15,15],"q":{"bk":"saadi","w":"السعدي","s":34,"ay":15,"x":"أنَّ الله تعالى وَعَدَهم إن شكروه أن يغفرَ لهم ويرحَمَهم، ولهذا قال:{بلدةٌ طيبةٌ وربٌّ غفورٌ}.","en":"Al-Sa'di: Allah promised them, if they thanked Him, that He would forgive and have mercy on them, hence \"a good land and a forgiving Lord.\""}},{"t":"بطروا النعمة وملّوها حتى طلبوا تباعد أسفارهم","r":[34,19,19],"q":{"bk":"saadi","w":"السعدي","s":34,"ay":15,"x":"فأعْرَضوا عن المنعِم وعن عبادتِهِ، وبَطِروا النعمةَ وملُّوها، حتى إنَّهم طلبوا وتمنَّوا أن تتباعد أسفارُهم بين تلك القرى التي كان السير فيها متيسراً.","en":"Al-Sa'di: they turned from the Giver and His worship, were insolent and tired of the blessing, even wishing their journeys to be longer."}},{"t":"عاقبهم بالنعمة التي أطغتهم","r":[34,19,19],"q":{"bk":"saadi","w":"السعدي","s":34,"ay":15,"x":"{وظلموا أنۡفُسَهم}: بكفرِهِم بالله وبنعمتِهِ، فعاقَبَهُمُ الله تعالى بهذه النعمة التي أطْغَتْهم، فأبادها عليهم، فأرسل عليها {سيلَ العَرِم}؛ أي: السيل المتوعِّر الذي خَرَّبَ سدَّهم، وأتلف جناتهم، وخرَّبَ بساتينَهم، فتبدَّلت تلك الجناتُ ذات الحدائق المعجِبَة والأشجار المثمرة، وصار بَدَلَها أشجارٌ لا نفعَ فيها.","en":"Al-Sa'di: they wronged themselves by disbelieving in Allah and His blessing; so Allah punished them with the blessing that made them tyrannical."}},{"t":"«هل نجازي إلا الكفور»","r":[34,17,17],"q":{"bk":"saadi","w":"السعدي","s":34,"ay":15,"x":"ولهذا قال:{ذلك جَزَيۡناهم بما كفروا وهل نُجازي إلاَّ الكفورَ}؛ أي: وهل نُجازي جزاء العقوبة ـ بدليل السياق ـ إلاَّ مَنْ كَفَرَ بالله وبَطِرَ النعمة؟!","en":"Al-Sa'di: \"That was Our recompense for their disbelief, and do We punish anyone but the ungrateful?\" the punishing recompense according to the context."}},{"t":"صاروا أحاديث يُتحدث بها","r":[34,19,19],"q":{"bk":"saadi","w":"السعدي","s":34,"ay":15,"x":"فلمَّا أصابَهم ما أصابَهم؛ تفرَّقوا وتمزَّقوا بعدما كانوا مجتمعينَ، وجَعَلَهُمُ الله أحاديثَ يُتَحَدَّث بهم وأسماراً للناس، وكان يُضْرَبُ بهم المثلُ، فيقالُ:«تفرَّقوا أيدي سبأ»؛ فكلُّ أحدٍ يتحدَّث بما جرى لهم، ولكنْ لا ينتفعُ بالعبرة فيهم إلاَّ مَنْ قال الله:{إنَّ في ذلك لآياتٍ لكلِّ صبارٍ شكورٍ}: صبَّارٍ على المكاره والشدائدِ، يتحمَّلُها لوجه الله، ولا يتسخَّطُها، بل يصبرُ عليها، شكورٍ لنعمة الله تعالى، يُقِرُّ بها، ويعترفُ، ويثني على من أولاها، ويصرِفُها في طاعته. فهذا إذا سمع بقصَّتِهم وما جرى منهم وعليهم؛ عَرَفَ بذلك أنَّ تلك العقوبة جزاءٌ لكفرِهم نعمةَ الله، وأنَّ مَنْ فَعَلَ مثلهم؛ فُعِلَ به كما فُعِلَ بهم، وأنَّ شُكْرَ الله تعالى حافظٌ للنعمة دافعٌ للنقمة، وأنَّ رُسُلَ الله صادقون فيما أخبروا به، وأنَّ الجزاء حقٌّ كما رأى أنموذَجَه في دار الدنيا.","en":"Al-Sa'di: when it befell them they scattered after being together, and Allah made them tales; whoever hears of what happened to them knows that punishment was for their ingratitude."}}],"ctx":{"bk":"ibnkathir","w":"ابن كثير","s":34,"ay":15,"x":"وَبَعَثَ اللَّهُ إِلَيْهِمُ الرُّسُلَ تَأْمُرُهُمْ أَنْ يَأْكُلُوا مِنْ رِزْقِهِ، وَيَشْكُرُوهُ بِتَوْحِيدِهِ وَعِبَادَتِهِ، فَكَانُوا كَذَلِكَ مَا شَاءَ اللَّهُ ثُمَّ أَعْرَضُوا عَمَّا أُمِرُوا بِهِ، فَعُوقِبُوا بِإِرْسَالِ السَّيْلِ وَالتَّفَرُّقِ فِي الْبِلَادِ أَيْدِيَ سَبَأٍ، شَذَرَ مَذرَ، كَمَا يَأْتِي تَفْصِيلُهُ وَبَيَانُهُ قَرِيبًا إِنْ شَاءَ اللَّهُ تَعَالَى وَبِهِ الثِّقَةُ.","en":"Ibn Kathir: Allah sent messengers to them commanding them to eat of His provision and thank Him by His oneness and worship; they did so for as long as Allah willed, then turned away and were punished by the flood and scattering in the lands."},"sb":"الإعراض عن المنعم وبطر النعمة وطلب تباعد الأسفار، وظلم النفس","uq":"سيل العرم وتبديل الجنتين وتمزيقهم كل ممزق","sn":"الشكر يحفظ النعمة والكفر يزيلها: «هل نجازي إلا الكفور»"},{"id":"jannah","cat":"u","n":"أصحاب الجنة","intro":"مثل ضربه الله لمشركي مكة: أصحاب جنة أقسموا ليصرمنها مصبحين ولا يستثنون، فطاف عليها طائف من ربك وهم نائمون فأصبحت كالصريم، فتلاوموا ورجعوا إلى ربهم تائبين.","eps":[{"t":"ابتلاء أصحاب الجنة","r":[68,17,20]},{"t":"التخافت بمنع الفقراء","r":[68,21,25]},{"t":"الندم والتلاوم","r":[68,26,33]}],"ls":[{"t":"ابتلاء المكذبين بالإمهال والنعمة","r":[68,17,17],"q":{"bk":"saadi","w":"السعدي","s":68,"ay":17,"x":"{17 ـ 18} يقول تعالى: إنَّا بَلَوْنا هؤلاء المكذِّبين بالخير، وأمهلناهم، وأمددناهم بما شئنا من مال وولدٍ وطول عمرٍ ونحو ذلك ممَّا يوافق أهواءهم، لا لكرامتهم علينا، بل ربَّما يكون استدراجاً لهم من حيثُ لا يعلمون، فاغترارهم بذلك نظيرُ اغترار أصحاب الجنَّة الذين هم فيها شركاء، حين أينعت أشجارها، وزهت ثمارها ، وآن وقت صِرامها وجزموا أنَّها في أيديهم وطوع أمرهم، وأنَّه ليس ثَمَّ مانعٌ يمنعهم منها، ولهذا أقسموا وحلفوا من غير استثناءٍ أنَّهم سيصرمونها؛ أي: يجذُّونها مصبحين، ولم يَدْروا أنَّ الله بالمرصادِ، وأنَّ العذاب سيخلفهم عليها ويبادِرُهم إليها.","en":"Al-Sa'di: Allah tested those who deny the good: He gave them respite and supplied them with wealth, children and long life."}},{"t":"شدة الحرص والبخل: تخافتوا لئلا يعلم الفقراء","r":[68,24,24],"q":{"bk":"saadi","w":"السعدي","s":68,"ay":17,"x":"ومن شدَّة حرصهم وبخلهم أنَّهم يتخافتون بهذا الكلام مخافتةً خوفاً أن يَسْمَعَهم أحدٌ فيخبر الفقراء.","en":"Al-Sa'di: from their strong greed and miserliness they whispered this, fearing someone would tell the poor."}},{"t":"«قال أوسطهم ألم أقل لكم لولا تسبحون»","r":[68,28,28],"q":{"bk":"saadi","w":"السعدي","s":68,"ay":17,"x":"{28} فَـ {قَالَ أوسطُهم}؛ أي: أعدلُهم وأحسنُهم طريقةً: {ألم أقل لكم لولا تسبِّحونَ}؛ أي: تنزِّهون الله عما لا يليق به، ومن ذلك ظنُّكم أنَّ قدرتكم مستقلةٌ، فلولا استثنيتم وقلتُم: إنْ شاء الله، وجعلتم مشيئتكم تابعةً لمشيئتِهِ ؛ لما جرى عليكم ما جرى.","en":"Al-Sa'di: the most just and best of them in conduct said, \"Did I not say to you, why do you not glorify Allah,\" that is, declare Him above what does not befit Him."}},{"t":"الاعتراف بعد وقوع العذاب","r":[68,29,29],"q":{"bk":"saadi","w":"السعدي","s":68,"ay":17,"x":"{29} فَـ {قالوا سبحانَ ربِّنا إنَّا كُنَّا ظالمين}؛ أي: استدركوا بعد ذلك، ولكن بعدما وقع العذاب على جنتهم، الذي لا يُرفع، ولكن لعلَّ تسبيحهم هذا وإقرارهم على أنفسهم بالظُّلم ينفعهم في تخفيف الإثم ويكونُ توبةً. {30 ـ 32} ولهذا ندموا ندامةً عظيمةً، وأقبل {بعضُهم على بعضٍ يتلاومونَ}: فيما أجروه وفعلوه، {قالوا يا وَيۡلَنا إنا كُنَّا طاغينَ}؛ أي: متجاوزين للحدِّ في حقِّ الله وحقِّ عباده، {عسى ربُّنا أن يُبۡدِلَنا خيراً منها إنَّا إلى ربِّنا راغبونَ}: فهم رجوا الله أن يبدِّلهم خيراً منها، ووعدوا أن سيرغبون إلى الله ويلحُّون عليه في الدُّنيا؛ فإنْ كانوا كما قالوا؛ فالظاهر أنَّ الله أبدلهم في الدُّنيا خيراً منها؛ لأنَّ من دعا الله صادقاً ورغب إليه ورجاه؛ أعطاه سؤاله.","en":"Al-Sa'di: they corrected themselves afterwards, but after the punishment had fallen on their garden; so they felt great regret, blaming one another."}},{"t":"كذلك العذاب: سلب ما طغى به الإنسان","r":[68,33,33],"q":{"bk":"saadi","w":"السعدي","s":68,"ay":17,"x":"{33} قال تعالى معظماً ما وقع: {كذلك العذابُ}؛ أي: الدنيويُّ لمن أتى بأسباب العذاب أن يسلبَه الله الشيء الذي طغى به وبغى وآثَرَ الحياةَ الدُّنيا وأن يزيلَه عنه أحوجَ ما يكون إليه، {ولَعذابُ الآخرةِ أكبرُ}: من عذاب الدُّنيا، {لو كانوا يعلمون}: فإنَّ مَنْ عَلِمَ ذلك؛ أوجب له الانزجار عن كلِّ سبب يوجب العقاب ويحرم الثواب.","en":"Al-Sa'di: such is worldly punishment for whoever brings its causes: Allah takes from him the thing by which he rebelled."}}],"ctx":{"bk":"ibnkathir","w":"ابن كثير","s":68,"ay":17,"x":"هَذَا مَثَل ضَرَبه اللَّهُ تَعَالَى لِكُفَّارِ قُرَيْشٍ فِيمَا أَهْدَى إِلَيْهِمْ مِنَ الرَّحْمَةِ الْعَظِيمَةِ، وَأَعْطَاهُمْ مِنَ النِّعَمِ الْجَسِيمَةِ، وَهُوَ بَعْثُهُ مُحَمَّدًا ﷺ إِلَيْهِمْ، فَقَابَلُوهُ بِالتَّكْذِيبِ وَالرَّدِّ وَالْمُحَارَبَةِ؛ وَلِهَذَا قَالَ: ﴿إِنَّا بَلَوْنَاهُمْ﴾ أَيِ: اخْتَبَرْنَاهُمْ، ﴿كَمَا بَلَوْنَا أَصْحَابَ الْجَنَّةِ﴾ وَهِيَ الْبُسْتَانُ الْمُشْتَمِلُ على أنواع الثمار وَالْفَوَاكِهِ ﴿إِذْ أَقْسَمُوا لَيَصْرِمُنَّهَا مُصْبِحِينَ﴾ أَيْ: حَلَفُوا فِيمَا بَيْنَهُمْ لَيجُذَّنَ ثَمرها لَيْلًا لِئَلَّا يَعْلَمَ بِهِمْ فَقِيرٌ وَلَا سَائِلٌ، لِيَتَوَفَّرَ ثَمَرُهَا عَلَيْهِمْ وَلَا يَتَصَدَّقُوا مِنْهُ بِشَيْءٍ، ﴿وَلا يَسْتَثْنُونَ﴾ أَيْ: فِيمَا حَلَفُوا بِهِ.","en":"Ibn Kathir: this is a parable Allah gave to the disbelievers of Quraysh concerning the mercy He sent them in sending Muhammad ﷺ, whom they met with denial and war."},"sb":"منع حق الفقراء والبخل وعدم الاستثناء بمشيئة الله","uq":"طائف من ربك فأصبحت كالصريم","sn":"من منع حق الله عاقبه الله بسلب ما طغى به، ولا ينفع الندم بعد فوات الأوان"}],"sn":[{"t":"الترف والفسق سبب الإهلاك","r":[17,16,16],"q":{"bk":"saadi","w":"السعدي","s":17,"ay":16,"x":"{16} يخبر تعالى أنه إذا أراد أن يُهْلِكَ قريةً من القرى الظالمة ويستأصلها بالعذاب؛ أمر مُتْرَفيها أمراً قدريًّا، ففسقوا فيها، واشتدَّ طغيانُهم؛ {فحقَّ عليها القولُ}؛ أي: كلمة العذاب التي لا مردَّ لها؛ {فدمَّرۡناها تدميراً} {17} وهؤلاء أمم كثيرةٌ أبادهم الله بالعذاب من بعد قوم نوح؛ كعاد وثمود وقوم لوط وغيرهم ممَّن عاقبهم الله لما كَثُر بغيُهم واشتدَّ كفرُهم؛ أنزل الله بهم عقابَه العظيم.","en":"Al-Sa'di: when Allah wills to destroy a wrongdoing town He commands its affluent by a decree, so they act wickedly and their tyranny grows and the punishment is deserved."}},{"t":"لا يهلك الله القرى ظلماً وأهلها مصلحون","r":[11,117,117],"q":{"bk":"saadi","w":"السعدي","s":11,"ay":117,"x":"{117} أي: وما كان الله ليهلك القرى بظُلم منه لهم والحالُ أنَّهم {مصلحون}؛ أي: مقيمون على الصلاح مستمرون عليه؛ فما كان الله ليهلكهم إلا إذا ظلموا، وقامت عليهم حجَّة الله. ويُحتمل أنَّ المعنى: وما كان ربُّك لِيُهْلِكَ القرى بظلمهم السابق إذا رجعوا وأصلحوا عملهم؛ فإنَّ الله يعفو عنهم، ويمحو ما تقدَّم من ظلمهم.","en":"Al-Sa'di: Allah would not destroy towns unjustly while they were persisting in reform; He destroys them only when they do wrong, and if they return and reform He pardons them."}},{"t":"الأمن من مكر الله خسران، والنعمة قد تكون استدراجاً","r":[7,96,99],"q":{"bk":"saadi","w":"السعدي","s":7,"ay":96,"x":"{99}{أفأمنوا مَكۡرَ الله}: حيث يستدرِجُهم من حيث لا يعلمونَ، ويُملي لهم إنَّ كيده متين. {فلا يأمنُ مكرَ اللهِ إلا القومُ الخاسرون}: فإنَّ من أمِنَ من عذاب الله؛ فإنه لم يصدِّق بالجزاء على الأعمال ولا آمن بالرسل حقيقة الإيمان.","en":"Al-Sa'di: do they feel secure from Allah's plan, how He draws them step by step; none feels secure from Allah's plan except the losing people."}},{"t":"لا يغيّر الله نعمته حتى يغيّروا ما بأنفسهم","r":[13,11,11],"q":{"bk":"saadi","w":"السعدي","s":13,"ay":11,"x":"{إنَّ الله لا يغيِّر ما بقوم}: من النعمة والإحسان ورَغَدِ العيش، {حتَّى يغيِّروا ما بأنفسِهم}: بأن ينتقلوا من الإيمان إلى الكفر، ومن الطاعة إلى المعصية، أو من شكر نعم الله إلى البطر بها، فيسلُبُهم الله عند ذلك إياها، وكذلك إذا غير العباد ما بأنفسهم من المعصية، فانتقلوا إلى طاعة الله؛ غيَّر الله عليهم ما كانوا فيه من الشقاء إلى الخير والسرور والغبطة والرحمة.","en":"Al-Sa'di: Allah does not change from a people their blessing and well-being until they change what is in themselves by moving from faith to disbelief and obedience to disobedience."}},{"t":"سنة الأخذ بالذنب بقدره","r":[29,40,40],"q":{"bk":"saadi","w":"السعدي","s":29,"ay":40,"x":"{40}{فكلاًّ}: من هؤلاء الأمم المكذِّبة {أخذنا بِذَنبِهِ}: على قدره وبعقوبةٍ مناسبة له، {فمنهم مَنۡ أرۡسَلۡنا عليه حاصباً}؛ أي: عذاباً يَحْصِبُهم كقوم عادٍ حين أرسل الله {عليهم الريح العقيم} و {سخَّرها عليهم سبعَ ليال وثمانيةَ أيام حسوماً فترى القوم فيها صَرۡعى كأنَّهم أعجازُ نخل خاوية}، {ومنهم من أخَذَتۡه الصيحةُ}: كقوم صالح، {ومنهم مَنۡ خَسَفۡنا به الأرض}: كقارون، {ومنهم من أغۡرَقۡنا}: كفرعون وهامان وجنودهما.","en":"Al-Sa'di: each of these denying nations We seized for its sin, in measure and with a fitting punishment: some We sent a violent storm upon."}},{"t":"كم أهلكنا من قبلهم من قرن","r":[6,6,6],"q":{"bk":"saadi","w":"السعدي","s":6,"ay":6,"x":"{6} ثم أمرهم أن يعتبروا بالأمم السابقة، فقال:{ألَم يَرَوۡا كم أهلكنا من قبلهم من قرنٍ}؛ أي: كم تتابع إهلاكنا للأمم المكذِّبين وأمهلناهم قبل ذلك الإهلاك بأن {مَكَّنَّاهم في الأرض ما لم نمكِّنۡ}: لهؤلاء من الأموال والبنين والرفاهية، {وأرۡسَلۡنا السماءَ عليهم مِدراراً وجعلنا الأنهار تجري من تحتهم}: تُنْبِتُ لهم بذلك ما شاء الله من زروع وثمار يتمتَّعون بها ويتناولون منها ما يشتهون، فلم يشكروا الله على نِعَمِهِ، بل أقبلوا على الشهوات، وألهتهم [أنواع] اللَّذَّات، فجاءتهم رسلهم بالبينات، فلم يصدِّقوها، بل ردُّوها وكذَّبوها، فأهلكهم الله بذُنوبهم، وأنشأ من بعدهم قَرْناً آخرين؛ فهذه سُنَّةُ الله ودأبه في الأمم السابقين واللاحقين؛ فاعتبروا بمن قَصَّ الله عليكم نبأهم.","en":"Al-Sa'di: He commands them to take lessons from past nations: how many denying nations We destroyed in succession after giving them respite."}},{"t":"أهلك الأمم بظلمهم وكفرهم بعد البينات","r":[10,13,14],"q":{"bk":"saadi","w":"السعدي","s":10,"ay":13,"x":"{13} يخبر تعالى أنه أهلك الأمم الماضية بظلمهم وكفرهم بعدما جاءتهم البيناتُ على أيدي الرسل تبيِّن الحقَّ، فلم ينقادوا لها، ولم يؤمنوا، فأحلَّ بهم عقابه الذي لا يُرَدُّ عن كلِّ مجرم متجرِّئ على محارم الله، وهذه سنته في جميع الأمم. {14}{ثم جعلناكم}؛ أيها: المخاطبون {خلائفَ في الأرض من بعدِهِم لننظر كيف تعملون}؛ فإن أنتم اعتبرتُم، واتَّعظتم بمن قبلكم، واتَّبعتم آيات الله، وصدَّقتم رسله؛ نجوتُم في الدنيا والآخرة، وإن فعلتُم كفعل الظالمين قبلكم؛ أحلَّ بكم ما أحلَّ بهم، ومَنْ أنذرَ فقد أعذرَ.","en":"Al-Sa'di: Allah destroyed past nations for their wrong and disbelief after proofs came through the messengers; then He made you successors that He may see how you act."}},{"t":"القوة لا تغني عن عذاب الله","r":[40,21,21],"q":{"bk":"saadi","w":"السعدي","s":40,"ay":21,"x":"{إنَّه قويٌّ شديد العقاب}: فلم تغنِ قوتهم عند قوةِ الله شيئاً، بل من أعظم الأمم قوة قومُ عاد الذين قالوا مَنْ أشدُّ منا قوَّةً؟! أرسل الله إليهم ريحاً أضعفت قواهم ودمَّرتهم كلَّ تدمير.","en":"Al-Sa'di: their power availed them nothing before Allah's power, and the strongest of nations in power was Aad, whom Allah sent a wind that weakened their strength and destroyed them."}}],"h":[{"id":"adm","p":"adam","t":"احتجاج آدم وموسى","x":"احْتَجَّ آدَمُ وَمُوسَى فَقَالَ لَهُ مُوسَى أَنْتَ آدَمُ الَّذِي أَخْرَجَتْكَ خَطِيئَتُكَ مِنَ الْجَنَّةِ. فَقَالَ لَهُ آدَمُ أَنْتَ مُوسَى الَّذِي اصْطَفَاكَ اللَّهُ بِرِسَالاَتِهِ وَبِكَلاَمِهِ، ثُمَّ تَلُومُنِي عَلَى أَمْرٍ قُدِّرَ عَلَىَّ قَبْلَ أَنْ أُخْلَقَ \". فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم \" فَحَجَّ آدَمُ مُوسَى","src":[["bukhari","3409"]],"gr":"صحيح: رواه البخاري","f":"محاجّة في القدر: اللوم على الذنب بعد التوبة وبعد أن قُدّر لا يصح احتجاجاً على الذنب قبل وقوعه؛ وقد تاب آدم فاجتباه ربه.","en":"The Prophet ﷺ said: \"Adam and Musa disputed. Musa said to him: You are Adam whom your sin drove out of Paradise. Adam said: You are Musa whom Allah chose for His messages and His speech, and you blame me for a matter that was decreed for me before I was created?\" The Prophet ﷺ said: \"So Adam overcame Musa,\" twice."},{"id":"lut","p":"yusuf","t":"رحمة الله على لوط وصبر يوسف","x":"وَيَرْحَمُ اللَّهُ لُوطًا، لَقَدْ كَانَ يَأْوِي إِلَى رُكْنٍ شَدِيدٍ وَلَوْ لَبِثْتُ فِي السِّجْنِ طُولَ مَا لَبِثَ يُوسُفُ لأَجَبْتُ الدَّاعِيَ","src":[["bukhari","3372"]],"gr":"صحيح: رواه البخاري","f":"ثناء النبي ﷺ على لوط عليه السلام وعلى يوسف في صبره الطويل في السجن وتمسكه بطلب البراءة قبل الخروج.","en":"The Prophet ﷺ said: \"May Allah have mercy on Lut; he used to take refuge in a strong support. And had I stayed in prison as long as Yusuf stayed, I would have answered the summoner.\""},{"id":"hajar","p":"ibrahim","t":"يرحم الله أم إسماعيل","x":"يَرْحَمُ اللَّهُ أُمَّ إِسْمَاعِيلَ، لَوْ تَرَكَتْ زَمْزَمَ ـ أَوْ قَالَ لَوْ لَمْ تَغْرِفْ مِنَ الْمَاءِ ـ لَكَانَتْ عَيْنًا مَعِينًا، وَأَقْبَلَ جُرْهُمُ فَقَالُوا أَتَأْذَنِينَ أَنْ نَنْزِلَ عِنْدَكِ قَالَتْ نَعَمْ وَلاَ حَقَّ لَكُمْ فِي الْمَاءِ","src":[["bukhari","2368"]],"gr":"صحيح: رواه البخاري","f":"من خبر هاجر وإسماعيل في وادي مكة حين تركهما إبراهيم عليه السلام، وهو أصل زمزم وسكنى جرهم عند البيت.","en":"The Prophet ﷺ said: \"May Allah have mercy on the mother of Isma'il; had she left Zamzam, or had she not scooped from the water, it would have been a flowing spring. Then Jurhum came and said: Will you permit us to settle with you? She said: Yes, but you have no right to the water. They said: Yes.\""},{"id":"khidr","p":"khidr","t":"موسى والخضر في صحيح البخاري","x":"مَلإٍ مِنْ بَنِي إِسْرَائِيلَ، جَاءَهُ رَجُلٌ فَقَالَ هَلْ تَعْلَمُ أَحَدًا أَعْلَمَ مِنْكَ قَالَ مُوسَى لاَ. فَأَوْحَى اللَّهُ إِلَى مُوسَى بَلَى، عَبْدُنَا خَضِرٌ، فَسَأَلَ مُوسَى السَّبِيلَ إِلَيْهِ، فَجَعَلَ اللَّهُ لَهُ الْحُوتَ آيَةً، وَقِيلَ لَهُ إِذَا فَقَدْتَ الْحُوتَ فَارْجِعْ، فَإِنَّكَ سَتَلْقَاهُ، وَكَانَ يَتَّبِعُ أَثَرَ الْحُوتِ فِي الْبَحْرِ، فَقَالَ لِمُوسَى فَتَاهُ أَرَأَيْتَ إِذْ أَوَيْنَا إِلَى الصَّخْرَةِ فَإِنِّي نَسِيتُ الْحُوتَ، وَمَا أَنْسَانِيهِ إِلاَّ الشَّيْطَانُ أَنْ أَذْكُرَهُ. قَالَ ذَلِكَ مَا كُنَّا نَبْغِي، فَارْتَدَّا عَلَى آثَارِهِمَا قَصَصًا، فَوَجَدَا خَضِرًا. فَكَانَ مِنْ شَأْنِهِمَا الَّذِي قَصَّ اللَّهُ ـ عَزَّ وَجَلَّ ـ فِي كِتَابِهِ","src":[["bukhari","74"]],"gr":"صحيح: رواه البخاري","f":"أصل الرحلة: سُئل موسى هل تعلم أحداً أعلم منك فقال لا، فأوحى الله إليه أن عبدنا خضراً أعلم، فرحل لطلب العلم.","en":"The Prophet ﷺ said that while Musa was among a gathering of the Children of Israel a man came and said: \"Do you know anyone more knowledgeable than you?\" Musa said: \"No.\" Allah revealed to him: \"Yes, Our servant Khidr.\" So Musa asked the way to him, a fish was made the sign, and he was told: when you lose the fish, go back, for you will meet him... and what followed is what Allah related in His Book."},{"id":"kamal","p":"maryam","t":"كمال مريم وآسية","x":"كَمَلَ مِنَ الرِّجَالِ كَثِيرٌ، وَلَمْ يَكْمُلْ مِنَ النِّسَاءِ إِلاَّ آسِيَةُ امْرَأَةُ فِرْعَوْنَ، وَمَرْيَمُ بِنْتُ عِمْرَانَ","src":[["bukhari","3411"]],"gr":"صحيح: رواه البخاري","f":"شهادة نبوية بكمال مريم بنت عمران وآسية امرأة فرعون من النساء.","en":"The Prophet ﷺ said: \"Many men have reached perfection, but of women none have reached perfection except Asiya, the wife of Pharaoh, and Maryam, daughter of Imran.\""}],"ay":{"36":"وَإِذۡ قَالَ رَبُّكَ لِلۡمَلَٰٓئِكَةِ إِنِّي جَاعِلٞ فِي ٱلۡأَرۡضِ خَلِيفَةٗۖ قَالُوٓاْ أَتَجۡعَلُ فِيهَا مَن يُفۡسِدُ فِيهَا وَيَسۡفِكُ ٱلدِّمَآءَ وَنَحۡنُ نُسَبِّحُ بِحَمۡدِكَ وَنُقَدِّسُ لَكَۖ قَالَ إِنِّيٓ أَعۡلَمُ مَا لَا تَعۡلَمُونَ","37":"وَعَلَّمَ ءَادَمَ ٱلۡأَسۡمَآءَ كُلَّهَا ثُمَّ عَرَضَهُمۡ عَلَى ٱلۡمَلَٰٓئِكَةِ فَقَالَ أَنۢبِـُٔونِي بِأَسۡمَآءِ هَٰٓؤُلَآءِ إِن كُنتُمۡ صَٰدِقِينَ","38":"قَالُواْ سُبۡحَٰنَكَ لَا عِلۡمَ لَنَآ إِلَّا مَا عَلَّمۡتَنَآۖ إِنَّكَ أَنتَ ٱلۡعَلِيمُ ٱلۡحَكِيمُ","39":"قَالَ يَٰٓـَٔادَمُ أَنۢبِئۡهُم بِأَسۡمَآئِهِمۡۖ فَلَمَّآ أَنۢبَأَهُم بِأَسۡمَآئِهِمۡ قَالَ أَلَمۡ أَقُل لَّكُمۡ إِنِّيٓ أَعۡلَمُ غَيۡبَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَأَعۡلَمُ مَا تُبۡدُونَ وَمَا كُنتُمۡ تَكۡتُمُونَ","130":"۞ وَإِذِ ٱبۡتَلَىٰٓ إِبۡرَٰهِـۧمَ رَبُّهُۥ بِكَلِمَٰتٖ فَأَتَمَّهُنَّۖ قَالَ إِنِّي جَاعِلُكَ لِلنَّاسِ إِمَامٗاۖ قَالَ وَمِن ذُرِّيَّتِيۖ قَالَ لَا يَنَالُ عَهۡدِي ٱلظَّٰلِمِينَ","131":"وَإِذۡ جَعَلۡنَا ٱلۡبَيۡتَ مَثَابَةٗ لِّلنَّاسِ وَأَمۡنٗا وَٱتَّخِذُواْ مِن مَّقَامِ إِبۡرَٰهِـۧمَ مُصَلّٗىۖ وَعَهِدۡنَآ إِلَىٰٓ إِبۡرَٰهِـۧمَ وَإِسۡمَٰعِيلَ أَن طَهِّرَا بَيۡتِيَ لِلطَّآئِفِينَ وَٱلۡعَٰكِفِينَ وَٱلرُّكَّعِ ٱلسُّجُودِ","132":"وَإِذۡ قَالَ إِبۡرَٰهِـۧمُ رَبِّ ٱجۡعَلۡ هَٰذَا بَلَدًا ءَامِنٗا وَٱرۡزُقۡ أَهۡلَهُۥ مِنَ ٱلثَّمَرَٰتِ مَنۡ ءَامَنَ مِنۡهُم بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِۚ قَالَ وَمَن كَفَرَ فَأُمَتِّعُهُۥ قَلِيلٗا ثُمَّ أَضۡطَرُّهُۥٓ إِلَىٰ عَذَابِ ٱلنَّارِۖ وَبِئۡسَ ٱلۡمَصِيرُ","133":"وَإِذۡ يَرۡفَعُ إِبۡرَٰهِـۧمُ ٱلۡقَوَاعِدَ مِنَ ٱلۡبَيۡتِ وَإِسۡمَٰعِيلُ رَبَّنَا تَقَبَّلۡ مِنَّآۖ إِنَّكَ أَنتَ ٱلسَّمِيعُ ٱلۡعَلِيمُ","264":"أَلَمۡ تَرَ إِلَى ٱلَّذِي حَآجَّ إِبۡرَٰهِـۧمَ فِي رَبِّهِۦٓ أَنۡ ءَاتَىٰهُ ٱللَّهُ ٱلۡمُلۡكَ إِذۡ قَالَ إِبۡرَٰهِـۧمُ رَبِّيَ ٱلَّذِي يُحۡيِۦ وَيُمِيتُ قَالَ أَنَا۠ أُحۡيِۦ وَأُمِيتُۖ قَالَ إِبۡرَٰهِـۧمُ فَإِنَّ ٱللَّهَ يَأۡتِي بِٱلشَّمۡسِ مِنَ ٱلۡمَشۡرِقِ فَأۡتِ بِهَا مِنَ ٱلۡمَغۡرِبِ فَبُهِتَ ٱلَّذِي كَفَرَۗ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلظَّٰلِمِينَ","327":"إِذۡ قَالَتِ ٱمۡرَأَتُ عِمۡرَٰنَ رَبِّ إِنِّي نَذَرۡتُ لَكَ مَا فِي بَطۡنِي مُحَرَّرٗا فَتَقَبَّلۡ مِنِّيٓۖ إِنَّكَ أَنتَ ٱلسَّمِيعُ ٱلۡعَلِيمُ","328":"فَلَمَّا وَضَعَتۡهَا قَالَتۡ رَبِّ إِنِّي وَضَعۡتُهَآ أُنثَىٰ وَٱللَّهُ أَعۡلَمُ بِمَا وَضَعَتۡ وَلَيۡسَ ٱلذَّكَرُ كَٱلۡأُنثَىٰۖ وَإِنِّي سَمَّيۡتُهَا مَرۡيَمَ وَإِنِّيٓ أُعِيذُهَا بِكَ وَذُرِّيَّتَهَا مِنَ ٱلشَّيۡطَٰنِ ٱلرَّجِيمِ","329":"فَتَقَبَّلَهَا رَبُّهَا بِقَبُولٍ حَسَنٖ وَأَنۢبَتَهَا نَبَاتًا حَسَنٗا وَكَفَّلَهَا زَكَرِيَّاۖ كُلَّمَا دَخَلَ عَلَيۡهَا زَكَرِيَّا ٱلۡمِحۡرَابَ وَجَدَ عِندَهَا رِزۡقٗاۖ قَالَ يَٰمَرۡيَمُ أَنَّىٰ لَكِ هَٰذَاۖ قَالَتۡ هُوَ مِنۡ عِندِ ٱللَّهِۖ إِنَّ ٱللَّهَ يَرۡزُقُ مَن يَشَآءُ بِغَيۡرِ حِسَابٍ","347":"إِذۡ قَالَ ٱللَّهُ يَٰعِيسَىٰٓ إِنِّي مُتَوَفِّيكَ وَرَافِعُكَ إِلَيَّ وَمُطَهِّرُكَ مِنَ ٱلَّذِينَ كَفَرُواْ وَجَاعِلُ ٱلَّذِينَ ٱتَّبَعُوكَ فَوۡقَ ٱلَّذِينَ كَفَرُوٓاْ إِلَىٰ يَوۡمِ ٱلۡقِيَٰمَةِۖ ثُمَّ إِلَيَّ مَرۡجِعُكُمۡ فَأَحۡكُمُ بَيۡنَكُمۡ فِيمَا كُنتُمۡ فِيهِ تَخۡتَلِفُونَ","794":"أَلَمۡ يَرَوۡاْ كَمۡ أَهۡلَكۡنَا مِن قَبۡلِهِم مِّن قَرۡنٖ مَّكَّنَّٰهُمۡ فِي ٱلۡأَرۡضِ مَا لَمۡ نُمَكِّن لَّكُمۡ وَأَرۡسَلۡنَا ٱلسَّمَآءَ عَلَيۡهِم مِّدۡرَارٗا وَجَعَلۡنَا ٱلۡأَنۡهَٰرَ تَجۡرِي مِن تَحۡتِهِمۡ فَأَهۡلَكۡنَٰهُم بِذُنُوبِهِمۡ وَأَنشَأۡنَا مِنۢ بَعۡدِهِمۡ قَرۡنًا ءَاخَرِينَ","862":"۞ وَإِذۡ قَالَ إِبۡرَٰهِيمُ لِأَبِيهِ ءَازَرَ أَتَتَّخِذُ أَصۡنَامًا ءَالِهَةً إِنِّيٓ أَرَىٰكَ وَقَوۡمَكَ فِي ضَلَٰلٖ مُّبِينٖ","863":"وَكَذَٰلِكَ نُرِيٓ إِبۡرَٰهِيمَ مَلَكُوتَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَلِيَكُونَ مِنَ ٱلۡمُوقِنِينَ","864":"فَلَمَّا جَنَّ عَلَيۡهِ ٱلَّيۡلُ رَءَا كَوۡكَبٗاۖ قَالَ هَٰذَا رَبِّيۖ فَلَمَّآ أَفَلَ قَالَ لَآ أُحِبُّ ٱلۡأٓفِلِينَ","865":"فَلَمَّا رَءَا ٱلۡقَمَرَ بَازِغٗا قَالَ هَٰذَا رَبِّيۖ فَلَمَّآ أَفَلَ قَالَ لَئِن لَّمۡ يَهۡدِنِي رَبِّي لَأَكُونَنَّ مِنَ ٱلۡقَوۡمِ ٱلضَّآلِّينَ","866":"فَلَمَّا رَءَا ٱلشَّمۡسَ بَازِغَةٗ قَالَ هَٰذَا رَبِّي هَٰذَآ أَكۡبَرُۖ فَلَمَّآ أَفَلَتۡ قَالَ يَٰقَوۡمِ إِنِّي بَرِيٓءٞ مِّمَّا تُشۡرِكُونَ","867":"إِنِّي وَجَّهۡتُ وَجۡهِيَ لِلَّذِي فَطَرَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ حَنِيفٗاۖ وَمَآ أَنَا۠ مِنَ ٱلۡمُشۡرِكِينَ","964":"وَلَقَدۡ خَلَقۡنَٰكُمۡ ثُمَّ صَوَّرۡنَٰكُمۡ ثُمَّ قُلۡنَا لِلۡمَلَٰٓئِكَةِ ٱسۡجُدُواْ لِأٓدَمَ فَسَجَدُوٓاْ إِلَّآ إِبۡلِيسَ لَمۡ يَكُن مِّنَ ٱلسَّٰجِدِينَ","965":"قَالَ مَا مَنَعَكَ أَلَّا تَسۡجُدَ إِذۡ أَمَرۡتُكَۖ قَالَ أَنَا۠ خَيۡرٞ مِّنۡهُ خَلَقۡتَنِي مِن نَّارٖ وَخَلَقۡتَهُۥ مِن طِينٖ","966":"قَالَ فَٱهۡبِطۡ مِنۡهَا فَمَا يَكُونُ لَكَ أَن تَتَكَبَّرَ فِيهَا فَٱخۡرُجۡ إِنَّكَ مِنَ ٱلصَّٰغِرِينَ","967":"قَالَ أَنظِرۡنِيٓ إِلَىٰ يَوۡمِ يُبۡعَثُونَ","968":"قَالَ إِنَّكَ مِنَ ٱلۡمُنظَرِينَ","972":"وَيَٰٓـَٔادَمُ ٱسۡكُنۡ أَنتَ وَزَوۡجُكَ ٱلۡجَنَّةَ فَكُلَا مِنۡ حَيۡثُ شِئۡتُمَا وَلَا تَقۡرَبَا هَٰذِهِ ٱلشَّجَرَةَ فَتَكُونَا مِنَ ٱلظَّٰلِمِينَ","973":"فَوَسۡوَسَ لَهُمَا ٱلشَّيۡطَٰنُ لِيُبۡدِيَ لَهُمَا مَا وُۥرِيَ عَنۡهُمَا مِن سَوۡءَٰتِهِمَا وَقَالَ مَا نَهَىٰكُمَا رَبُّكُمَا عَنۡ هَٰذِهِ ٱلشَّجَرَةِ إِلَّآ أَن تَكُونَا مَلَكَيۡنِ أَوۡ تَكُونَا مِنَ ٱلۡخَٰلِدِينَ","974":"وَقَاسَمَهُمَآ إِنِّي لَكُمَا لَمِنَ ٱلنَّٰصِحِينَ","975":"فَدَلَّىٰهُمَا بِغُرُورٖۚ فَلَمَّا ذَاقَا ٱلشَّجَرَةَ بَدَتۡ لَهُمَا سَوۡءَٰتُهُمَا وَطَفِقَا يَخۡصِفَانِ عَلَيۡهِمَا مِن وَرَقِ ٱلۡجَنَّةِۖ وَنَادَىٰهُمَا رَبُّهُمَآ أَلَمۡ أَنۡهَكُمَا عَن تِلۡكُمَا ٱلشَّجَرَةِ وَأَقُل لَّكُمَآ إِنَّ ٱلشَّيۡطَٰنَ لَكُمَا عَدُوّٞ مُّبِينٞ","976":"قَالَا رَبَّنَا ظَلَمۡنَآ أَنفُسَنَا وَإِن لَّمۡ تَغۡفِرۡ لَنَا وَتَرۡحَمۡنَا لَنَكُونَنَّ مِنَ ٱلۡخَٰسِرِينَ","1018":"۞ وَإِلَىٰ عَادٍ أَخَاهُمۡ هُودٗاۚ قَالَ يَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥٓۚ أَفَلَا تَتَّقُونَ","1019":"قَالَ ٱلۡمَلَأُ ٱلَّذِينَ كَفَرُواْ مِن قَوۡمِهِۦٓ إِنَّا لَنَرَىٰكَ فِي سَفَاهَةٖ وَإِنَّا لَنَظُنُّكَ مِنَ ٱلۡكَٰذِبِينَ","1020":"قَالَ يَٰقَوۡمِ لَيۡسَ بِي سَفَاهَةٞ وَلَٰكِنِّي رَسُولٞ مِّن رَّبِّ ٱلۡعَٰلَمِينَ","1021":"أُبَلِّغُكُمۡ رِسَٰلَٰتِ رَبِّي وَأَنَا۠ لَكُمۡ نَاصِحٌ أَمِينٌ","1022":"أَوَعَجِبۡتُمۡ أَن جَآءَكُمۡ ذِكۡرٞ مِّن رَّبِّكُمۡ عَلَىٰ رَجُلٖ مِّنكُمۡ لِيُنذِرَكُمۡۚ وَٱذۡكُرُوٓاْ إِذۡ جَعَلَكُمۡ خُلَفَآءَ مِنۢ بَعۡدِ قَوۡمِ نُوحٖ وَزَادَكُمۡ فِي ٱلۡخَلۡقِ بَصۜۡطَةٗۖ فَٱذۡكُرُوٓاْ ءَالَآءَ ٱللَّهِ لَعَلَّكُمۡ تُفۡلِحُونَ","1024":"قَالَ قَدۡ وَقَعَ عَلَيۡكُم مِّن رَّبِّكُمۡ رِجۡسٞ وَغَضَبٌۖ أَتُجَٰدِلُونَنِي فِيٓ أَسۡمَآءٖ سَمَّيۡتُمُوهَآ أَنتُمۡ وَءَابَآؤُكُم مَّا نَزَّلَ ٱللَّهُ بِهَا مِن سُلۡطَٰنٖۚ فَٱنتَظِرُوٓاْ إِنِّي مَعَكُم مِّنَ ٱلۡمُنتَظِرِينَ","1026":"وَإِلَىٰ ثَمُودَ أَخَاهُمۡ صَٰلِحٗاۚ قَالَ يَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥۖ قَدۡ جَآءَتۡكُم بَيِّنَةٞ مِّن رَّبِّكُمۡۖ هَٰذِهِۦ نَاقَةُ ٱللَّهِ لَكُمۡ ءَايَةٗۖ فَذَرُوهَا تَأۡكُلۡ فِيٓ أَرۡضِ ٱللَّهِۖ وَلَا تَمَسُّوهَا بِسُوٓءٖ فَيَأۡخُذَكُمۡ عَذَابٌ أَلِيمٞ","1027":"وَٱذۡكُرُوٓاْ إِذۡ جَعَلَكُمۡ خُلَفَآءَ مِنۢ بَعۡدِ عَادٖ وَبَوَّأَكُمۡ فِي ٱلۡأَرۡضِ تَتَّخِذُونَ مِن سُهُولِهَا قُصُورٗا وَتَنۡحِتُونَ ٱلۡجِبَالَ بُيُوتٗاۖ فَٱذۡكُرُوٓاْ ءَالَآءَ ٱللَّهِ وَلَا تَعۡثَوۡاْ فِي ٱلۡأَرۡضِ مُفۡسِدِينَ","1028":"قَالَ ٱلۡمَلَأُ ٱلَّذِينَ ٱسۡتَكۡبَرُواْ مِن قَوۡمِهِۦ لِلَّذِينَ ٱسۡتُضۡعِفُواْ لِمَنۡ ءَامَنَ مِنۡهُمۡ أَتَعۡلَمُونَ أَنَّ صَٰلِحٗا مُّرۡسَلٞ مِّن رَّبِّهِۦۚ قَالُوٓاْ إِنَّا بِمَآ أُرۡسِلَ بِهِۦ مُؤۡمِنُونَ","1029":"قَالَ ٱلَّذِينَ ٱسۡتَكۡبَرُوٓاْ إِنَّا بِٱلَّذِيٓ ءَامَنتُم بِهِۦ كَٰفِرُونَ","1030":"فَعَقَرُواْ ٱلنَّاقَةَ وَعَتَوۡاْ عَنۡ أَمۡرِ رَبِّهِمۡ وَقَالُواْ يَٰصَٰلِحُ ٱئۡتِنَا بِمَا تَعِدُنَآ إِن كُنتَ مِنَ ٱلۡمُرۡسَلِينَ","1031":"فَأَخَذَتۡهُمُ ٱلرَّجۡفَةُ فَأَصۡبَحُواْ فِي دَارِهِمۡ جَٰثِمِينَ","1033":"وَلُوطًا إِذۡ قَالَ لِقَوۡمِهِۦٓ أَتَأۡتُونَ ٱلۡفَٰحِشَةَ مَا سَبَقَكُم بِهَا مِنۡ أَحَدٖ مِّنَ ٱلۡعَٰلَمِينَ","1034":"إِنَّكُمۡ لَتَأۡتُونَ ٱلرِّجَالَ شَهۡوَةٗ مِّن دُونِ ٱلنِّسَآءِۚ بَلۡ أَنتُمۡ قَوۡمٞ مُّسۡرِفُونَ","1035":"وَمَا كَانَ جَوَابَ قَوۡمِهِۦٓ إِلَّآ أَن قَالُوٓاْ أَخۡرِجُوهُم مِّن قَرۡيَتِكُمۡۖ إِنَّهُمۡ أُنَاسٞ يَتَطَهَّرُونَ","1036":"فَأَنجَيۡنَٰهُ وَأَهۡلَهُۥٓ إِلَّا ٱمۡرَأَتَهُۥ كَانَتۡ مِنَ ٱلۡغَٰبِرِينَ","1037":"وَأَمۡطَرۡنَا عَلَيۡهِم مَّطَرٗاۖ فَٱنظُرۡ كَيۡفَ كَانَ عَٰقِبَةُ ٱلۡمُجۡرِمِينَ","1038":"وَإِلَىٰ مَدۡيَنَ أَخَاهُمۡ شُعَيۡبٗاۚ قَالَ يَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥۖ قَدۡ جَآءَتۡكُم بَيِّنَةٞ مِّن رَّبِّكُمۡۖ فَأَوۡفُواْ ٱلۡكَيۡلَ وَٱلۡمِيزَانَ وَلَا تَبۡخَسُواْ ٱلنَّاسَ أَشۡيَآءَهُمۡ وَلَا تُفۡسِدُواْ فِي ٱلۡأَرۡضِ بَعۡدَ إِصۡلَٰحِهَاۚ ذَٰلِكُمۡ خَيۡرٞ لَّكُمۡ إِن كُنتُم مُّؤۡمِنِينَ","1039":"وَلَا تَقۡعُدُواْ بِكُلِّ صِرَٰطٖ تُوعِدُونَ وَتَصُدُّونَ عَن سَبِيلِ ٱللَّهِ مَنۡ ءَامَنَ بِهِۦ وَتَبۡغُونَهَا عِوَجٗاۚ وَٱذۡكُرُوٓاْ إِذۡ كُنتُمۡ قَلِيلٗا فَكَثَّرَكُمۡۖ وَٱنظُرُواْ كَيۡفَ كَانَ عَٰقِبَةُ ٱلۡمُفۡسِدِينَ","1040":"وَإِن كَانَ طَآئِفَةٞ مِّنكُمۡ ءَامَنُواْ بِٱلَّذِيٓ أُرۡسِلۡتُ بِهِۦ وَطَآئِفَةٞ لَّمۡ يُؤۡمِنُواْ فَٱصۡبِرُواْ حَتَّىٰ يَحۡكُمَ ٱللَّهُ بَيۡنَنَاۚ وَهُوَ خَيۡرُ ٱلۡحَٰكِمِينَ","1041":"۞ قَالَ ٱلۡمَلَأُ ٱلَّذِينَ ٱسۡتَكۡبَرُواْ مِن قَوۡمِهِۦ لَنُخۡرِجَنَّكَ يَٰشُعَيۡبُ وَٱلَّذِينَ ءَامَنُواْ مَعَكَ مِن قَرۡيَتِنَآ أَوۡ لَتَعُودُنَّ فِي مِلَّتِنَاۚ قَالَ أَوَلَوۡ كُنَّا كَٰرِهِينَ","1042":"قَدِ ٱفۡتَرَيۡنَا عَلَى ٱللَّهِ كَذِبًا إِنۡ عُدۡنَا فِي مِلَّتِكُم بَعۡدَ إِذۡ نَجَّىٰنَا ٱللَّهُ مِنۡهَاۚ وَمَا يَكُونُ لَنَآ أَن نَّعُودَ فِيهَآ إِلَّآ أَن يَشَآءَ ٱللَّهُ رَبُّنَاۚ وَسِعَ رَبُّنَا كُلَّ شَيۡءٍ عِلۡمًاۚ عَلَى ٱللَّهِ تَوَكَّلۡنَاۚ رَبَّنَا ٱفۡتَحۡ بَيۡنَنَا وَبَيۡنَ قَوۡمِنَا بِٱلۡحَقِّ وَأَنتَ خَيۡرُ ٱلۡفَٰتِحِينَ","1049":"وَلَوۡ أَنَّ أَهۡلَ ٱلۡقُرَىٰٓ ءَامَنُواْ وَٱتَّقَوۡاْ لَفَتَحۡنَا عَلَيۡهِم بَرَكَٰتٖ مِّنَ ٱلسَّمَآءِ وَٱلۡأَرۡضِ وَلَٰكِن كَذَّبُواْ فَأَخَذۡنَٰهُم بِمَا كَانُواْ يَكۡسِبُونَ","1050":"أَفَأَمِنَ أَهۡلُ ٱلۡقُرَىٰٓ أَن يَأۡتِيَهُم بَأۡسُنَا بَيَٰتٗا وَهُمۡ نَآئِمُونَ","1051":"أَوَأَمِنَ أَهۡلُ ٱلۡقُرَىٰٓ أَن يَأۡتِيَهُم بَأۡسُنَا ضُحٗى وَهُمۡ يَلۡعَبُونَ","1056":"ثُمَّ بَعَثۡنَا مِنۢ بَعۡدِهِم مُّوسَىٰ بِـَٔايَٰتِنَآ إِلَىٰ فِرۡعَوۡنَ وَمَلَإِيْهِۦ فَظَلَمُواْ بِهَاۖ فَٱنظُرۡ كَيۡفَ كَانَ عَٰقِبَةُ ٱلۡمُفۡسِدِينَ","1057":"وَقَالَ مُوسَىٰ يَٰفِرۡعَوۡنُ إِنِّي رَسُولٞ مِّن رَّبِّ ٱلۡعَٰلَمِينَ","1058":"حَقِيقٌ عَلَىٰٓ أَن لَّآ أَقُولَ عَلَى ٱللَّهِ إِلَّا ٱلۡحَقَّۚ قَدۡ جِئۡتُكُم بِبَيِّنَةٖ مِّن رَّبِّكُمۡ فَأَرۡسِلۡ مَعِيَ بَنِيٓ إِسۡرَٰٓءِيلَ","1059":"قَالَ إِن كُنتَ جِئۡتَ بِـَٔايَةٖ فَأۡتِ بِهَآ إِن كُنتَ مِنَ ٱلصَّٰدِقِينَ","1060":"فَأَلۡقَىٰ عَصَاهُ فَإِذَا هِيَ ثُعۡبَانٞ مُّبِينٞ","1376":"وَلَقَدۡ أَهۡلَكۡنَا ٱلۡقُرُونَ مِن قَبۡلِكُمۡ لَمَّا ظَلَمُواْ وَجَآءَتۡهُمۡ رُسُلُهُم بِٱلۡبَيِّنَٰتِ وَمَا كَانُواْ لِيُؤۡمِنُواْۚ كَذَٰلِكَ نَجۡزِي ٱلۡقَوۡمَ ٱلۡمُجۡرِمِينَ","1377":"ثُمَّ جَعَلۡنَٰكُمۡ خَلَٰٓئِفَ فِي ٱلۡأَرۡضِ مِنۢ بَعۡدِهِمۡ لِنَنظُرَ كَيۡفَ تَعۡمَلُونَ","1453":"۞ وَجَٰوَزۡنَا بِبَنِيٓ إِسۡرَٰٓءِيلَ ٱلۡبَحۡرَ فَأَتۡبَعَهُمۡ فِرۡعَوۡنُ وَجُنُودُهُۥ بَغۡيٗا وَعَدۡوًاۖ حَتَّىٰٓ إِذَآ أَدۡرَكَهُ ٱلۡغَرَقُ قَالَ ءَامَنتُ أَنَّهُۥ لَآ إِلَٰهَ إِلَّا ٱلَّذِيٓ ءَامَنَتۡ بِهِۦ بَنُوٓاْ إِسۡرَٰٓءِيلَ وَأَنَا۠ مِنَ ٱلۡمُسۡلِمِينَ","1454":"ءَآلۡـَٰٔنَ وَقَدۡ عَصَيۡتَ قَبۡلُ وَكُنتَ مِنَ ٱلۡمُفۡسِدِينَ","1455":"فَٱلۡيَوۡمَ نُنَجِّيكَ بِبَدَنِكَ لِتَكُونَ لِمَنۡ خَلۡفَكَ ءَايَةٗۚ وَإِنَّ كَثِيرٗا مِّنَ ٱلنَّاسِ عَنۡ ءَايَٰتِنَا لَغَٰفِلُونَ","1497":"وَلَقَدۡ أَرۡسَلۡنَا نُوحًا إِلَىٰ قَوۡمِهِۦٓ إِنِّي لَكُمۡ نَذِيرٞ مُّبِينٌ","1498":"أَن لَّا تَعۡبُدُوٓاْ إِلَّا ٱللَّهَۖ إِنِّيٓ أَخَافُ عَلَيۡكُمۡ عَذَابَ يَوۡمٍ أَلِيمٖ","1499":"فَقَالَ ٱلۡمَلَأُ ٱلَّذِينَ كَفَرُواْ مِن قَوۡمِهِۦ مَا نَرَىٰكَ إِلَّا بَشَرٗا مِّثۡلَنَا وَمَا نَرَىٰكَ ٱتَّبَعَكَ إِلَّا ٱلَّذِينَ هُمۡ أَرَاذِلُنَا بَادِيَ ٱلرَّأۡيِ وَمَا نَرَىٰ لَكُمۡ عَلَيۡنَا مِن فَضۡلِۭ بَلۡ نَظُنُّكُمۡ كَٰذِبِينَ","1500":"قَالَ يَٰقَوۡمِ أَرَءَيۡتُمۡ إِن كُنتُ عَلَىٰ بَيِّنَةٖ مِّن رَّبِّي وَءَاتَىٰنِي رَحۡمَةٗ مِّنۡ عِندِهِۦ فَعُمِّيَتۡ عَلَيۡكُمۡ أَنُلۡزِمُكُمُوهَا وَأَنتُمۡ لَهَا كَٰرِهُونَ","1501":"وَيَٰقَوۡمِ لَآ أَسۡـَٔلُكُمۡ عَلَيۡهِ مَالًاۖ إِنۡ أَجۡرِيَ إِلَّا عَلَى ٱللَّهِۚ وَمَآ أَنَا۠ بِطَارِدِ ٱلَّذِينَ ءَامَنُوٓاْۚ إِنَّهُم مُّلَٰقُواْ رَبِّهِمۡ وَلَٰكِنِّيٓ أَرَىٰكُمۡ قَوۡمٗا تَجۡهَلُونَ","1508":"وَأُوحِيَ إِلَىٰ نُوحٍ أَنَّهُۥ لَن يُؤۡمِنَ مِن قَوۡمِكَ إِلَّا مَن قَدۡ ءَامَنَ فَلَا تَبۡتَئِسۡ بِمَا كَانُواْ يَفۡعَلُونَ","1509":"وَٱصۡنَعِ ٱلۡفُلۡكَ بِأَعۡيُنِنَا وَوَحۡيِنَا وَلَا تُخَٰطِبۡنِي فِي ٱلَّذِينَ ظَلَمُوٓاْ إِنَّهُم مُّغۡرَقُونَ","1510":"وَيَصۡنَعُ ٱلۡفُلۡكَ وَكُلَّمَا مَرَّ عَلَيۡهِ مَلَأٞ مِّن قَوۡمِهِۦ سَخِرُواْ مِنۡهُۚ قَالَ إِن تَسۡخَرُواْ مِنَّا فَإِنَّا نَسۡخَرُ مِنكُمۡ كَمَا تَسۡخَرُونَ","1511":"فَسَوۡفَ تَعۡلَمُونَ مَن يَأۡتِيهِ عَذَابٞ يُخۡزِيهِ وَيَحِلُّ عَلَيۡهِ عَذَابٞ مُّقِيمٌ","1512":"حَتَّىٰٓ إِذَا جَآءَ أَمۡرُنَا وَفَارَ ٱلتَّنُّورُ قُلۡنَا ٱحۡمِلۡ فِيهَا مِن كُلّٖ زَوۡجَيۡنِ ٱثۡنَيۡنِ وَأَهۡلَكَ إِلَّا مَن سَبَقَ عَلَيۡهِ ٱلۡقَوۡلُ وَمَنۡ ءَامَنَۚ وَمَآ ءَامَنَ مَعَهُۥٓ إِلَّا قَلِيلٞ","1513":"۞ وَقَالَ ٱرۡكَبُواْ فِيهَا بِسۡمِ ٱللَّهِ مَجۡر۪ىٰهَا وَمُرۡسَىٰهَآۚ إِنَّ رَبِّي لَغَفُورٞ رَّحِيمٞ","1514":"وَهِيَ تَجۡرِي بِهِمۡ فِي مَوۡجٖ كَٱلۡجِبَالِ وَنَادَىٰ نُوحٌ ٱبۡنَهُۥ وَكَانَ فِي مَعۡزِلٖ يَٰبُنَيَّ ٱرۡكَب مَّعَنَا وَلَا تَكُن مَّعَ ٱلۡكَٰفِرِينَ","1515":"قَالَ سَـَٔاوِيٓ إِلَىٰ جَبَلٖ يَعۡصِمُنِي مِنَ ٱلۡمَآءِۚ قَالَ لَا عَاصِمَ ٱلۡيَوۡمَ مِنۡ أَمۡرِ ٱللَّهِ إِلَّا مَن رَّحِمَۚ وَحَالَ بَيۡنَهُمَا ٱلۡمَوۡجُ فَكَانَ مِنَ ٱلۡمُغۡرَقِينَ","1516":"وَقِيلَ يَٰٓأَرۡضُ ٱبۡلَعِي مَآءَكِ وَيَٰسَمَآءُ أَقۡلِعِي وَغِيضَ ٱلۡمَآءُ وَقُضِيَ ٱلۡأَمۡرُ وَٱسۡتَوَتۡ عَلَى ٱلۡجُودِيِّۖ وَقِيلَ بُعۡدٗا لِّلۡقَوۡمِ ٱلظَّٰلِمِينَ","1517":"وَنَادَىٰ نُوحٞ رَّبَّهُۥ فَقَالَ رَبِّ إِنَّ ٱبۡنِي مِنۡ أَهۡلِي وَإِنَّ وَعۡدَكَ ٱلۡحَقُّ وَأَنتَ أَحۡكَمُ ٱلۡحَٰكِمِينَ","1518":"قَالَ يَٰنُوحُ إِنَّهُۥ لَيۡسَ مِنۡ أَهۡلِكَۖ إِنَّهُۥ عَمَلٌ غَيۡرُ صَٰلِحٖۖ فَلَا تَسۡـَٔلۡنِ مَا لَيۡسَ لَكَ بِهِۦ عِلۡمٌۖ إِنِّيٓ أَعِظُكَ أَن تَكُونَ مِنَ ٱلۡجَٰهِلِينَ","1521":"تِلۡكَ مِنۡ أَنۢبَآءِ ٱلۡغَيۡبِ نُوحِيهَآ إِلَيۡكَۖ مَا كُنتَ تَعۡلَمُهَآ أَنتَ وَلَا قَوۡمُكَ مِن قَبۡلِ هَٰذَاۖ فَٱصۡبِرۡۖ إِنَّ ٱلۡعَٰقِبَةَ لِلۡمُتَّقِينَ","1533":"۞ وَإِلَىٰ ثَمُودَ أَخَاهُمۡ صَٰلِحٗاۚ قَالَ يَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥۖ هُوَ أَنشَأَكُم مِّنَ ٱلۡأَرۡضِ وَٱسۡتَعۡمَرَكُمۡ فِيهَا فَٱسۡتَغۡفِرُوهُ ثُمَّ تُوبُوٓاْ إِلَيۡهِۚ إِنَّ رَبِّي قَرِيبٞ مُّجِيبٞ","1534":"قَالُواْ يَٰصَٰلِحُ قَدۡ كُنتَ فِينَا مَرۡجُوّٗا قَبۡلَ هَٰذَآۖ أَتَنۡهَىٰنَآ أَن نَّعۡبُدَ مَا يَعۡبُدُ ءَابَآؤُنَا وَإِنَّنَا لَفِي شَكّٖ مِّمَّا تَدۡعُونَآ إِلَيۡهِ مُرِيبٖ","1535":"قَالَ يَٰقَوۡمِ أَرَءَيۡتُمۡ إِن كُنتُ عَلَىٰ بَيِّنَةٖ مِّن رَّبِّي وَءَاتَىٰنِي مِنۡهُ رَحۡمَةٗ فَمَن يَنصُرُنِي مِنَ ٱللَّهِ إِنۡ عَصَيۡتُهُۥۖ فَمَا تَزِيدُونَنِي غَيۡرَ تَخۡسِيرٖ","1536":"وَيَٰقَوۡمِ هَٰذِهِۦ نَاقَةُ ٱللَّهِ لَكُمۡ ءَايَةٗۖ فَذَرُوهَا تَأۡكُلۡ فِيٓ أَرۡضِ ٱللَّهِۖ وَلَا تَمَسُّوهَا بِسُوٓءٖ فَيَأۡخُذَكُمۡ عَذَابٞ قَرِيبٞ","1537":"فَعَقَرُوهَا فَقَالَ تَمَتَّعُواْ فِي دَارِكُمۡ ثَلَٰثَةَ أَيَّامٖۖ ذَٰلِكَ وَعۡدٌ غَيۡرُ مَكۡذُوبٖ","1538":"فَلَمَّا جَآءَ أَمۡرُنَا نَجَّيۡنَا صَٰلِحٗا وَٱلَّذِينَ ءَامَنُواْ مَعَهُۥ بِرَحۡمَةٖ مِّنَّا وَمِنۡ خِزۡيِ يَوۡمِئِذٍۚ إِنَّ رَبَّكَ هُوَ ٱلۡقَوِيُّ ٱلۡعَزِيزُ","1541":"وَلَقَدۡ جَآءَتۡ رُسُلُنَآ إِبۡرَٰهِيمَ بِٱلۡبُشۡرَىٰ قَالُواْ سَلَٰمٗاۖ قَالَ سَلَٰمٞۖ فَمَا لَبِثَ أَن جَآءَ بِعِجۡلٍ حَنِيذٖ","1542":"فَلَمَّا رَءَآ أَيۡدِيَهُمۡ لَا تَصِلُ إِلَيۡهِ نَكِرَهُمۡ وَأَوۡجَسَ مِنۡهُمۡ خِيفَةٗۚ قَالُواْ لَا تَخَفۡ إِنَّآ أُرۡسِلۡنَآ إِلَىٰ قَوۡمِ لُوطٖ","1543":"وَٱمۡرَأَتُهُۥ قَآئِمَةٞ فَضَحِكَتۡ فَبَشَّرۡنَٰهَا بِإِسۡحَٰقَ وَمِن وَرَآءِ إِسۡحَٰقَ يَعۡقُوبَ","1544":"قَالَتۡ يَٰوَيۡلَتَىٰٓ ءَأَلِدُ وَأَنَا۠ عَجُوزٞ وَهَٰذَا بَعۡلِي شَيۡخًاۖ إِنَّ هَٰذَا لَشَيۡءٌ عَجِيبٞ","1545":"قَالُوٓاْ أَتَعۡجَبِينَ مِنۡ أَمۡرِ ٱللَّهِۖ رَحۡمَتُ ٱللَّهِ وَبَرَكَٰتُهُۥ عَلَيۡكُمۡ أَهۡلَ ٱلۡبَيۡتِۚ إِنَّهُۥ حَمِيدٞ مَّجِيدٞ","1550":"وَجَآءَهُۥ قَوۡمُهُۥ يُهۡرَعُونَ إِلَيۡهِ وَمِن قَبۡلُ كَانُواْ يَعۡمَلُونَ ٱلسَّيِّـَٔاتِۚ قَالَ يَٰقَوۡمِ هَٰٓؤُلَآءِ بَنَاتِي هُنَّ أَطۡهَرُ لَكُمۡۖ فَٱتَّقُواْ ٱللَّهَ وَلَا تُخۡزُونِ فِي ضَيۡفِيٓۖ أَلَيۡسَ مِنكُمۡ رَجُلٞ رَّشِيدٞ","1551":"قَالُواْ لَقَدۡ عَلِمۡتَ مَا لَنَا فِي بَنَاتِكَ مِنۡ حَقّٖ وَإِنَّكَ لَتَعۡلَمُ مَا نُرِيدُ","1556":"۞ وَإِلَىٰ مَدۡيَنَ أَخَاهُمۡ شُعَيۡبٗاۚ قَالَ يَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥۖ وَلَا تَنقُصُواْ ٱلۡمِكۡيَالَ وَٱلۡمِيزَانَۖ إِنِّيٓ أَرَىٰكُم بِخَيۡرٖ وَإِنِّيٓ أَخَافُ عَلَيۡكُمۡ عَذَابَ يَوۡمٖ مُّحِيطٖ","1557":"وَيَٰقَوۡمِ أَوۡفُواْ ٱلۡمِكۡيَالَ وَٱلۡمِيزَانَ بِٱلۡقِسۡطِۖ وَلَا تَبۡخَسُواْ ٱلنَّاسَ أَشۡيَآءَهُمۡ وَلَا تَعۡثَوۡاْ فِي ٱلۡأَرۡضِ مُفۡسِدِينَ","1558":"بَقِيَّتُ ٱللَّهِ خَيۡرٞ لَّكُمۡ إِن كُنتُم مُّؤۡمِنِينَۚ وَمَآ أَنَا۠ عَلَيۡكُم بِحَفِيظٖ","1559":"قَالُواْ يَٰشُعَيۡبُ أَصَلَوٰتُكَ تَأۡمُرُكَ أَن نَّتۡرُكَ مَا يَعۡبُدُ ءَابَآؤُنَآ أَوۡ أَن نَّفۡعَلَ فِيٓ أَمۡوَٰلِنَا مَا نَشَٰٓؤُاْۖ إِنَّكَ لَأَنتَ ٱلۡحَلِيمُ ٱلرَّشِيدُ","1560":"قَالَ يَٰقَوۡمِ أَرَءَيۡتُمۡ إِن كُنتُ عَلَىٰ بَيِّنَةٖ مِّن رَّبِّي وَرَزَقَنِي مِنۡهُ رِزۡقًا حَسَنٗاۚ وَمَآ أُرِيدُ أَنۡ أُخَالِفَكُمۡ إِلَىٰ مَآ أَنۡهَىٰكُمۡ عَنۡهُۚ إِنۡ أُرِيدُ إِلَّا ٱلۡإِصۡلَٰحَ مَا ٱسۡتَطَعۡتُۚ وَمَا تَوۡفِيقِيٓ إِلَّا بِٱللَّهِۚ عَلَيۡهِ تَوَكَّلۡتُ وَإِلَيۡهِ أُنِيبُ","1562":"وَٱسۡتَغۡفِرُواْ رَبَّكُمۡ ثُمَّ تُوبُوٓاْ إِلَيۡهِۚ إِنَّ رَبِّي رَحِيمٞ وَدُودٞ","1566":"وَلَمَّا جَآءَ أَمۡرُنَا نَجَّيۡنَا شُعَيۡبٗا وَٱلَّذِينَ ءَامَنُواْ مَعَهُۥ بِرَحۡمَةٖ مِّنَّا وَأَخَذَتِ ٱلَّذِينَ ظَلَمُواْ ٱلصَّيۡحَةُ فَأَصۡبَحُواْ فِي دِيَٰرِهِمۡ جَٰثِمِينَ","1589":"وَمَا كَانَ رَبُّكَ لِيُهۡلِكَ ٱلۡقُرَىٰ بِظُلۡمٖ وَأَهۡلُهَا مُصۡلِحُونَ","1599":"إِذۡ قَالَ يُوسُفُ لِأَبِيهِ يَٰٓأَبَتِ إِنِّي رَأَيۡتُ أَحَدَ عَشَرَ كَوۡكَبٗا وَٱلشَّمۡسَ وَٱلۡقَمَرَ رَأَيۡتُهُمۡ لِي سَٰجِدِينَ","1600":"قَالَ يَٰبُنَيَّ لَا تَقۡصُصۡ رُءۡيَاكَ عَلَىٰٓ إِخۡوَتِكَ فَيَكِيدُواْ لَكَ كَيۡدًاۖ إِنَّ ٱلشَّيۡطَٰنَ لِلۡإِنسَٰنِ عَدُوّٞ مُّبِينٞ","1601":"وَكَذَٰلِكَ يَجۡتَبِيكَ رَبُّكَ وَيُعَلِّمُكَ مِن تَأۡوِيلِ ٱلۡأَحَادِيثِ وَيُتِمُّ نِعۡمَتَهُۥ عَلَيۡكَ وَعَلَىٰٓ ءَالِ يَعۡقُوبَ كَمَآ أَتَمَّهَا عَلَىٰٓ أَبَوَيۡكَ مِن قَبۡلُ إِبۡرَٰهِيمَ وَإِسۡحَٰقَۚ إِنَّ رَبَّكَ عَلِيمٌ حَكِيمٞ","1602":"۞ لَّقَدۡ كَانَ فِي يُوسُفَ وَإِخۡوَتِهِۦٓ ءَايَٰتٞ لِّلسَّآئِلِينَ","1603":"إِذۡ قَالُواْ لَيُوسُفُ وَأَخُوهُ أَحَبُّ إِلَىٰٓ أَبِينَا مِنَّا وَنَحۡنُ عُصۡبَةٌ إِنَّ أَبَانَا لَفِي ضَلَٰلٖ مُّبِينٍ","1604":"ٱقۡتُلُواْ يُوسُفَ أَوِ ٱطۡرَحُوهُ أَرۡضٗا يَخۡلُ لَكُمۡ وَجۡهُ أَبِيكُمۡ وَتَكُونُواْ مِنۢ بَعۡدِهِۦ قَوۡمٗا صَٰلِحِينَ","1605":"قَالَ قَآئِلٞ مِّنۡهُمۡ لَا تَقۡتُلُواْ يُوسُفَ وَأَلۡقُوهُ فِي غَيَٰبَتِ ٱلۡجُبِّ يَلۡتَقِطۡهُ بَعۡضُ ٱلسَّيَّارَةِ إِن كُنتُمۡ فَٰعِلِينَ","1606":"قَالُواْ يَٰٓأَبَانَا مَا لَكَ لَا تَأۡمَ۬نَّا عَلَىٰ يُوسُفَ وَإِنَّا لَهُۥ لَنَٰصِحُونَ","1616":"وَقَالَ ٱلَّذِي ٱشۡتَرَىٰهُ مِن مِّصۡرَ لِٱمۡرَأَتِهِۦٓ أَكۡرِمِي مَثۡوَىٰهُ عَسَىٰٓ أَن يَنفَعَنَآ أَوۡ نَتَّخِذَهُۥ وَلَدٗاۚ وَكَذَٰلِكَ مَكَّنَّا لِيُوسُفَ فِي ٱلۡأَرۡضِ وَلِنُعَلِّمَهُۥ مِن تَأۡوِيلِ ٱلۡأَحَادِيثِۚ وَٱللَّهُ غَالِبٌ عَلَىٰٓ أَمۡرِهِۦ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَعۡلَمُونَ","1617":"وَلَمَّا بَلَغَ أَشُدَّهُۥٓ ءَاتَيۡنَٰهُ حُكۡمٗا وَعِلۡمٗاۚ وَكَذَٰلِكَ نَجۡزِي ٱلۡمُحۡسِنِينَ","1618":"وَرَٰوَدَتۡهُ ٱلَّتِي هُوَ فِي بَيۡتِهَا عَن نَّفۡسِهِۦ وَغَلَّقَتِ ٱلۡأَبۡوَٰبَ وَقَالَتۡ هَيۡتَ لَكَۚ قَالَ مَعَاذَ ٱللَّهِۖ إِنَّهُۥ رَبِّيٓ أَحۡسَنَ مَثۡوَايَۖ إِنَّهُۥ لَا يُفۡلِحُ ٱلظَّٰلِمُونَ","1619":"وَلَقَدۡ هَمَّتۡ بِهِۦۖ وَهَمَّ بِهَا لَوۡلَآ أَن رَّءَا بُرۡهَٰنَ رَبِّهِۦۚ كَذَٰلِكَ لِنَصۡرِفَ عَنۡهُ ٱلسُّوٓءَ وَٱلۡفَحۡشَآءَۚ إِنَّهُۥ مِنۡ عِبَادِنَا ٱلۡمُخۡلَصِينَ","1620":"وَٱسۡتَبَقَا ٱلۡبَابَ وَقَدَّتۡ قَمِيصَهُۥ مِن دُبُرٖ وَأَلۡفَيَا سَيِّدَهَا لَدَا ٱلۡبَابِۚ قَالَتۡ مَا جَزَآءُ مَنۡ أَرَادَ بِأَهۡلِكَ سُوٓءًا إِلَّآ أَن يُسۡجَنَ أَوۡ عَذَابٌ أَلِيمٞ","1625":"۞ وَقَالَ نِسۡوَةٞ فِي ٱلۡمَدِينَةِ ٱمۡرَأَتُ ٱلۡعَزِيزِ تُرَٰوِدُ فَتَىٰهَا عَن نَّفۡسِهِۦۖ قَدۡ شَغَفَهَا حُبًّاۖ إِنَّا لَنَرَىٰهَا فِي ضَلَٰلٖ مُّبِينٖ","1626":"فَلَمَّا سَمِعَتۡ بِمَكۡرِهِنَّ أَرۡسَلَتۡ إِلَيۡهِنَّ وَأَعۡتَدَتۡ لَهُنَّ مُتَّكَـٔٗا وَءَاتَتۡ كُلَّ وَٰحِدَةٖ مِّنۡهُنَّ سِكِّينٗا وَقَالَتِ ٱخۡرُجۡ عَلَيۡهِنَّۖ فَلَمَّا رَأَيۡنَهُۥٓ أَكۡبَرۡنَهُۥ وَقَطَّعۡنَ أَيۡدِيَهُنَّ وَقُلۡنَ حَٰشَ لِلَّهِ مَا هَٰذَا بَشَرًا إِنۡ هَٰذَآ إِلَّا مَلَكٞ كَرِيمٞ","1627":"قَالَتۡ فَذَٰلِكُنَّ ٱلَّذِي لُمۡتُنَّنِي فِيهِۖ وَلَقَدۡ رَٰوَدتُّهُۥ عَن نَّفۡسِهِۦ فَٱسۡتَعۡصَمَۖ وَلَئِن لَّمۡ يَفۡعَلۡ مَآ ءَامُرُهُۥ لَيُسۡجَنَنَّ وَلَيَكُونٗا مِّنَ ٱلصَّٰغِرِينَ","1628":"قَالَ رَبِّ ٱلسِّجۡنُ أَحَبُّ إِلَيَّ مِمَّا يَدۡعُونَنِيٓ إِلَيۡهِۖ وَإِلَّا تَصۡرِفۡ عَنِّي كَيۡدَهُنَّ أَصۡبُ إِلَيۡهِنَّ وَأَكُن مِّنَ ٱلۡجَٰهِلِينَ","1629":"فَٱسۡتَجَابَ لَهُۥ رَبُّهُۥ فَصَرَفَ عَنۡهُ كَيۡدَهُنَّۚ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ","1638":"وَقَالَ ٱلۡمَلِكُ إِنِّيٓ أَرَىٰ سَبۡعَ بَقَرَٰتٖ سِمَانٖ يَأۡكُلُهُنَّ سَبۡعٌ عِجَافٞ وَسَبۡعَ سُنۢبُلَٰتٍ خُضۡرٖ وَأُخَرَ يَابِسَٰتٖۖ يَٰٓأَيُّهَا ٱلۡمَلَأُ أَفۡتُونِي فِي رُءۡيَٰيَ إِن كُنتُمۡ لِلرُّءۡيَا تَعۡبُرُونَ","1639":"قَالُوٓاْ أَضۡغَٰثُ أَحۡلَٰمٖۖ وَمَا نَحۡنُ بِتَأۡوِيلِ ٱلۡأَحۡلَٰمِ بِعَٰلِمِينَ","1640":"وَقَالَ ٱلَّذِي نَجَا مِنۡهُمَا وَٱدَّكَرَ بَعۡدَ أُمَّةٍ أَنَا۠ أُنَبِّئُكُم بِتَأۡوِيلِهِۦ فَأَرۡسِلُونِ","1641":"يُوسُفُ أَيُّهَا ٱلصِّدِّيقُ أَفۡتِنَا فِي سَبۡعِ بَقَرَٰتٖ سِمَانٖ يَأۡكُلُهُنَّ سَبۡعٌ عِجَافٞ وَسَبۡعِ سُنۢبُلَٰتٍ خُضۡرٖ وَأُخَرَ يَابِسَٰتٖ لَّعَلِّيٓ أَرۡجِعُ إِلَى ٱلنَّاسِ لَعَلَّهُمۡ يَعۡلَمُونَ","1642":"قَالَ تَزۡرَعُونَ سَبۡعَ سِنِينَ دَأَبٗا فَمَا حَصَدتُّمۡ فَذَرُوهُ فِي سُنۢبُلِهِۦٓ إِلَّا قَلِيلٗا مِّمَّا تَأۡكُلُونَ","1645":"وَقَالَ ٱلۡمَلِكُ ٱئۡتُونِي بِهِۦۖ فَلَمَّا جَآءَهُ ٱلرَّسُولُ قَالَ ٱرۡجِعۡ إِلَىٰ رَبِّكَ فَسۡـَٔلۡهُ مَا بَالُ ٱلنِّسۡوَةِ ٱلَّٰتِي قَطَّعۡنَ أَيۡدِيَهُنَّۚ إِنَّ رَبِّي بِكَيۡدِهِنَّ عَلِيمٞ","1653":"وَجَآءَ إِخۡوَةُ يُوسُفَ فَدَخَلُواْ عَلَيۡهِ فَعَرَفَهُمۡ وَهُمۡ لَهُۥ مُنكِرُونَ","1654":"وَلَمَّا جَهَّزَهُم بِجَهَازِهِمۡ قَالَ ٱئۡتُونِي بِأَخٖ لَّكُم مِّنۡ أَبِيكُمۡۚ أَلَا تَرَوۡنَ أَنِّيٓ أُوفِي ٱلۡكَيۡلَ وَأَنَا۠ خَيۡرُ ٱلۡمُنزِلِينَ","1655":"فَإِن لَّمۡ تَأۡتُونِي بِهِۦ فَلَا كَيۡلَ لَكُمۡ عِندِي وَلَا تَقۡرَبُونِ","1656":"قَالُواْ سَنُرَٰوِدُ عَنۡهُ أَبَاهُ وَإِنَّا لَفَٰعِلُونَ","1657":"وَقَالَ لِفِتۡيَٰنِهِ ٱجۡعَلُواْ بِضَٰعَتَهُمۡ فِي رِحَالِهِمۡ لَعَلَّهُمۡ يَعۡرِفُونَهَآ إِذَا ٱنقَلَبُوٓاْ إِلَىٰٓ أَهۡلِهِمۡ لَعَلَّهُمۡ يَرۡجِعُونَ","1682":"يَٰبَنِيَّ ٱذۡهَبُواْ فَتَحَسَّسُواْ مِن يُوسُفَ وَأَخِيهِ وَلَا تَاْيۡـَٔسُواْ مِن رَّوۡحِ ٱللَّهِۖ إِنَّهُۥ لَا يَاْيۡـَٔسُ مِن رَّوۡحِ ٱللَّهِ إِلَّا ٱلۡقَوۡمُ ٱلۡكَٰفِرُونَ","1685":"قَالُوٓاْ أَءِنَّكَ لَأَنتَ يُوسُفُۖ قَالَ أَنَا۠ يُوسُفُ وَهَٰذَآ أَخِيۖ قَدۡ مَنَّ ٱللَّهُ عَلَيۡنَآۖ إِنَّهُۥ مَن يَتَّقِ وَيَصۡبِرۡ فَإِنَّ ٱللَّهَ لَا يُضِيعُ أَجۡرَ ٱلۡمُحۡسِنِينَ","1689":"وَلَمَّا فَصَلَتِ ٱلۡعِيرُ قَالَ أَبُوهُمۡ إِنِّي لَأَجِدُ رِيحَ يُوسُفَۖ لَوۡلَآ أَن تُفَنِّدُونِ","1690":"قَالُواْ تَٱللَّهِ إِنَّكَ لَفِي ضَلَٰلِكَ ٱلۡقَدِيمِ","1691":"فَلَمَّآ أَن جَآءَ ٱلۡبَشِيرُ أَلۡقَىٰهُ عَلَىٰ وَجۡهِهِۦ فَٱرۡتَدَّ بَصِيرٗاۖ قَالَ أَلَمۡ أَقُل لَّكُمۡ إِنِّيٓ أَعۡلَمُ مِنَ ٱللَّهِ مَا لَا تَعۡلَمُونَ","1692":"قَالُواْ يَٰٓأَبَانَا ٱسۡتَغۡفِرۡ لَنَا ذُنُوبَنَآ إِنَّا كُنَّا خَٰطِـِٔينَ","1693":"قَالَ سَوۡفَ أَسۡتَغۡفِرُ لَكُمۡ رَبِّيٓۖ إِنَّهُۥ هُوَ ٱلۡغَفُورُ ٱلرَّحِيمُ","1695":"وَرَفَعَ أَبَوَيۡهِ عَلَى ٱلۡعَرۡشِ وَخَرُّواْ لَهُۥ سُجَّدٗاۖ وَقَالَ يَٰٓأَبَتِ هَٰذَا تَأۡوِيلُ رُءۡيَٰيَ مِن قَبۡلُ قَدۡ جَعَلَهَا رَبِّي حَقّٗاۖ وَقَدۡ أَحۡسَنَ بِيٓ إِذۡ أَخۡرَجَنِي مِنَ ٱلسِّجۡنِ وَجَآءَ بِكُم مِّنَ ٱلۡبَدۡوِ مِنۢ بَعۡدِ أَن نَّزَغَ ٱلشَّيۡطَٰنُ بَيۡنِي وَبَيۡنَ إِخۡوَتِيٓۚ إِنَّ رَبِّي لَطِيفٞ لِّمَا يَشَآءُۚ إِنَّهُۥ هُوَ ٱلۡعَلِيمُ ٱلۡحَكِيمُ","1717":"لَهُۥ مُعَقِّبَٰتٞ مِّنۢ بَيۡنِ يَدَيۡهِ وَمِنۡ خَلۡفِهِۦ يَحۡفَظُونَهُۥ مِنۡ أَمۡرِ ٱللَّهِۗ إِنَّ ٱللَّهَ لَا يُغَيِّرُ مَا بِقَوۡمٍ حَتَّىٰ يُغَيِّرُواْ مَا بِأَنفُسِهِمۡۗ وَإِذَآ أَرَادَ ٱللَّهُ بِقَوۡمٖ سُوٓءٗا فَلَا مَرَدَّ لَهُۥۚ وَمَا لَهُم مِّن دُونِهِۦ مِن وَالٍ","1786":"رَّبَّنَآ إِنِّيٓ أَسۡكَنتُ مِن ذُرِّيَّتِي بِوَادٍ غَيۡرِ ذِي زَرۡعٍ عِندَ بَيۡتِكَ ٱلۡمُحَرَّمِ رَبَّنَا لِيُقِيمُواْ ٱلصَّلَوٰةَ فَٱجۡعَلۡ أَفۡـِٔدَةٗ مِّنَ ٱلنَّاسِ تَهۡوِيٓ إِلَيۡهِمۡ وَٱرۡزُقۡهُم مِّنَ ٱلثَّمَرَٰتِ لَعَلَّهُمۡ يَشۡكُرُونَ","1858":"قَالَ فَمَا خَطۡبُكُمۡ أَيُّهَا ٱلۡمُرۡسَلُونَ","1859":"قَالُوٓاْ إِنَّآ أُرۡسِلۡنَآ إِلَىٰ قَوۡمٖ مُّجۡرِمِينَ","1860":"إِلَّآ ءَالَ لُوطٍ إِنَّا لَمُنَجُّوهُمۡ أَجۡمَعِينَ","1861":"إِلَّا ٱمۡرَأَتَهُۥ قَدَّرۡنَآ إِنَّهَا لَمِنَ ٱلۡغَٰبِرِينَ","1862":"فَلَمَّا جَآءَ ءَالَ لُوطٍ ٱلۡمُرۡسَلُونَ","1878":"إِنَّ فِي ذَٰلِكَ لَأٓيَةٗ لِّلۡمُؤۡمِنِينَ","2044":"وَإِذَآ أَرَدۡنَآ أَن نُّهۡلِكَ قَرۡيَةً أَمَرۡنَا مُتۡرَفِيهَا فَفَسَقُواْ فِيهَا فَحَقَّ عَلَيۡهَا ٱلۡقَوۡلُ فَدَمَّرۡنَٰهَا تَدۡمِيرٗا","2148":"أَمۡ حَسِبۡتَ أَنَّ أَصۡحَٰبَ ٱلۡكَهۡفِ وَٱلرَّقِيمِ كَانُواْ مِنۡ ءَايَٰتِنَا عَجَبًا","2149":"إِذۡ أَوَى ٱلۡفِتۡيَةُ إِلَى ٱلۡكَهۡفِ فَقَالُواْ رَبَّنَآ ءَاتِنَا مِن لَّدُنكَ رَحۡمَةٗ وَهَيِّئۡ لَنَا مِنۡ أَمۡرِنَا رَشَدٗا","2150":"فَضَرَبۡنَا عَلَىٰٓ ءَاذَانِهِمۡ فِي ٱلۡكَهۡفِ سِنِينَ عَدَدٗا","2151":"ثُمَّ بَعَثۡنَٰهُمۡ لِنَعۡلَمَ أَيُّ ٱلۡحِزۡبَيۡنِ أَحۡصَىٰ لِمَا لَبِثُوٓاْ أَمَدٗا","2152":"نَّحۡنُ نَقُصُّ عَلَيۡكَ نَبَأَهُم بِٱلۡحَقِّۚ إِنَّهُمۡ فِتۡيَةٌ ءَامَنُواْ بِرَبِّهِمۡ وَزِدۡنَٰهُمۡ هُدٗى","2155":"وَإِذِ ٱعۡتَزَلۡتُمُوهُمۡ وَمَا يَعۡبُدُونَ إِلَّا ٱللَّهَ فَأۡوُۥٓاْ إِلَى ٱلۡكَهۡفِ يَنشُرۡ لَكُمۡ رَبُّكُم مِّن رَّحۡمَتِهِۦ وَيُهَيِّئۡ لَكُم مِّنۡ أَمۡرِكُم مِّرۡفَقٗا","2156":"۞ وَتَرَى ٱلشَّمۡسَ إِذَا طَلَعَت تَّزَٰوَرُ عَن كَهۡفِهِمۡ ذَاتَ ٱلۡيَمِينِ وَإِذَا غَرَبَت تَّقۡرِضُهُمۡ ذَاتَ ٱلشِّمَالِ وَهُمۡ فِي فَجۡوَةٖ مِّنۡهُۚ ذَٰلِكَ مِنۡ ءَايَٰتِ ٱللَّهِۗ مَن يَهۡدِ ٱللَّهُ فَهُوَ ٱلۡمُهۡتَدِۖ وَمَن يُضۡلِلۡ فَلَن تَجِدَ لَهُۥ وَلِيّٗا مُّرۡشِدٗا","2157":"وَتَحۡسَبُهُمۡ أَيۡقَاظٗا وَهُمۡ رُقُودٞۚ وَنُقَلِّبُهُمۡ ذَاتَ ٱلۡيَمِينِ وَذَاتَ ٱلشِّمَالِۖ وَكَلۡبُهُم بَٰسِطٞ ذِرَاعَيۡهِ بِٱلۡوَصِيدِۚ لَوِ ٱطَّلَعۡتَ عَلَيۡهِمۡ لَوَلَّيۡتَ مِنۡهُمۡ فِرَارٗا وَلَمُلِئۡتَ مِنۡهُمۡ رُعۡبٗا","2158":"وَكَذَٰلِكَ بَعَثۡنَٰهُمۡ لِيَتَسَآءَلُواْ بَيۡنَهُمۡۚ قَالَ قَآئِلٞ مِّنۡهُمۡ كَمۡ لَبِثۡتُمۡۖ قَالُواْ لَبِثۡنَا يَوۡمًا أَوۡ بَعۡضَ يَوۡمٖۚ قَالُواْ رَبُّكُمۡ أَعۡلَمُ بِمَا لَبِثۡتُمۡ فَٱبۡعَثُوٓاْ أَحَدَكُم بِوَرِقِكُمۡ هَٰذِهِۦٓ إِلَى ٱلۡمَدِينَةِ فَلۡيَنظُرۡ أَيُّهَآ أَزۡكَىٰ طَعَامٗا فَلۡيَأۡتِكُم بِرِزۡقٖ مِّنۡهُ وَلۡيَتَلَطَّفۡ وَلَا يُشۡعِرَنَّ بِكُمۡ أَحَدًا","2159":"إِنَّهُمۡ إِن يَظۡهَرُواْ عَلَيۡكُمۡ يَرۡجُمُوكُمۡ أَوۡ يُعِيدُوكُمۡ فِي مِلَّتِهِمۡ وَلَن تُفۡلِحُوٓاْ إِذًا أَبَدٗا","2160":"وَكَذَٰلِكَ أَعۡثَرۡنَا عَلَيۡهِمۡ لِيَعۡلَمُوٓاْ أَنَّ وَعۡدَ ٱللَّهِ حَقّٞ وَأَنَّ ٱلسَّاعَةَ لَا رَيۡبَ فِيهَآ إِذۡ يَتَنَٰزَعُونَ بَيۡنَهُمۡ أَمۡرَهُمۡۖ فَقَالُواْ ٱبۡنُواْ عَلَيۡهِم بُنۡيَٰنٗاۖ رَّبُّهُمۡ أَعۡلَمُ بِهِمۡۚ قَالَ ٱلَّذِينَ غَلَبُواْ عَلَىٰٓ أَمۡرِهِمۡ لَنَتَّخِذَنَّ عَلَيۡهِم مَّسۡجِدٗا","2161":"سَيَقُولُونَ ثَلَٰثَةٞ رَّابِعُهُمۡ كَلۡبُهُمۡ وَيَقُولُونَ خَمۡسَةٞ سَادِسُهُمۡ كَلۡبُهُمۡ رَجۡمَۢا بِٱلۡغَيۡبِۖ وَيَقُولُونَ سَبۡعَةٞ وَثَامِنُهُمۡ كَلۡبُهُمۡۚ قُل رَّبِّيٓ أَعۡلَمُ بِعِدَّتِهِم مَّا يَعۡلَمُهُمۡ إِلَّا قَلِيلٞۗ فَلَا تُمَارِ فِيهِمۡ إِلَّا مِرَآءٗ ظَٰهِرٗا وَلَا تَسۡتَفۡتِ فِيهِم مِّنۡهُمۡ أَحَدٗا","2162":"وَلَا تَقُولَنَّ لِشَاْيۡءٍ إِنِّي فَاعِلٞ ذَٰلِكَ غَدًا","2163":"إِلَّآ أَن يَشَآءَ ٱللَّهُۚ وَٱذۡكُر رَّبَّكَ إِذَا نَسِيتَ وَقُلۡ عَسَىٰٓ أَن يَهۡدِيَنِ رَبِّي لِأَقۡرَبَ مِنۡ هَٰذَا رَشَدٗا","2164":"وَلَبِثُواْ فِي كَهۡفِهِمۡ ثَلَٰثَ مِاْئَةٖ سِنِينَ وَٱزۡدَادُواْ تِسۡعٗا","2165":"قُلِ ٱللَّهُ أَعۡلَمُ بِمَا لَبِثُواْۖ لَهُۥ غَيۡبُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ أَبۡصِرۡ بِهِۦ وَأَسۡمِعۡۚ مَا لَهُم مِّن دُونِهِۦ مِن وَلِيّٖ وَلَا يُشۡرِكُ فِي حُكۡمِهِۦٓ أَحَدٗا","2199":"وَإِذۡ قَالَ مُوسَىٰ لِفَتَىٰهُ لَآ أَبۡرَحُ حَتَّىٰٓ أَبۡلُغَ مَجۡمَعَ ٱلۡبَحۡرَيۡنِ أَوۡ أَمۡضِيَ حُقُبٗا","2200":"فَلَمَّا بَلَغَا مَجۡمَعَ بَيۡنِهِمَا نَسِيَا حُوتَهُمَا فَٱتَّخَذَ سَبِيلَهُۥ فِي ٱلۡبَحۡرِ سَرَبٗا","2201":"فَلَمَّا جَاوَزَا قَالَ لِفَتَىٰهُ ءَاتِنَا غَدَآءَنَا لَقَدۡ لَقِينَا مِن سَفَرِنَا هَٰذَا نَصَبٗا","2202":"قَالَ أَرَءَيۡتَ إِذۡ أَوَيۡنَآ إِلَى ٱلصَّخۡرَةِ فَإِنِّي نَسِيتُ ٱلۡحُوتَ وَمَآ أَنسَىٰنِيهُ إِلَّا ٱلشَّيۡطَٰنُ أَنۡ أَذۡكُرَهُۥۚ وَٱتَّخَذَ سَبِيلَهُۥ فِي ٱلۡبَحۡرِ عَجَبٗا","2203":"قَالَ ذَٰلِكَ مَا كُنَّا نَبۡغِۚ فَٱرۡتَدَّا عَلَىٰٓ ءَاثَارِهِمَا قَصَصٗا","2204":"فَوَجَدَا عَبۡدٗا مِّنۡ عِبَادِنَآ ءَاتَيۡنَٰهُ رَحۡمَةٗ مِّنۡ عِندِنَا وَعَلَّمۡنَٰهُ مِن لَّدُنَّا عِلۡمٗا","2205":"قَالَ لَهُۥ مُوسَىٰ هَلۡ أَتَّبِعُكَ عَلَىٰٓ أَن تُعَلِّمَنِ مِمَّا عُلِّمۡتَ رُشۡدٗا","2206":"قَالَ إِنَّكَ لَن تَسۡتَطِيعَ مَعِيَ صَبۡرٗا","2207":"وَكَيۡفَ تَصۡبِرُ عَلَىٰ مَا لَمۡ تُحِطۡ بِهِۦ خُبۡرٗا","2208":"قَالَ سَتَجِدُنِيٓ إِن شَآءَ ٱللَّهُ صَابِرٗا وَلَآ أَعۡصِي لَكَ أَمۡرٗا","2209":"قَالَ فَإِنِ ٱتَّبَعۡتَنِي فَلَا تَسۡـَٔلۡنِي عَن شَيۡءٍ حَتَّىٰٓ أُحۡدِثَ لَكَ مِنۡهُ ذِكۡرٗا","2210":"فَٱنطَلَقَا حَتَّىٰٓ إِذَا رَكِبَا فِي ٱلسَّفِينَةِ خَرَقَهَاۖ قَالَ أَخَرَقۡتَهَا لِتُغۡرِقَ أَهۡلَهَا لَقَدۡ جِئۡتَ شَيۡـًٔا إِمۡرٗا","2211":"قَالَ أَلَمۡ أَقُلۡ إِنَّكَ لَن تَسۡتَطِيعَ مَعِيَ صَبۡرٗا","2212":"قَالَ لَا تُؤَاخِذۡنِي بِمَا نَسِيتُ وَلَا تُرۡهِقۡنِي مِنۡ أَمۡرِي عُسۡرٗا","2213":"فَٱنطَلَقَا حَتَّىٰٓ إِذَا لَقِيَا غُلَٰمٗا فَقَتَلَهُۥ قَالَ أَقَتَلۡتَ نَفۡسٗا زَكِيَّةَۢ بِغَيۡرِ نَفۡسٖ لَّقَدۡ جِئۡتَ شَيۡـٔٗا نُّكۡرٗا","2214":"۞ قَالَ أَلَمۡ أَقُل لَّكَ إِنَّكَ لَن تَسۡتَطِيعَ مَعِيَ صَبۡرٗا","2215":"قَالَ إِن سَأَلۡتُكَ عَن شَيۡءِۭ بَعۡدَهَا فَلَا تُصَٰحِبۡنِيۖ قَدۡ بَلَغۡتَ مِن لَّدُنِّي عُذۡرٗا","2216":"فَٱنطَلَقَا حَتَّىٰٓ إِذَآ أَتَيَآ أَهۡلَ قَرۡيَةٍ ٱسۡتَطۡعَمَآ أَهۡلَهَا فَأَبَوۡاْ أَن يُضَيِّفُوهُمَا فَوَجَدَا فِيهَا جِدَارٗا يُرِيدُ أَن يَنقَضَّ فَأَقَامَهُۥۖ قَالَ لَوۡ شِئۡتَ لَتَّخَذۡتَ عَلَيۡهِ أَجۡرٗا","2217":"قَالَ هَٰذَا فِرَاقُ بَيۡنِي وَبَيۡنِكَۚ سَأُنَبِّئُكَ بِتَأۡوِيلِ مَا لَمۡ تَسۡتَطِع عَّلَيۡهِ صَبۡرًا","2218":"أَمَّا ٱلسَّفِينَةُ فَكَانَتۡ لِمَسَٰكِينَ يَعۡمَلُونَ فِي ٱلۡبَحۡرِ فَأَرَدتُّ أَنۡ أَعِيبَهَا وَكَانَ وَرَآءَهُم مَّلِكٞ يَأۡخُذُ كُلَّ سَفِينَةٍ غَصۡبٗا","2219":"وَأَمَّا ٱلۡغُلَٰمُ فَكَانَ أَبَوَاهُ مُؤۡمِنَيۡنِ فَخَشِينَآ أَن يُرۡهِقَهُمَا طُغۡيَٰنٗا وَكُفۡرٗا","2220":"فَأَرَدۡنَآ أَن يُبۡدِلَهُمَا رَبُّهُمَا خَيۡرٗا مِّنۡهُ زَكَوٰةٗ وَأَقۡرَبَ رُحۡمٗا","2221":"وَأَمَّا ٱلۡجِدَارُ فَكَانَ لِغُلَٰمَيۡنِ يَتِيمَيۡنِ فِي ٱلۡمَدِينَةِ وَكَانَ تَحۡتَهُۥ كَنزٞ لَّهُمَا وَكَانَ أَبُوهُمَا صَٰلِحٗا فَأَرَادَ رَبُّكَ أَن يَبۡلُغَآ أَشُدَّهُمَا وَيَسۡتَخۡرِجَا كَنزَهُمَا رَحۡمَةٗ مِّن رَّبِّكَۚ وَمَا فَعَلۡتُهُۥ عَنۡ أَمۡرِيۚ ذَٰلِكَ تَأۡوِيلُ مَا لَمۡ تَسۡطِع عَّلَيۡهِ صَبۡرٗا","2222":"وَيَسۡـَٔلُونَكَ عَن ذِي ٱلۡقَرۡنَيۡنِۖ قُلۡ سَأَتۡلُواْ عَلَيۡكُم مِّنۡهُ ذِكۡرًا","2223":"إِنَّا مَكَّنَّا لَهُۥ فِي ٱلۡأَرۡضِ وَءَاتَيۡنَٰهُ مِن كُلِّ شَيۡءٖ سَبَبٗا","2224":"فَأَتۡبَعَ سَبَبًا","2225":"حَتَّىٰٓ إِذَا بَلَغَ مَغۡرِبَ ٱلشَّمۡسِ وَجَدَهَا تَغۡرُبُ فِي عَيۡنٍ حَمِئَةٖ وَوَجَدَ عِندَهَا قَوۡمٗاۖ قُلۡنَا يَٰذَا ٱلۡقَرۡنَيۡنِ إِمَّآ أَن تُعَذِّبَ وَإِمَّآ أَن تَتَّخِذَ فِيهِمۡ حُسۡنٗا","2226":"قَالَ أَمَّا مَن ظَلَمَ فَسَوۡفَ نُعَذِّبُهُۥ ثُمَّ يُرَدُّ إِلَىٰ رَبِّهِۦ فَيُعَذِّبُهُۥ عَذَابٗا نُّكۡرٗا","2227":"وَأَمَّا مَنۡ ءَامَنَ وَعَمِلَ صَٰلِحٗا فَلَهُۥ جَزَآءً ٱلۡحُسۡنَىٰۖ وَسَنَقُولُ لَهُۥ مِنۡ أَمۡرِنَا يُسۡرٗا","2228":"ثُمَّ أَتۡبَعَ سَبَبًا","2229":"حَتَّىٰٓ إِذَا بَلَغَ مَطۡلِعَ ٱلشَّمۡسِ وَجَدَهَا تَطۡلُعُ عَلَىٰ قَوۡمٖ لَّمۡ نَجۡعَل لَّهُم مِّن دُونِهَا سِتۡرٗا","2230":"كَذَٰلِكَۖ وَقَدۡ أَحَطۡنَا بِمَا لَدَيۡهِ خُبۡرٗا","2231":"ثُمَّ أَتۡبَعَ سَبَبًا","2232":"حَتَّىٰٓ إِذَا بَلَغَ بَيۡنَ ٱلسَّدَّيۡنِ وَجَدَ مِن دُونِهِمَا قَوۡمٗا لَّا يَكَادُونَ يَفۡقَهُونَ قَوۡلٗا","2233":"قَالُواْ يَٰذَا ٱلۡقَرۡنَيۡنِ إِنَّ يَأۡجُوجَ وَمَأۡجُوجَ مُفۡسِدُونَ فِي ٱلۡأَرۡضِ فَهَلۡ نَجۡعَلُ لَكَ خَرۡجًا عَلَىٰٓ أَن تَجۡعَلَ بَيۡنَنَا وَبَيۡنَهُمۡ سَدّٗا","2234":"قَالَ مَا مَكَّنِّي فِيهِ رَبِّي خَيۡرٞ فَأَعِينُونِي بِقُوَّةٍ أَجۡعَلۡ بَيۡنَكُمۡ وَبَيۡنَهُمۡ رَدۡمًا","2235":"ءَاتُونِي زُبَرَ ٱلۡحَدِيدِۖ حَتَّىٰٓ إِذَا سَاوَىٰ بَيۡنَ ٱلصَّدَفَيۡنِ قَالَ ٱنفُخُواْۖ حَتَّىٰٓ إِذَا جَعَلَهُۥ نَارٗا قَالَ ءَاتُونِيٓ أُفۡرِغۡ عَلَيۡهِ قِطۡرٗا","2237":"قَالَ هَٰذَا رَحۡمَةٞ مِّن رَّبِّيۖ فَإِذَا جَآءَ وَعۡدُ رَبِّي جَعَلَهُۥ دَكَّآءَۖ وَكَانَ وَعۡدُ رَبِّي حَقّٗا","2265":"وَٱذۡكُرۡ فِي ٱلۡكِتَٰبِ مَرۡيَمَ إِذِ ٱنتَبَذَتۡ مِنۡ أَهۡلِهَا مَكَانٗا شَرۡقِيّٗا","2266":"فَٱتَّخَذَتۡ مِن دُونِهِمۡ حِجَابٗا فَأَرۡسَلۡنَآ إِلَيۡهَا رُوحَنَا فَتَمَثَّلَ لَهَا بَشَرٗا سَوِيّٗا","2267":"قَالَتۡ إِنِّيٓ أَعُوذُ بِٱلرَّحۡمَٰنِ مِنكَ إِن كُنتَ تَقِيّٗا","2268":"قَالَ إِنَّمَآ أَنَا۠ رَسُولُ رَبِّكِ لِأَهَبَ لَكِ غُلَٰمٗا زَكِيّٗا","2269":"قَالَتۡ أَنَّىٰ يَكُونُ لِي غُلَٰمٞ وَلَمۡ يَمۡسَسۡنِي بَشَرٞ وَلَمۡ أَكُ بَغِيّٗا","2270":"قَالَ كَذَٰلِكِ قَالَ رَبُّكِ هُوَ عَلَيَّ هَيِّنٞۖ وَلِنَجۡعَلَهُۥٓ ءَايَةٗ لِّلنَّاسِ وَرَحۡمَةٗ مِّنَّاۚ وَكَانَ أَمۡرٗا مَّقۡضِيّٗا","2271":"۞ فَحَمَلَتۡهُ فَٱنتَبَذَتۡ بِهِۦ مَكَانٗا قَصِيّٗا","2272":"فَأَجَآءَهَا ٱلۡمَخَاضُ إِلَىٰ جِذۡعِ ٱلنَّخۡلَةِ قَالَتۡ يَٰلَيۡتَنِي مِتُّ قَبۡلَ هَٰذَا وَكُنتُ نَسۡيٗا مَّنسِيّٗا","2273":"فَنَادَىٰهَا مِن تَحۡتِهَآ أَلَّا تَحۡزَنِي قَدۡ جَعَلَ رَبُّكِ تَحۡتَكِ سَرِيّٗا","2274":"وَهُزِّيٓ إِلَيۡكِ بِجِذۡعِ ٱلنَّخۡلَةِ تُسَٰقِطۡ عَلَيۡكِ رُطَبٗا جَنِيّٗا","2275":"فَكُلِي وَٱشۡرَبِي وَقَرِّي عَيۡنٗاۖ فَإِمَّا تَرَيِنَّ مِنَ ٱلۡبَشَرِ أَحَدٗا فَقُولِيٓ إِنِّي نَذَرۡتُ لِلرَّحۡمَٰنِ صَوۡمٗا فَلَنۡ أُكَلِّمَ ٱلۡيَوۡمَ إِنسِيّٗا","2276":"فَأَتَتۡ بِهِۦ قَوۡمَهَا تَحۡمِلُهُۥۖ قَالُواْ يَٰمَرۡيَمُ لَقَدۡ جِئۡتِ شَيۡـٔٗا فَرِيّٗا","2277":"يَٰٓأُخۡتَ هَٰرُونَ مَا كَانَ أَبُوكِ ٱمۡرَأَ سَوۡءٖ وَمَا كَانَتۡ أُمُّكِ بَغِيّٗا","2278":"فَأَشَارَتۡ إِلَيۡهِۖ قَالُواْ كَيۡفَ نُكَلِّمُ مَن كَانَ فِي ٱلۡمَهۡدِ صَبِيّٗا","2279":"قَالَ إِنِّي عَبۡدُ ٱللَّهِ ءَاتَىٰنِيَ ٱلۡكِتَٰبَ وَجَعَلَنِي نَبِيّٗا","2280":"وَجَعَلَنِي مُبَارَكًا أَيۡنَ مَا كُنتُ وَأَوۡصَٰنِي بِٱلصَّلَوٰةِ وَٱلزَّكَوٰةِ مَا دُمۡتُ حَيّٗا","2356":"وَهَلۡ أَتَىٰكَ حَدِيثُ مُوسَىٰٓ","2357":"إِذۡ رَءَا نَارٗا فَقَالَ لِأَهۡلِهِ ٱمۡكُثُوٓاْ إِنِّيٓ ءَانَسۡتُ نَارٗا لَّعَلِّيٓ ءَاتِيكُم مِّنۡهَا بِقَبَسٍ أَوۡ أَجِدُ عَلَى ٱلنَّارِ هُدٗى","2358":"فَلَمَّآ أَتَىٰهَا نُودِيَ يَٰمُوسَىٰٓ","2359":"إِنِّيٓ أَنَا۠ رَبُّكَ فَٱخۡلَعۡ نَعۡلَيۡكَ إِنَّكَ بِٱلۡوَادِ ٱلۡمُقَدَّسِ طُوٗى","2360":"وَأَنَا ٱخۡتَرۡتُكَ فَٱسۡتَمِعۡ لِمَا يُوحَىٰٓ","2462":"وَلَقَدۡ عَهِدۡنَآ إِلَىٰٓ ءَادَمَ مِن قَبۡلُ فَنَسِيَ وَلَمۡ نَجِدۡ لَهُۥ عَزۡمٗا","2463":"وَإِذۡ قُلۡنَا لِلۡمَلَٰٓئِكَةِ ٱسۡجُدُواْ لِأٓدَمَ فَسَجَدُوٓاْ إِلَّآ إِبۡلِيسَ أَبَىٰ","2464":"فَقُلۡنَا يَٰٓـَٔادَمُ إِنَّ هَٰذَا عَدُوّٞ لَّكَ وَلِزَوۡجِكَ فَلَا يُخۡرِجَنَّكُمَا مِنَ ٱلۡجَنَّةِ فَتَشۡقَىٰٓ","2465":"إِنَّ لَكَ أَلَّا تَجُوعَ فِيهَا وَلَا تَعۡرَىٰ","2466":"وَأَنَّكَ لَا تَظۡمَؤُاْ فِيهَا وَلَا تَضۡحَىٰ","2533":"۞ وَلَقَدۡ ءَاتَيۡنَآ إِبۡرَٰهِيمَ رُشۡدَهُۥ مِن قَبۡلُ وَكُنَّا بِهِۦ عَٰلِمِينَ","2534":"إِذۡ قَالَ لِأَبِيهِ وَقَوۡمِهِۦ مَا هَٰذِهِ ٱلتَّمَاثِيلُ ٱلَّتِيٓ أَنتُمۡ لَهَا عَٰكِفُونَ","2535":"قَالُواْ وَجَدۡنَآ ءَابَآءَنَا لَهَا عَٰبِدِينَ","2536":"قَالَ لَقَدۡ كُنتُمۡ أَنتُمۡ وَءَابَآؤُكُمۡ فِي ضَلَٰلٖ مُّبِينٖ","2537":"قَالُوٓاْ أَجِئۡتَنَا بِٱلۡحَقِّ أَمۡ أَنتَ مِنَ ٱللَّٰعِبِينَ","2541":"قَالُواْ مَن فَعَلَ هَٰذَا بِـَٔالِهَتِنَآ إِنَّهُۥ لَمِنَ ٱلظَّٰلِمِينَ","2551":"قُلۡنَا يَٰنَارُ كُونِي بَرۡدٗا وَسَلَٰمًا عَلَىٰٓ إِبۡرَٰهِيمَ","2702":"إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ وَإِن كُنَّا لَمُبۡتَلِينَ","3091":"كَذَّبَتۡ قَوۡمُ لُوطٍ ٱلۡمُرۡسَلِينَ","3092":"إِذۡ قَالَ لَهُمۡ أَخُوهُمۡ لُوطٌ أَلَا تَتَّقُونَ","3093":"إِنِّي لَكُمۡ رَسُولٌ أَمِينٞ","3094":"فَٱتَّقُواْ ٱللَّهَ وَأَطِيعُونِ","3095":"وَمَآ أَسۡـَٔلُكُمۡ عَلَيۡهِ مِنۡ أَجۡرٍۖ إِنۡ أَجۡرِيَ إِلَّا عَلَىٰ رَبِّ ٱلۡعَٰلَمِينَ","3099":"قَالَ إِنِّي لِعَمَلِكُم مِّنَ ٱلۡقَالِينَ","3173":"وَلَقَدۡ ءَاتَيۡنَا دَاوُۥدَ وَسُلَيۡمَٰنَ عِلۡمٗاۖ وَقَالَا ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِي فَضَّلَنَا عَلَىٰ كَثِيرٖ مِّنۡ عِبَادِهِ ٱلۡمُؤۡمِنِينَ","3174":"وَوَرِثَ سُلَيۡمَٰنُ دَاوُۥدَۖ وَقَالَ يَٰٓأَيُّهَا ٱلنَّاسُ عُلِّمۡنَا مَنطِقَ ٱلطَّيۡرِ وَأُوتِينَا مِن كُلِّ شَيۡءٍۖ إِنَّ هَٰذَا لَهُوَ ٱلۡفَضۡلُ ٱلۡمُبِينُ","3175":"وَحُشِرَ لِسُلَيۡمَٰنَ جُنُودُهُۥ مِنَ ٱلۡجِنِّ وَٱلۡإِنسِ وَٱلطَّيۡرِ فَهُمۡ يُوزَعُونَ","3176":"حَتَّىٰٓ إِذَآ أَتَوۡاْ عَلَىٰ وَادِ ٱلنَّمۡلِ قَالَتۡ نَمۡلَةٞ يَٰٓأَيُّهَا ٱلنَّمۡلُ ٱدۡخُلُواْ مَسَٰكِنَكُمۡ لَا يَحۡطِمَنَّكُمۡ سُلَيۡمَٰنُ وَجُنُودُهُۥ وَهُمۡ لَا يَشۡعُرُونَ","3177":"فَتَبَسَّمَ ضَاحِكٗا مِّن قَوۡلِهَا وَقَالَ رَبِّ أَوۡزِعۡنِيٓ أَنۡ أَشۡكُرَ نِعۡمَتَكَ ٱلَّتِيٓ أَنۡعَمۡتَ عَلَيَّ وَعَلَىٰ وَٰلِدَيَّ وَأَنۡ أَعۡمَلَ صَٰلِحٗا تَرۡضَىٰهُ وَأَدۡخِلۡنِي بِرَحۡمَتِكَ فِي عِبَادِكَ ٱلصَّٰلِحِينَ","3178":"وَتَفَقَّدَ ٱلطَّيۡرَ فَقَالَ مَالِيَ لَآ أَرَى ٱلۡهُدۡهُدَ أَمۡ كَانَ مِنَ ٱلۡغَآئِبِينَ","3179":"لَأُعَذِّبَنَّهُۥ عَذَابٗا شَدِيدًا أَوۡ لَأَاْذۡبَحَنَّهُۥٓ أَوۡ لَيَأۡتِيَنِّي بِسُلۡطَٰنٖ مُّبِينٖ","3180":"فَمَكَثَ غَيۡرَ بَعِيدٖ فَقَالَ أَحَطتُ بِمَا لَمۡ تُحِطۡ بِهِۦ وَجِئۡتُكَ مِن سَبَإِۭ بِنَبَإٖ يَقِينٍ","3181":"إِنِّي وَجَدتُّ ٱمۡرَأَةٗ تَمۡلِكُهُمۡ وَأُوتِيَتۡ مِن كُلِّ شَيۡءٖ وَلَهَا عَرۡشٌ عَظِيمٞ","3182":"وَجَدتُّهَا وَقَوۡمَهَا يَسۡجُدُونَ لِلشَّمۡسِ مِن دُونِ ٱللَّهِ وَزَيَّنَ لَهُمُ ٱلشَّيۡطَٰنُ أَعۡمَٰلَهُمۡ فَصَدَّهُمۡ عَنِ ٱلسَّبِيلِ فَهُمۡ لَا يَهۡتَدُونَ","3255":"إِنَّ فِرۡعَوۡنَ عَلَا فِي ٱلۡأَرۡضِ وَجَعَلَ أَهۡلَهَا شِيَعٗا يَسۡتَضۡعِفُ طَآئِفَةٗ مِّنۡهُمۡ يُذَبِّحُ أَبۡنَآءَهُمۡ وَيَسۡتَحۡيِۦ نِسَآءَهُمۡۚ إِنَّهُۥ كَانَ مِنَ ٱلۡمُفۡسِدِينَ","3256":"وَنُرِيدُ أَن نَّمُنَّ عَلَى ٱلَّذِينَ ٱسۡتُضۡعِفُواْ فِي ٱلۡأَرۡضِ وَنَجۡعَلَهُمۡ أَئِمَّةٗ وَنَجۡعَلَهُمُ ٱلۡوَٰرِثِينَ","3257":"وَنُمَكِّنَ لَهُمۡ فِي ٱلۡأَرۡضِ وَنُرِيَ فِرۡعَوۡنَ وَهَٰمَٰنَ وَجُنُودَهُمَا مِنۡهُم مَّا كَانُواْ يَحۡذَرُونَ","3258":"وَأَوۡحَيۡنَآ إِلَىٰٓ أُمِّ مُوسَىٰٓ أَنۡ أَرۡضِعِيهِۖ فَإِذَا خِفۡتِ عَلَيۡهِ فَأَلۡقِيهِ فِي ٱلۡيَمِّ وَلَا تَخَافِي وَلَا تَحۡزَنِيٓۖ إِنَّا رَآدُّوهُ إِلَيۡكِ وَجَاعِلُوهُ مِنَ ٱلۡمُرۡسَلِينَ","3259":"فَٱلۡتَقَطَهُۥٓ ءَالُ فِرۡعَوۡنَ لِيَكُونَ لَهُمۡ عَدُوّٗا وَحَزَنًاۗ إِنَّ فِرۡعَوۡنَ وَهَٰمَٰنَ وَجُنُودَهُمَا كَانُواْ خَٰطِـِٔينَ","3260":"وَقَالَتِ ٱمۡرَأَتُ فِرۡعَوۡنَ قُرَّتُ عَيۡنٖ لِّي وَلَكَۖ لَا تَقۡتُلُوهُ عَسَىٰٓ أَن يَنفَعَنَآ أَوۡ نَتَّخِذَهُۥ وَلَدٗا وَهُمۡ لَا يَشۡعُرُونَ","3261":"وَأَصۡبَحَ فُؤَادُ أُمِّ مُوسَىٰ فَٰرِغًاۖ إِن كَادَتۡ لَتُبۡدِي بِهِۦ لَوۡلَآ أَن رَّبَطۡنَا عَلَىٰ قَلۡبِهَا لِتَكُونَ مِنَ ٱلۡمُؤۡمِنِينَ","3262":"وَقَالَتۡ لِأُخۡتِهِۦ قُصِّيهِۖ فَبَصُرَتۡ بِهِۦ عَن جُنُبٖ وَهُمۡ لَا يَشۡعُرُونَ","3264":"فَرَدَدۡنَٰهُ إِلَىٰٓ أُمِّهِۦ كَيۡ تَقَرَّ عَيۡنُهَا وَلَا تَحۡزَنَ وَلِتَعۡلَمَ أَنَّ وَعۡدَ ٱللَّهِ حَقّٞ وَلَٰكِنَّ أَكۡثَرَهُمۡ لَا يَعۡلَمُونَ","3265":"وَلَمَّا بَلَغَ أَشُدَّهُۥ وَٱسۡتَوَىٰٓ ءَاتَيۡنَٰهُ حُكۡمٗا وَعِلۡمٗاۚ وَكَذَٰلِكَ نَجۡزِي ٱلۡمُحۡسِنِينَ","3266":"وَدَخَلَ ٱلۡمَدِينَةَ عَلَىٰ حِينِ غَفۡلَةٖ مِّنۡ أَهۡلِهَا فَوَجَدَ فِيهَا رَجُلَيۡنِ يَقۡتَتِلَانِ هَٰذَا مِن شِيعَتِهِۦ وَهَٰذَا مِنۡ عَدُوِّهِۦۖ فَٱسۡتَغَٰثَهُ ٱلَّذِي مِن شِيعَتِهِۦ عَلَى ٱلَّذِي مِنۡ عَدُوِّهِۦ فَوَكَزَهُۥ مُوسَىٰ فَقَضَىٰ عَلَيۡهِۖ قَالَ هَٰذَا مِنۡ عَمَلِ ٱلشَّيۡطَٰنِۖ إِنَّهُۥ عَدُوّٞ مُّضِلّٞ مُّبِينٞ","3267":"قَالَ رَبِّ إِنِّي ظَلَمۡتُ نَفۡسِي فَٱغۡفِرۡ لِي فَغَفَرَ لَهُۥٓۚ إِنَّهُۥ هُوَ ٱلۡغَفُورُ ٱلرَّحِيمُ","3268":"قَالَ رَبِّ بِمَآ أَنۡعَمۡتَ عَلَيَّ فَلَنۡ أَكُونَ ظَهِيرٗا لِّلۡمُجۡرِمِينَ","3269":"فَأَصۡبَحَ فِي ٱلۡمَدِينَةِ خَآئِفٗا يَتَرَقَّبُ فَإِذَا ٱلَّذِي ٱسۡتَنصَرَهُۥ بِٱلۡأَمۡسِ يَسۡتَصۡرِخُهُۥۚ قَالَ لَهُۥ مُوسَىٰٓ إِنَّكَ لَغَوِيّٞ مُّبِينٞ","3273":"وَلَمَّا تَوَجَّهَ تِلۡقَآءَ مَدۡيَنَ قَالَ عَسَىٰ رَبِّيٓ أَن يَهۡدِيَنِي سَوَآءَ ٱلسَّبِيلِ","3274":"وَلَمَّا وَرَدَ مَآءَ مَدۡيَنَ وَجَدَ عَلَيۡهِ أُمَّةٗ مِّنَ ٱلنَّاسِ يَسۡقُونَ وَوَجَدَ مِن دُونِهِمُ ٱمۡرَأَتَيۡنِ تَذُودَانِۖ قَالَ مَا خَطۡبُكُمَاۖ قَالَتَا لَا نَسۡقِي حَتَّىٰ يُصۡدِرَ ٱلرِّعَآءُۖ وَأَبُونَا شَيۡخٞ كَبِيرٞ","3275":"فَسَقَىٰ لَهُمَا ثُمَّ تَوَلَّىٰٓ إِلَى ٱلظِّلِّ فَقَالَ رَبِّ إِنِّي لِمَآ أَنزَلۡتَ إِلَيَّ مِنۡ خَيۡرٖ فَقِيرٞ","3276":"فَجَآءَتۡهُ إِحۡدَىٰهُمَا تَمۡشِي عَلَى ٱسۡتِحۡيَآءٖ قَالَتۡ إِنَّ أَبِي يَدۡعُوكَ لِيَجۡزِيَكَ أَجۡرَ مَا سَقَيۡتَ لَنَاۚ فَلَمَّا جَآءَهُۥ وَقَصَّ عَلَيۡهِ ٱلۡقَصَصَ قَالَ لَا تَخَفۡۖ نَجَوۡتَ مِنَ ٱلۡقَوۡمِ ٱلظَّٰلِمِينَ","3277":"قَالَتۡ إِحۡدَىٰهُمَا يَٰٓأَبَتِ ٱسۡتَـٔۡجِرۡهُۖ إِنَّ خَيۡرَ مَنِ ٱسۡتَـٔۡجَرۡتَ ٱلۡقَوِيُّ ٱلۡأَمِينُ","3289":"وَقَالَ فِرۡعَوۡنُ يَٰٓأَيُّهَا ٱلۡمَلَأُ مَا عَلِمۡتُ لَكُم مِّنۡ إِلَٰهٍ غَيۡرِي فَأَوۡقِدۡ لِي يَٰهَٰمَٰنُ عَلَى ٱلطِّينِ فَٱجۡعَل لِّي صَرۡحٗا لَّعَلِّيٓ أَطَّلِعُ إِلَىٰٓ إِلَٰهِ مُوسَىٰ وَإِنِّي لَأَظُنُّهُۥ مِنَ ٱلۡكَٰذِبِينَ","3290":"وَٱسۡتَكۡبَرَ هُوَ وَجُنُودُهُۥ فِي ٱلۡأَرۡضِ بِغَيۡرِ ٱلۡحَقِّ وَظَنُّوٓاْ أَنَّهُمۡ إِلَيۡنَا لَا يُرۡجَعُونَ","3291":"فَأَخَذۡنَٰهُ وَجُنُودَهُۥ فَنَبَذۡنَٰهُمۡ فِي ٱلۡيَمِّۖ فَٱنظُرۡ كَيۡفَ كَانَ عَٰقِبَةُ ٱلظَّٰلِمِينَ","3292":"وَجَعَلۡنَٰهُمۡ أَئِمَّةٗ يَدۡعُونَ إِلَى ٱلنَّارِۖ وَيَوۡمَ ٱلۡقِيَٰمَةِ لَا يُنصَرُونَ","3293":"وَأَتۡبَعۡنَٰهُمۡ فِي هَٰذِهِ ٱلدُّنۡيَا لَعۡنَةٗۖ وَيَوۡمَ ٱلۡقِيَٰمَةِ هُم مِّنَ ٱلۡمَقۡبُوحِينَ","3327":"۞ إِنَّ قَٰرُونَ كَانَ مِن قَوۡمِ مُوسَىٰ فَبَغَىٰ عَلَيۡهِمۡۖ وَءَاتَيۡنَٰهُ مِنَ ٱلۡكُنُوزِ مَآ إِنَّ مَفَاتِحَهُۥ لَتَنُوٓأُ بِٱلۡعُصۡبَةِ أُوْلِي ٱلۡقُوَّةِ إِذۡ قَالَ لَهُۥ قَوۡمُهُۥ لَا تَفۡرَحۡۖ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلۡفَرِحِينَ","3328":"وَٱبۡتَغِ فِيمَآ ءَاتَىٰكَ ٱللَّهُ ٱلدَّارَ ٱلۡأٓخِرَةَۖ وَلَا تَنسَ نَصِيبَكَ مِنَ ٱلدُّنۡيَاۖ وَأَحۡسِن كَمَآ أَحۡسَنَ ٱللَّهُ إِلَيۡكَۖ وَلَا تَبۡغِ ٱلۡفَسَادَ فِي ٱلۡأَرۡضِۖ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلۡمُفۡسِدِينَ","3329":"قَالَ إِنَّمَآ أُوتِيتُهُۥ عَلَىٰ عِلۡمٍ عِندِيٓۚ أَوَلَمۡ يَعۡلَمۡ أَنَّ ٱللَّهَ قَدۡ أَهۡلَكَ مِن قَبۡلِهِۦ مِنَ ٱلۡقُرُونِ مَنۡ هُوَ أَشَدُّ مِنۡهُ قُوَّةٗ وَأَكۡثَرُ جَمۡعٗاۚ وَلَا يُسۡـَٔلُ عَن ذُنُوبِهِمُ ٱلۡمُجۡرِمُونَ","3330":"فَخَرَجَ عَلَىٰ قَوۡمِهِۦ فِي زِينَتِهِۦۖ قَالَ ٱلَّذِينَ يُرِيدُونَ ٱلۡحَيَوٰةَ ٱلدُّنۡيَا يَٰلَيۡتَ لَنَا مِثۡلَ مَآ أُوتِيَ قَٰرُونُ إِنَّهُۥ لَذُو حَظٍّ عَظِيمٖ","3331":"وَقَالَ ٱلَّذِينَ أُوتُواْ ٱلۡعِلۡمَ وَيۡلَكُمۡ ثَوَابُ ٱللَّهِ خَيۡرٞ لِّمَنۡ ءَامَنَ وَعَمِلَ صَٰلِحٗاۚ وَلَا يُلَقَّىٰهَآ إِلَّا ٱلصَّٰبِرُونَ","3332":"فَخَسَفۡنَا بِهِۦ وَبِدَارِهِ ٱلۡأَرۡضَ فَمَا كَانَ لَهُۥ مِن فِئَةٖ يَنصُرُونَهُۥ مِن دُونِ ٱللَّهِ وَمَا كَانَ مِنَ ٱلۡمُنتَصِرِينَ","3333":"وَأَصۡبَحَ ٱلَّذِينَ تَمَنَّوۡاْ مَكَانَهُۥ بِٱلۡأَمۡسِ يَقُولُونَ وَيۡكَأَنَّ ٱللَّهَ يَبۡسُطُ ٱلرِّزۡقَ لِمَن يَشَآءُ مِنۡ عِبَادِهِۦ وَيَقۡدِرُۖ لَوۡلَآ أَن مَّنَّ ٱللَّهُ عَلَيۡنَا لَخَسَفَ بِنَاۖ وَيۡكَأَنَّهُۥ لَا يُفۡلِحُ ٱلۡكَٰفِرُونَ","3334":"تِلۡكَ ٱلدَّارُ ٱلۡأٓخِرَةُ نَجۡعَلُهَا لِلَّذِينَ لَا يُرِيدُونَ عُلُوّٗا فِي ٱلۡأَرۡضِ وَلَا فَسَادٗاۚ وَٱلۡعَٰقِبَةُ لِلۡمُتَّقِينَ","3335":"مَن جَآءَ بِٱلۡحَسَنَةِ فَلَهُۥ خَيۡرٞ مِّنۡهَاۖ وَمَن جَآءَ بِٱلسَّيِّئَةِ فَلَا يُجۡزَى ٱلَّذِينَ عَمِلُواْ ٱلسَّيِّـَٔاتِ إِلَّا مَا كَانُواْ يَعۡمَلُونَ","3353":"وَلَقَدۡ أَرۡسَلۡنَا نُوحًا إِلَىٰ قَوۡمِهِۦ فَلَبِثَ فِيهِمۡ أَلۡفَ سَنَةٍ إِلَّا خَمۡسِينَ عَامٗا فَأَخَذَهُمُ ٱلطُّوفَانُ وَهُمۡ ظَٰلِمُونَ","3354":"فَأَنجَيۡنَٰهُ وَأَصۡحَٰبَ ٱلسَّفِينَةِ وَجَعَلۡنَٰهَآ ءَايَةٗ لِّلۡعَٰلَمِينَ","3379":"فَكُلًّا أَخَذۡنَا بِذَنۢبِهِۦۖ فَمِنۡهُم مَّنۡ أَرۡسَلۡنَا عَلَيۡهِ حَاصِبٗا وَمِنۡهُم مَّنۡ أَخَذَتۡهُ ٱلصَّيۡحَةُ وَمِنۡهُم مَّنۡ خَسَفۡنَا بِهِ ٱلۡأَرۡضَ وَمِنۡهُم مَّنۡ أَغۡرَقۡنَاۚ وَمَا كَانَ ٱللَّهُ لِيَظۡلِمَهُمۡ وَلَٰكِن كَانُوٓاْ أَنفُسَهُمۡ يَظۡلِمُونَ","3617":"وَلِسُلَيۡمَٰنَ ٱلرِّيحَ غُدُوُّهَا شَهۡرٞ وَرَوَاحُهَا شَهۡرٞۖ وَأَسَلۡنَا لَهُۥ عَيۡنَ ٱلۡقِطۡرِۖ وَمِنَ ٱلۡجِنِّ مَن يَعۡمَلُ بَيۡنَ يَدَيۡهِ بِإِذۡنِ رَبِّهِۦۖ وَمَن يَزِغۡ مِنۡهُمۡ عَنۡ أَمۡرِنَا نُذِقۡهُ مِنۡ عَذَابِ ٱلسَّعِيرِ","3618":"يَعۡمَلُونَ لَهُۥ مَا يَشَآءُ مِن مَّحَٰرِيبَ وَتَمَٰثِيلَ وَجِفَانٖ كَٱلۡجَوَابِ وَقُدُورٖ رَّاسِيَٰتٍۚ ٱعۡمَلُوٓاْ ءَالَ دَاوُۥدَ شُكۡرٗاۚ وَقَلِيلٞ مِّنۡ عِبَادِيَ ٱلشَّكُورُ","3619":"فَلَمَّا قَضَيۡنَا عَلَيۡهِ ٱلۡمَوۡتَ مَا دَلَّهُمۡ عَلَىٰ مَوۡتِهِۦٓ إِلَّا دَآبَّةُ ٱلۡأَرۡضِ تَأۡكُلُ مِنسَأَتَهُۥۖ فَلَمَّا خَرَّ تَبَيَّنَتِ ٱلۡجِنُّ أَن لَّوۡ كَانُواْ يَعۡلَمُونَ ٱلۡغَيۡبَ مَا لَبِثُواْ فِي ٱلۡعَذَابِ ٱلۡمُهِينِ","3620":"لَقَدۡ كَانَ لِسَبَإٖ فِي مَسۡكَنِهِمۡ ءَايَةٞۖ جَنَّتَانِ عَن يَمِينٖ وَشِمَالٖۖ كُلُواْ مِن رِّزۡقِ رَبِّكُمۡ وَٱشۡكُرُواْ لَهُۥۚ بَلۡدَةٞ طَيِّبَةٞ وَرَبٌّ غَفُورٞ","3621":"فَأَعۡرَضُواْ فَأَرۡسَلۡنَا عَلَيۡهِمۡ سَيۡلَ ٱلۡعَرِمِ وَبَدَّلۡنَٰهُم بِجَنَّتَيۡهِمۡ جَنَّتَيۡنِ ذَوَاتَيۡ أُكُلٍ خَمۡطٖ وَأَثۡلٖ وَشَيۡءٖ مِّن سِدۡرٖ قَلِيلٖ","3622":"ذَٰلِكَ جَزَيۡنَٰهُم بِمَا كَفَرُواْۖ وَهَلۡ نُجَٰزِيٓ إِلَّا ٱلۡكَفُورَ","3623":"وَجَعَلۡنَا بَيۡنَهُمۡ وَبَيۡنَ ٱلۡقُرَى ٱلَّتِي بَٰرَكۡنَا فِيهَا قُرٗى ظَٰهِرَةٗ وَقَدَّرۡنَا فِيهَا ٱلسَّيۡرَۖ سِيرُواْ فِيهَا لَيَالِيَ وَأَيَّامًا ءَامِنِينَ","3624":"فَقَالُواْ رَبَّنَا بَٰعِدۡ بَيۡنَ أَسۡفَارِنَا وَظَلَمُوٓاْ أَنفُسَهُمۡ فَجَعَلۡنَٰهُمۡ أَحَادِيثَ وَمَزَّقۡنَٰهُمۡ كُلَّ مُمَزَّقٍۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّكُلِّ صَبَّارٖ شَكُورٖ","3625":"وَلَقَدۡ صَدَّقَ عَلَيۡهِمۡ إِبۡلِيسُ ظَنَّهُۥ فَٱتَّبَعُوهُ إِلَّا فَرِيقٗا مِّنَ ٱلۡمُؤۡمِنِينَ","3626":"وَمَا كَانَ لَهُۥ عَلَيۡهِم مِّن سُلۡطَٰنٍ إِلَّا لِنَعۡلَمَ مَن يُؤۡمِنُ بِٱلۡأٓخِرَةِ مِمَّنۡ هُوَ مِنۡهَا فِي شَكّٖۗ وَرَبُّكَ عَلَىٰ كُلِّ شَيۡءٍ حَفِيظٞ","3886":"وَقَالَ إِنِّي ذَاهِبٌ إِلَىٰ رَبِّي سَيَهۡدِينِ","3887":"رَبِّ هَبۡ لِي مِنَ ٱلصَّٰلِحِينَ","3888":"فَبَشَّرۡنَٰهُ بِغُلَٰمٍ حَلِيمٖ","3889":"فَلَمَّا بَلَغَ مَعَهُ ٱلسَّعۡيَ قَالَ يَٰبُنَيَّ إِنِّيٓ أَرَىٰ فِي ٱلۡمَنَامِ أَنِّيٓ أَذۡبَحُكَ فَٱنظُرۡ مَاذَا تَرَىٰۚ قَالَ يَٰٓأَبَتِ ٱفۡعَلۡ مَا تُؤۡمَرُۖ سَتَجِدُنِيٓ إِن شَآءَ ٱللَّهُ مِنَ ٱلصَّٰبِرِينَ","3890":"فَلَمَّآ أَسۡلَمَا وَتَلَّهُۥ لِلۡجَبِينِ","3893":"إِنَّ هَٰذَا لَهُوَ ٱلۡبَلَٰٓؤُاْ ٱلۡمُبِينُ","3995":"يَٰدَاوُۥدُ إِنَّا جَعَلۡنَٰكَ خَلِيفَةٗ فِي ٱلۡأَرۡضِ فَٱحۡكُم بَيۡنَ ٱلنَّاسِ بِٱلۡحَقِّ وَلَا تَتَّبِعِ ٱلۡهَوَىٰ فَيُضِلَّكَ عَن سَبِيلِ ٱللَّهِۚ إِنَّ ٱلَّذِينَ يَضِلُّونَ عَن سَبِيلِ ٱللَّهِ لَهُمۡ عَذَابٞ شَدِيدُۢ بِمَا نَسُواْ يَوۡمَ ٱلۡحِسَابِ","3999":"وَوَهَبۡنَا لِدَاوُۥدَ سُلَيۡمَٰنَۚ نِعۡمَ ٱلۡعَبۡدُ إِنَّهُۥٓ أَوَّابٌ","4000":"إِذۡ عُرِضَ عَلَيۡهِ بِٱلۡعَشِيِّ ٱلصَّٰفِنَٰتُ ٱلۡجِيَادُ","4001":"فَقَالَ إِنِّيٓ أَحۡبَبۡتُ حُبَّ ٱلۡخَيۡرِ عَن ذِكۡرِ رَبِّي حَتَّىٰ تَوَارَتۡ بِٱلۡحِجَابِ","4002":"رُدُّوهَا عَلَيَّۖ فَطَفِقَ مَسۡحَۢا بِٱلسُّوقِ وَٱلۡأَعۡنَاقِ","4003":"وَلَقَدۡ فَتَنَّا سُلَيۡمَٰنَ وَأَلۡقَيۡنَا عَلَىٰ كُرۡسِيِّهِۦ جَسَدٗا ثُمَّ أَنَابَ","4153":"۞ أَوَلَمۡ يَسِيرُواْ فِي ٱلۡأَرۡضِ فَيَنظُرُواْ كَيۡفَ كَانَ عَٰقِبَةُ ٱلَّذِينَ كَانُواْ مِن قَبۡلِهِمۡۚ كَانُواْ هُمۡ أَشَدَّ مِنۡهُمۡ قُوَّةٗ وَءَاثَارٗا فِي ٱلۡأَرۡضِ فَأَخَذَهُمُ ٱللَّهُ بِذُنُوبِهِمۡ وَمَا كَانَ لَهُم مِّنَ ٱللَّهِ مِن وَاقٖ","4155":"وَلَقَدۡ أَرۡسَلۡنَا مُوسَىٰ بِـَٔايَٰتِنَا وَسُلۡطَٰنٖ مُّبِينٍ","4156":"إِلَىٰ فِرۡعَوۡنَ وَهَٰمَٰنَ وَقَٰرُونَ فَقَالُواْ سَٰحِرٞ كَذَّابٞ","4157":"فَلَمَّا جَآءَهُم بِٱلۡحَقِّ مِنۡ عِندِنَا قَالُواْ ٱقۡتُلُوٓاْ أَبۡنَآءَ ٱلَّذِينَ ءَامَنُواْ مَعَهُۥ وَٱسۡتَحۡيُواْ نِسَآءَهُمۡۚ وَمَا كَيۡدُ ٱلۡكَٰفِرِينَ إِلَّا فِي ضَلَٰلٖ","4158":"وَقَالَ فِرۡعَوۡنُ ذَرُونِيٓ أَقۡتُلۡ مُوسَىٰ وَلۡيَدۡعُ رَبَّهُۥٓۖ إِنِّيٓ أَخَافُ أَن يُبَدِّلَ دِينَكُمۡ أَوۡ أَن يُظۡهِرَ فِي ٱلۡأَرۡضِ ٱلۡفَسَادَ","4159":"وَقَالَ مُوسَىٰٓ إِنِّي عُذۡتُ بِرَبِّي وَرَبِّكُم مِّن كُلِّ مُتَكَبِّرٖ لَّا يُؤۡمِنُ بِيَوۡمِ ٱلۡحِسَابِ","4163":"مِثۡلَ دَأۡبِ قَوۡمِ نُوحٖ وَعَادٖ وَثَمُودَ وَٱلَّذِينَ مِنۢ بَعۡدِهِمۡۚ وَمَا ٱللَّهُ يُرِيدُ ظُلۡمٗا لِّلۡعِبَادِ","4232":"فَأَمَّا عَادٞ فَٱسۡتَكۡبَرُواْ فِي ٱلۡأَرۡضِ بِغَيۡرِ ٱلۡحَقِّ وَقَالُواْ مَنۡ أَشَدُّ مِنَّا قُوَّةًۖ أَوَلَمۡ يَرَوۡاْ أَنَّ ٱللَّهَ ٱلَّذِي خَلَقَهُمۡ هُوَ أَشَدُّ مِنۡهُمۡ قُوَّةٗۖ وَكَانُواْ بِـَٔايَٰتِنَا يَجۡحَدُونَ","4233":"فَأَرۡسَلۡنَا عَلَيۡهِمۡ رِيحٗا صَرۡصَرٗا فِيٓ أَيَّامٖ نَّحِسَاتٖ لِّنُذِيقَهُمۡ عَذَابَ ٱلۡخِزۡيِ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۖ وَلَعَذَابُ ٱلۡأٓخِرَةِ أَخۡزَىٰۖ وَهُمۡ لَا يُنصَرُونَ","4370":"وَلَقَدۡ أَرۡسَلۡنَا مُوسَىٰ بِـَٔايَٰتِنَآ إِلَىٰ فِرۡعَوۡنَ وَمَلَإِيْهِۦ فَقَالَ إِنِّي رَسُولُ رَبِّ ٱلۡعَٰلَمِينَ","4371":"فَلَمَّا جَآءَهُم بِـَٔايَٰتِنَآ إِذَا هُم مِّنۡهَا يَضۡحَكُونَ","4372":"وَمَا نُرِيهِم مِّنۡ ءَايَةٍ إِلَّا هِيَ أَكۡبَرُ مِنۡ أُخۡتِهَاۖ وَأَخَذۡنَٰهُم بِٱلۡعَذَابِ لَعَلَّهُمۡ يَرۡجِعُونَ","4373":"وَقَالُواْ يَٰٓأَيُّهَ ٱلسَّاحِرُ ٱدۡعُ لَنَا رَبَّكَ بِمَا عَهِدَ عِندَكَ إِنَّنَا لَمُهۡتَدُونَ","4374":"فَلَمَّا كَشَفۡنَا عَنۡهُمُ ٱلۡعَذَابَ إِذَا هُمۡ يَنكُثُونَ","4375":"وَنَادَىٰ فِرۡعَوۡنُ فِي قَوۡمِهِۦ قَالَ يَٰقَوۡمِ أَلَيۡسَ لِي مُلۡكُ مِصۡرَ وَهَٰذِهِ ٱلۡأَنۡهَٰرُ تَجۡرِي مِن تَحۡتِيٓۚ أَفَلَا تُبۡصِرُونَ","4378":"فَٱسۡتَخَفَّ قَوۡمَهُۥ فَأَطَاعُوهُۚ إِنَّهُمۡ كَانُواْ قَوۡمٗا فَٰسِقِينَ","4530":"۞ وَٱذۡكُرۡ أَخَا عَادٍ إِذۡ أَنذَرَ قَوۡمَهُۥ بِٱلۡأَحۡقَافِ وَقَدۡ خَلَتِ ٱلنُّذُرُ مِنۢ بَيۡنِ يَدَيۡهِ وَمِنۡ خَلۡفِهِۦٓ أَلَّا تَعۡبُدُوٓاْ إِلَّا ٱللَّهَ إِنِّيٓ أَخَافُ عَلَيۡكُمۡ عَذَابَ يَوۡمٍ عَظِيمٖ","4531":"قَالُوٓاْ أَجِئۡتَنَا لِتَأۡفِكَنَا عَنۡ ءَالِهَتِنَا فَأۡتِنَا بِمَا تَعِدُنَآ إِن كُنتَ مِنَ ٱلصَّٰدِقِينَ","4532":"قَالَ إِنَّمَا ٱلۡعِلۡمُ عِندَ ٱللَّهِ وَأُبَلِّغُكُم مَّآ أُرۡسِلۡتُ بِهِۦ وَلَٰكِنِّيٓ أَرَىٰكُمۡ قَوۡمٗا تَجۡهَلُونَ","4533":"فَلَمَّا رَأَوۡهُ عَارِضٗا مُّسۡتَقۡبِلَ أَوۡدِيَتِهِمۡ قَالُواْ هَٰذَا عَارِضٞ مُّمۡطِرُنَاۚ بَلۡ هُوَ مَا ٱسۡتَعۡجَلۡتُم بِهِۦۖ رِيحٞ فِيهَا عَذَابٌ أَلِيمٞ","4534":"تُدَمِّرُ كُلَّ شَيۡءِۭ بِأَمۡرِ رَبِّهَا فَأَصۡبَحُواْ لَا يُرَىٰٓ إِلَّا مَسَٰكِنُهُمۡۚ كَذَٰلِكَ نَجۡزِي ٱلۡقَوۡمَ ٱلۡمُجۡرِمِينَ","4535":"وَلَقَدۡ مَكَّنَّٰهُمۡ فِيمَآ إِن مَّكَّنَّٰكُمۡ فِيهِ وَجَعَلۡنَا لَهُمۡ سَمۡعٗا وَأَبۡصَٰرٗا وَأَفۡـِٔدَةٗ فَمَآ أَغۡنَىٰ عَنۡهُمۡ سَمۡعُهُمۡ وَلَآ أَبۡصَٰرُهُمۡ وَلَآ أَفۡـِٔدَتُهُم مِّن شَيۡءٍ إِذۡ كَانُواْ يَجۡحَدُونَ بِـَٔايَٰتِ ٱللَّهِ وَحَاقَ بِهِم مَّا كَانُواْ بِهِۦ يَسۡتَهۡزِءُونَ","4868":"كَذَّبَتۡ ثَمُودُ بِٱلنُّذُرِ","4869":"فَقَالُوٓاْ أَبَشَرٗا مِّنَّا وَٰحِدٗا نَّتَّبِعُهُۥٓ إِنَّآ إِذٗا لَّفِي ضَلَٰلٖ وَسُعُرٍ","4870":"أَءُلۡقِيَ ٱلذِّكۡرُ عَلَيۡهِ مِنۢ بَيۡنِنَا بَلۡ هُوَ كَذَّابٌ أَشِرٞ","4871":"سَيَعۡلَمُونَ غَدٗا مَّنِ ٱلۡكَذَّابُ ٱلۡأَشِرُ","4872":"إِنَّا مُرۡسِلُواْ ٱلنَّاقَةِ فِتۡنَةٗ لَّهُمۡ فَٱرۡتَقِبۡهُمۡ وَٱصۡطَبِرۡ","5153":"قَدۡ كَانَتۡ لَكُمۡ أُسۡوَةٌ حَسَنَةٞ فِيٓ إِبۡرَٰهِيمَ وَٱلَّذِينَ مَعَهُۥٓ إِذۡ قَالُواْ لِقَوۡمِهِمۡ إِنَّا بُرَءَٰٓؤُاْ مِنكُمۡ وَمِمَّا تَعۡبُدُونَ مِن دُونِ ٱللَّهِ كَفَرۡنَا بِكُمۡ وَبَدَا بَيۡنَنَا وَبَيۡنَكُمُ ٱلۡعَدَٰوَةُ وَٱلۡبَغۡضَآءُ أَبَدًا حَتَّىٰ تُؤۡمِنُواْ بِٱللَّهِ وَحۡدَهُۥٓ إِلَّا قَوۡلَ إِبۡرَٰهِيمَ لِأَبِيهِ لَأَسۡتَغۡفِرَنَّ لَكَ وَمَآ أَمۡلِكُ لَكَ مِنَ ٱللَّهِ مِن شَيۡءٖۖ رَّبَّنَا عَلَيۡكَ تَوَكَّلۡنَا وَإِلَيۡكَ أَنَبۡنَا وَإِلَيۡكَ ٱلۡمَصِيرُ","5287":"إِنَّا بَلَوۡنَٰهُمۡ كَمَا بَلَوۡنَآ أَصۡحَٰبَ ٱلۡجَنَّةِ إِذۡ أَقۡسَمُواْ لَيَصۡرِمُنَّهَا مُصۡبِحِينَ","5288":"وَلَا يَسۡتَثۡنُونَ","5289":"فَطَافَ عَلَيۡهَا طَآئِفٞ مِّن رَّبِّكَ وَهُمۡ نَآئِمُونَ","5290":"فَأَصۡبَحَتۡ كَٱلصَّرِيمِ","5291":"فَتَنَادَوۡاْ مُصۡبِحِينَ","5292":"أَنِ ٱغۡدُواْ عَلَىٰ حَرۡثِكُمۡ إِن كُنتُمۡ صَٰرِمِينَ","5293":"فَٱنطَلَقُواْ وَهُمۡ يَتَخَٰفَتُونَ","5294":"أَن لَّا يَدۡخُلَنَّهَا ٱلۡيَوۡمَ عَلَيۡكُم مِّسۡكِينٞ","5295":"وَغَدَوۡاْ عَلَىٰ حَرۡدٖ قَٰدِرِينَ","5296":"فَلَمَّا رَأَوۡهَا قَالُوٓاْ إِنَّا لَضَآلُّونَ","5297":"بَلۡ نَحۡنُ مَحۡرُومُونَ","5298":"قَالَ أَوۡسَطُهُمۡ أَلَمۡ أَقُل لَّكُمۡ لَوۡلَا تُسَبِّحُونَ","5299":"قَالُواْ سُبۡحَٰنَ رَبِّنَآ إِنَّا كُنَّا ظَٰلِمِينَ","5300":"فَأَقۡبَلَ بَعۡضُهُمۡ عَلَىٰ بَعۡضٖ يَتَلَٰوَمُونَ","5303":"كَذَٰلِكَ ٱلۡعَذَابُۖ وَلَعَذَابُ ٱلۡأٓخِرَةِ أَكۡبَرُۚ لَوۡ كَانُواْ يَعۡلَمُونَ","5328":"وَأَمَّا عَادٞ فَأُهۡلِكُواْ بِرِيحٖ صَرۡصَرٍ عَاتِيَةٖ","5329":"سَخَّرَهَا عَلَيۡهِمۡ سَبۡعَ لَيَالٖ وَثَمَٰنِيَةَ أَيَّامٍ حُسُومٗاۖ فَتَرَى ٱلۡقَوۡمَ فِيهَا صَرۡعَىٰ كَأَنَّهُمۡ أَعۡجَازُ نَخۡلٍ خَاوِيَةٖ","5330":"فَهَلۡ تَرَىٰ لَهُم مِّنۢ بَاقِيَةٖ","5423":"قَالَ رَبِّ إِنِّي دَعَوۡتُ قَوۡمِي لَيۡلٗا وَنَهَارٗا","5424":"فَلَمۡ يَزِدۡهُمۡ دُعَآءِيٓ إِلَّا فِرَارٗا","5425":"وَإِنِّي كُلَّمَا دَعَوۡتُهُمۡ لِتَغۡفِرَ لَهُمۡ جَعَلُوٓاْ أَصَٰبِعَهُمۡ فِيٓ ءَاذَانِهِمۡ وَٱسۡتَغۡشَوۡاْ ثِيَابَهُمۡ وَأَصَرُّواْ وَٱسۡتَكۡبَرُواْ ٱسۡتِكۡبَارٗا","5426":"ثُمَّ إِنِّي دَعَوۡتُهُمۡ جِهَارٗا","5427":"ثُمَّ إِنِّيٓ أَعۡلَنتُ لَهُمۡ وَأَسۡرَرۡتُ لَهُمۡ إِسۡرَارٗا","6053":"كَذَّبَتۡ ثَمُودُ بِطَغۡوَىٰهَآ","6054":"إِذِ ٱنۢبَعَثَ أَشۡقَىٰهَا","6055":"فَقَالَ لَهُمۡ رَسُولُ ٱللَّهِ نَاقَةَ ٱللَّهِ وَسُقۡيَٰهَا","6056":"فَكَذَّبُوهُ فَعَقَرُوهَا فَدَمۡدَمَ عَلَيۡهِمۡ رَبُّهُم بِذَنۢبِهِمۡ فَسَوَّىٰهَا","6057":"وَلَا يَخَافُ عُقۡبَٰهَا"},"nay":367,"nq":138,"nls":114};
